/* Main CSS entrypoint
   Import order:
   1) core tokens/base
   2) public layout + public pages
   3) global utilities
   4) shared components
   5) admin/dashboard/PageBuilder
*/

/* Shared design tokens */
:root,
:root[data-theme="light"] {
  color-scheme: light;

  --madar-bg: var(--app-bg);
  --madar-navy: #162033;
  --madar-navy-dark: #101317;
  --madar-red: var(--theme-primary);
  --madar-red-dark: var(--theme-primary-hover);
  --madar-red-deep: #6f241b;
  --madar-cream: #f4f0e8;
  --madar-gradient: var(--theme-gradient);
  --madar-gradient-hover: var(--theme-gradient-hover);
  --madar-button-shadow: 0 12px 24px rgba(var(--theme-primary-rgb), 0.18);
  --madar-button-shadow-hover: 0 16px 32px rgba(var(--theme-primary-rgb), 0.24);

  /* Shared application surfaces. Structural layout uses --app-bg; white is
     reserved for compact controls, intentional cards, previews, and content. */
  --app-bg: #f4f0e8;
  --surface-1: #fffdfa;
  --surface-2: #f8f4ed;
  --surface-3: var(--surface-2);
  --border-subtle: #ddd6ca;
  --border-strong: #c8bfb1;
  --border-control: #6f7787;
  --text-primary: #162033;
  --text-secondary: #465066;
  --text-muted: var(--text-secondary);
  --accent: #852c21;

  --theme-bg: var(--app-bg);
  --theme-bg-soft: var(--surface-2);
  --theme-surface: var(--surface-1);
  --theme-surface-elevated: var(--theme-surface-2);
  --theme-surface-2: var(--surface-2);
  --theme-surface-3: var(--surface-2);
  --theme-border: var(--border-subtle);
  --theme-border-strong: var(--border-strong);
  --theme-text: var(--text-primary);
  --theme-text-secondary: var(--theme-text-soft);
  --theme-text-soft: var(--text-secondary);
  --theme-text-muted: var(--text-muted);
  --theme-text-inverse: #ffffff;
  --theme-text-inverse-rgb: 255, 255, 255;
  --theme-black-rgb: 0, 0, 0;
  --theme-paper-surface: var(--surface-1);
  --theme-paper-surface-soft: var(--surface-2);
  --theme-paper-text: var(--text-primary);
  --theme-paper-text-soft: var(--text-secondary);
  --theme-paper-border: var(--border-subtle);
  --theme-primary: #852C21;
  --theme-primary-hover: #6f241b;
  --theme-primary-soft: rgba(133, 44, 33, 0.1);
  --theme-primary-rgb: 133, 44, 33;
  --accent-text: var(--theme-primary);
  --heading-accent: var(--theme-primary);
  --danger-action: var(--status-danger-text);
  --focus-indicator: var(--theme-primary);
  --status-success-text: #365849;
  --status-warning-text: var(--text-primary);
  --status-danger-text: #b42318;
  --theme-secondary: #6b7654;
  --theme-secondary-soft: rgba(107, 118, 84, 0.12);
  --theme-secondary-rgb: 107, 118, 84;
  --theme-info: #4a5470;
  --theme-info-rgb: 74, 84, 112;
  --theme-success: #3e8c6b;
  --theme-success-rgb: 62, 140, 107;
  --theme-warning: #b8842f;
  --theme-warning-rgb: 184, 132, 47;
  --theme-danger: #c4453a;
  --theme-danger-rgb: 196, 69, 58;
  --theme-gradient: var(--theme-primary);
  --theme-gradient-hover: var(--theme-primary-hover);
  --theme-text-gradient: var(--theme-primary);
  --theme-shadow: 0 18px 44px rgba(27, 42, 74, 0.12);
  --theme-shadow-rgb: 27, 42, 74;
  --theme-footer-bg: var(--surface-1);
  --theme-footer-bg-soft: var(--surface-2);
  --theme-footer-surface: var(--surface-2);
  --theme-footer-border: var(--border-subtle);
  --theme-footer-text: var(--text-primary);
  --theme-footer-text-soft: var(--text-secondary);
  --theme-footer-text-muted: var(--text-muted);

  /* Semantic app color aliases. Keep --theme-* as the compatibility layer. */
  --color-bg: var(--theme-bg);
  --color-bg-soft: var(--theme-bg-soft);
  --color-surface: var(--theme-surface);
  --color-surface-soft: var(--theme-surface-2);
  --color-surface-muted: var(--theme-surface-3);
  --color-border: var(--theme-border);
  --color-border-strong: var(--theme-border-strong);
  --color-border-control: var(--border-control);
  --color-text: var(--theme-text);
  --color-text-soft: var(--theme-text-soft);
  --color-text-muted: var(--theme-text-muted);
  --color-text-inverse: var(--theme-text-inverse);
  --color-primary: var(--theme-primary);
  --color-primary-hover: var(--theme-primary-hover);
  --color-primary-soft: var(--theme-primary-soft);
  --color-accent-text: var(--accent-text);
  --color-heading-accent: var(--heading-accent);
  --color-danger-action: var(--danger-action);
  --color-focus-indicator: var(--focus-indicator);
  --color-disabled-bg: var(--surface-2);
  --color-disabled-border: var(--border-control);
  --color-disabled-text: var(--text-muted);
  --color-status-success-text: var(--status-success-text);
  --color-status-warning-text: var(--status-warning-text);
  --color-status-danger-text: var(--status-danger-text);
  --color-secondary: var(--theme-secondary);
  --color-secondary-soft: var(--theme-secondary-soft);
  --color-info: var(--theme-info);
  --color-success: var(--theme-success);
  --color-warning: var(--theme-warning);
  --color-danger: var(--theme-danger);
  --color-focus: rgba(var(--theme-primary-rgb), 0.16);
  --app-surface-alpha: color-mix(in srgb, var(--theme-surface) 84%, transparent);
  --app-focus-ring: 0 0 0 4px var(--color-focus);
  --app-shadow-sm: 0 6px 18px rgba(var(--theme-shadow-rgb), 0.055);
  --app-shadow-md: 0 12px 32px rgba(var(--theme-shadow-rgb), 0.075);
  --app-primary-shadow: 0 12px 28px rgba(var(--theme-primary-rgb), 0.18);
  --app-card-shadow: 0 10px 28px rgba(var(--theme-shadow-rgb), 0.07);
  --app-card-shadow-hover: 0 14px 36px rgba(var(--theme-shadow-rgb), 0.1);
  --app-header-shadow: 0 6px 20px rgba(var(--theme-shadow-rgb), 0.05);
  --app-panel-shadow: 0 14px 38px rgba(var(--theme-shadow-rgb), 0.075);
  --app-modal-shadow: 0 28px 80px rgba(var(--theme-shadow-rgb), 0.18);
  --app-backdrop: rgba(var(--theme-shadow-rgb), 0.58);
  --app-chrome-translucent: color-mix(in srgb, var(--theme-surface) 92%, transparent);
  --app-success-strong: #4ade80;
  --app-success-strong-rgb: 74, 222, 128;
  --builder-chrome-bg: var(--app-bg);
  --builder-chrome-surface: var(--surface-1);
  --builder-chrome-surface-raised: var(--surface-2);
  --builder-chrome-surface-muted: var(--surface-2);
  --app-control-shadow: inset 0 1px 0 rgba(var(--theme-text-inverse-rgb), 0.72);
  --builder-chrome-border: var(--border-subtle);
  --builder-chrome-shadow: var(--app-shadow-sm);
  --builder-bg: var(--builder-chrome-bg);
  --builder-surface-1: var(--builder-chrome-surface);
  --builder-surface-2: var(--builder-chrome-surface-raised);
  --builder-surface-3: var(--builder-chrome-surface-muted);
  --builder-border: var(--builder-chrome-border);
  --builder-border-strong: color-mix(in srgb, var(--theme-border) 82%, transparent);
  --builder-hover: var(--surface-2);
  --builder-selected: color-mix(in srgb, var(--surface-2) 90%, var(--accent));
  --builder-text: var(--theme-text);
  --builder-text-muted: var(--theme-text-soft);
  /* Backward-compatible aliases for builder modules migrated incrementally. */
  --builder-neutral-bg: var(--builder-bg);
  --builder-neutral-surface: var(--builder-surface-1);
  --builder-neutral-surface-raised: var(--builder-surface-2);
  --builder-neutral-surface-muted: var(--builder-surface-3);
  --builder-neutral-hover: color-mix(in srgb, var(--builder-surface-2) 95%, var(--builder-text));
  --builder-neutral-selected: color-mix(in srgb, var(--builder-surface-2) 93%, var(--builder-text));
}

:root[data-theme="dark"] {
  color-scheme: dark;

  /* Shared neutral dark palette. All dark application themes resolve through
     these primitives so route shells cannot drift back toward navy/slate. */
  --app-bg: #101317;
  --surface-1: #181d23;
  --surface-2: #232a32;
  --surface-3: var(--surface-2);
  --border-subtle: rgba(255, 255, 255, 0.10);
  --border-strong: rgba(255, 255, 255, 0.17);
  --border-control: #9ca6b2;
  --text-primary: #f4f6f8;
  --text-secondary: #c8ced6;
  --text-muted: #9ca6b2;
  --accent: #852c21;

  --madar-bg: var(--app-bg);
  --madar-navy: var(--surface-3);
  --madar-navy-dark: var(--app-bg);
  --madar-cream: var(--surface-1);

  --theme-bg: var(--app-bg);
  --theme-bg-soft: var(--surface-1);
  --theme-surface: var(--surface-1);
  --theme-surface-elevated: var(--theme-surface-2);
  --theme-surface-2: var(--surface-2);
  --theme-surface-3: var(--surface-2);
  --theme-border: var(--border-subtle);
  --theme-border-strong: var(--border-strong);
  --theme-text: var(--text-primary);
  --theme-text-secondary: var(--theme-text-soft);
  --theme-text-soft: var(--text-secondary);
  --theme-text-muted: var(--text-muted);
  --theme-text-inverse: #ffffff;
  --theme-text-inverse-rgb: 255, 255, 255;
  --theme-black-rgb: 0, 0, 0;
  --theme-paper-surface: var(--surface-1);
  --theme-paper-surface-soft: var(--surface-2);
  --theme-paper-text: var(--text-primary);
  --theme-paper-text-soft: var(--text-secondary);
  --theme-paper-border: var(--border-subtle);
  --theme-primary: #c94730;
  --theme-primary-hover: #c94730;
  --theme-primary-soft: rgba(196, 69, 58, 0.14);
  --theme-primary-rgb: 201, 71, 48;
  --accent-text: var(--text-primary);
  --heading-accent: var(--theme-danger);
  --danger-action: var(--theme-danger);
  --focus-indicator: var(--theme-danger);
  --status-success-text: var(--theme-success);
  --status-warning-text: var(--theme-warning);
  --status-danger-text: var(--text-primary);
  --theme-secondary: #8c9a6b;
  --theme-secondary-soft: rgba(140, 154, 107, 0.14);
  --theme-secondary-rgb: 140, 154, 107;
  --theme-info: var(--text-muted);
  --theme-info-rgb: 167, 176, 189;
  --theme-success: #4fa37d;
  --theme-success-rgb: 79, 163, 125;
  --theme-warning: #d9a441;
  --theme-warning-rgb: 217, 164, 65;
  --theme-danger: #e5564b;
  --theme-danger-rgb: 229, 86, 75;
  --theme-gradient: var(--theme-primary);
  --theme-gradient-hover: var(--theme-primary-hover);
  --theme-text-gradient: var(--theme-primary-hover);
  --theme-shadow: 0 22px 60px rgba(0, 0, 0, 0.38);
  --theme-shadow-rgb: 0, 0, 0;
  --theme-footer-bg: var(--app-bg);
  --theme-footer-bg-soft: var(--surface-1);
  --theme-footer-surface: rgba(255, 255, 255, 0.07);
  --theme-footer-border: rgba(255, 255, 255, 0.12);
  --theme-footer-text: var(--text-primary);
  --theme-footer-text-soft: var(--text-secondary);
  --theme-footer-text-muted: var(--text-muted);

  --color-bg: var(--theme-bg);
  --color-bg-soft: var(--theme-bg-soft);
  --color-surface: var(--theme-surface);
  --color-surface-soft: var(--theme-surface-2);
  --color-surface-muted: var(--theme-surface-3);
  --color-border: var(--theme-border);
  --color-border-strong: var(--theme-border-strong);
  --color-border-control: var(--border-control);
  --color-text: var(--theme-text);
  --color-text-soft: var(--theme-text-soft);
  --color-text-muted: var(--theme-text-muted);
  --color-text-inverse: var(--theme-text-inverse);
  --color-primary: var(--theme-primary);
  --color-primary-hover: var(--theme-primary-hover);
  --color-primary-soft: var(--theme-primary-soft);
  --color-accent-text: var(--accent-text);
  --color-heading-accent: var(--heading-accent);
  --color-danger-action: var(--danger-action);
  --color-focus-indicator: var(--focus-indicator);
  --color-disabled-bg: var(--surface-2);
  --color-disabled-border: var(--border-control);
  --color-disabled-text: var(--text-muted);
  --color-status-success-text: var(--status-success-text);
  --color-status-warning-text: var(--status-warning-text);
  --color-status-danger-text: var(--status-danger-text);
  --color-secondary: var(--theme-secondary);
  --color-secondary-soft: var(--theme-secondary-soft);
  --color-info: var(--theme-info);
  --color-success: var(--theme-success);
  --color-warning: var(--theme-warning);
  --color-danger: var(--theme-danger);
  --color-focus: rgba(var(--theme-primary-rgb), 0.22);
  --app-surface-alpha: color-mix(in srgb, var(--theme-surface) 86%, transparent);
  --app-focus-ring: 0 0 0 4px var(--color-focus);
  --app-shadow-sm: 0 14px 34px rgba(var(--theme-shadow-rgb), 0.24);
  --app-shadow-md: 0 22px 56px rgba(var(--theme-shadow-rgb), 0.3);
  --app-primary-shadow: 0 14px 30px rgba(var(--theme-primary-rgb), 0.2);
  --app-card-shadow: 0 22px 58px rgba(var(--theme-shadow-rgb), 0.34);
  --app-card-shadow-hover: 0 26px 68px rgba(var(--theme-shadow-rgb), 0.42);
  --app-header-shadow: 0 14px 36px rgba(var(--theme-shadow-rgb), 0.28);
  --app-panel-shadow: 0 22px 56px rgba(var(--theme-shadow-rgb), 0.28);
  --app-modal-shadow: 0 28px 80px rgba(var(--theme-shadow-rgb), 0.26);
  --app-backdrop: rgba(var(--theme-shadow-rgb), 0.58);
  --app-chrome-translucent: color-mix(in srgb, var(--theme-surface) 90%, transparent);
  --app-success-strong: #4ade80;
  --app-success-strong-rgb: 74, 222, 128;
  --app-control-shadow: none;
  --builder-chrome-bg: var(--app-bg);
  --builder-chrome-surface: var(--surface-1);
  --builder-chrome-surface-raised: var(--surface-2);
  --builder-chrome-surface-muted: var(--surface-2);
  --builder-chrome-border: var(--border-subtle);
  --builder-chrome-shadow: 0 10px 22px rgba(var(--theme-black-rgb), 0.14);
  --builder-bg: var(--app-bg);
  --builder-surface-1: var(--surface-1);
  --builder-surface-2: var(--surface-2);
  --builder-surface-3: var(--surface-2);
  --builder-border: var(--border-subtle);
  --builder-border-strong: var(--border-strong);
  --builder-hover: rgba(255, 255, 255, 0.05);
  --builder-selected: rgba(255, 255, 255, 0.075);
  --builder-text: var(--text-primary);
  --builder-text-muted: var(--text-muted);
  --builder-neutral-bg: var(--builder-bg);
  --builder-neutral-surface: var(--builder-surface-1);
  --builder-neutral-surface-raised: var(--builder-surface-2);
  --builder-neutral-surface-muted: var(--builder-surface-3);
  --builder-neutral-hover: var(--builder-surface-3);
  --builder-neutral-selected: color-mix(in srgb, var(--builder-surface-3) 92%, var(--builder-text));
}

/* ============================================================
   DARK ADMIN TOKENS
   These are used by dashboard.css and PageBuilder.css.
   The public website pages can still use their own light styling.
   ============================================================ */
:root {
  --admin-bg: var(--theme-bg);
  --admin-surface: var(--theme-surface);
  --admin-surface-2: var(--theme-surface-2);
  --admin-surface-3: var(--theme-surface-3);
  --admin-border: var(--theme-border);
  --admin-border-strong: var(--theme-border-strong);
  --admin-text: var(--theme-text);
  --admin-muted: var(--theme-text-muted);
  --admin-soft: var(--theme-text-soft);
  --admin-cyan: var(--theme-info);
  --admin-navy: var(--madar-navy);
  --admin-red: var(--theme-primary);
  --admin-red-bright: var(--theme-primary-hover);
  --admin-danger: var(--theme-danger);
  --admin-gradient: var(--theme-gradient);
  --admin-shadow: var(--theme-shadow);
  --admin-focus-ring: var(--app-focus-ring);
  --admin-surface-alpha: var(--app-surface-alpha);
  --admin-success-strong: var(--app-success-strong);
}

/* UI CONSISTENCY STRUCTURAL TOKENS */
/* Geometry and typography are deliberately theme-independent. */
:root {
  --color-divider: var(--color-border-strong);
  --color-bg-secondary: var(--theme-bg-soft);
  --color-surface-elevated: var(--theme-surface-elevated);
  --font-family-base: Inter, "IBM Plex Sans Arabic", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --type-display-size: 36px; --type-display-line: 44px;
  --type-h1-size: 32px; --type-h1-line: 40px;
  --type-h2-size: 28px; --type-h2-line: 36px;
  --type-h3-size: 24px; --type-h3-line: 32px;
  --type-h4-size: 20px; --type-h4-line: 28px;
  --type-body-lg-size: 18px; --type-body-lg-line: 28px;
  --type-body-size: 16px; --type-body-line: 24px;
  --type-small-size: 14px; --type-small-line: 20px;
  --type-caption-size: 12px; --type-caption-line: 16px;
  --weight-regular: 400; --weight-medium: 500; --weight-semibold: 600; --weight-bold: 700;
  --space-1: 4px; --space-2: 8px; --space-3: 12px; --space-4: 16px; --space-5: 20px;
  --space-6: 24px; --space-8: 32px; --space-10: 40px; --space-12: 48px; --space-16: 64px; --space-20: 80px;
  --radius-small: 6px; --radius-default: 8px; --radius-card: 12px; --radius-large: 16px; --radius-pill: 9999px;
  --app-radius-control: var(--radius-default); --app-radius-card: var(--radius-card); --app-radius-panel: var(--radius-large);
  --control-height-sm: 36px; --control-height: 44px; --control-height-lg: 48px;
  --icon-size-sm: 16px; --icon-size: 20px; --icon-size-lg: 24px; --icon-size-feature: 32px;
  --layout-max-width: 1440px; --content-max-width: 800px; --intro-max-width: 720px;
  --page-gutter: 48px; --page-top-space: 64px; --section-space: 80px; --app-header-height: 88px;
}
@media (max-width: 1024px) {
  :root { --page-gutter: 32px; --page-top-space: 48px; --section-space: 64px; --app-header-height: 80px; }
}
@media (max-width: 620px) {
  :root {
    --type-display-size: 32px; --type-display-line: 40px;
    --type-h1-size: 28px; --type-h1-line: 36px;
    --type-h2-size: 24px; --type-h2-line: 32px;
    --type-h3-size: 20px; --type-h3-line: 28px;
    --type-h4-size: 18px; --type-h4-line: 26px;
    --type-body-lg-size: 16px; --type-body-lg-line: 24px;
    --page-gutter: 20px; --page-top-space: 32px; --section-space: 48px; --app-header-height: 72px;
  }
}
/* Shared compatibility aliases for the centralized application design system. */
:root {
  --color-primary: var(--theme-primary);
  --color-primary-hover: var(--theme-primary-hover);
  --color-secondary: var(--theme-secondary);
  --color-accent: var(--theme-info);
  --color-background: var(--theme-bg);
  --color-background-soft: var(--theme-bg-soft);
  --color-surface: var(--theme-surface);
  --color-surface-muted: var(--theme-surface-2);
  --color-card: var(--theme-surface);
  --color-text-main: var(--theme-text);
  --color-text-soft: var(--theme-text-soft);
  --color-text-muted: var(--theme-text-muted);
  --color-text-inverse: var(--theme-text-inverse);
  --color-border: var(--theme-border);
  --color-border-strong: var(--theme-border-strong);
  --font-main: var(--font-family-base);
  --font-heading: var(--font-family-base);
  --font-size-xs: var(--type-caption-size);
  --font-size-sm: var(--type-small-size);
  --font-size-md: var(--type-body-size);
  --font-size-lg: var(--type-body-lg-size);
  --font-size-xl: var(--type-h3-size);
  --font-size-2xl: var(--type-h1-size);
  --font-size-3xl: var(--type-display-size);
  --font-weight-regular: var(--weight-regular);
  --font-weight-medium: var(--weight-medium);
  --font-weight-semibold: var(--weight-semibold);
  --font-weight-bold: var(--weight-bold);
  --font-weight-black: var(--weight-bold);
  --line-height-tight: 1.25;
  --line-height-base: 1.5;
  --line-height-relaxed: 1.75;
  --space-xs: var(--space-1);
  --space-sm: var(--space-2);
  --space-md: var(--space-4);
  --space-lg: var(--space-6);
  --space-xl: var(--space-8);
  --space-2xl: var(--space-12);
  --space-3xl: var(--space-20);
  --radius-sm: var(--radius-small);
  --radius-md: var(--radius-default);
