  --container-lg: var(--layout-max-width);
  --container-xl: var(--layout-max-width);
  --breakpoint-sm: 620px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --transition-fast: 0.2s ease;
  --transition-normal: 0.3s ease;
  --z-header: 5000;
  --z-overlay: 5800;
  --z-modal: 5900;
}
/* Application reset and root background contract. */
*,
*::before,
*::after { box-sizing: border-box; }

html,
body,
#root {
  width: 100%;
  min-height: 100%;
  margin: 0;
  padding: 0;
}

html { background: var(--color-bg); }
body {
  min-height: 100vh;
  overflow-x: hidden;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family-base);
  font-size: var(--type-body-size);
  line-height: var(--type-body-line);
  font-weight: var(--weight-regular);
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

#root { min-height: 100vh; background: var(--color-bg); }
button,
input,
select,
textarea { font: inherit; }
button { cursor: pointer; }
a { color: inherit; text-decoration: none; }
img,
svg,
video,
canvas { max-width: 100%; }
/* Core application theme contract.
   Normal application UI has exactly three background roles:
   app background, primary surface, and nested/elevated surface.
   Component styles consume these roles through the aliases in tokens.css. */

html,
body,
#root,
.app-shell {
  background-color: var(--app-bg);
  color: var(--text-primary);
}

/* Shared semantic primitives for new and migrated UI. */
.app-background,
.app-layout,
.app-page,
.app-workspace {
  background-color: var(--app-bg);
  color: var(--text-primary);
}

.app-surface,
.app-panel,
.app-card,
.app-dialog {
  background-color: var(--surface-1);
  border: 1px solid var(--border-subtle);
  border-color: var(--border-subtle);
  border-radius: var(--app-radius-card);
  color: var(--text-primary);
  box-shadow: var(--app-card-shadow);
}

.app-surface-nested,
.app-control,
.app-row {
  background-color: var(--surface-2);
  border: 1px solid var(--border-subtle);
  border-color: var(--border-subtle);
  border-radius: var(--app-radius-control);
  color: var(--text-primary);
}

:where(input, select, textarea) {
  background-color: var(--surface-2);
  border-color: var(--border-subtle);
  color: var(--text-primary);
}

:root:not([data-theme="dark"]) :where(input, select, textarea) {
  box-shadow: var(--app-control-shadow);
}

:where(input, select, textarea)::placeholder {
  color: var(--text-muted);
  opacity: 1;
}

:where(input, select, textarea) {
  border-color: var(--border-control);
}

:where(input, select, textarea):disabled {
  background-color: var(--color-disabled-bg);
  border-color: var(--color-disabled-border);
  color: var(--color-disabled-text);
  opacity: 1;
}

body :is(a, button, input, select, textarea, summary, [tabindex]):focus-visible {
  outline: 2px solid var(--color-focus-indicator);
  outline-offset: 2px;
}

:where(hr, .divider) {
  border-color: var(--border-subtle);
}

/* Explicit authored-output boundaries own --theme-* / --form-theme-* values
   and are intentionally outside the application surface contract. */
.builder-form-preview-page,
.page-builder .builder-canvas,
.tenant-site-runtime {
  isolation: isolate;
}

/* ============================================================
   HEADER
   ============================================================ */

.site-header,
.site-header * {
  box-sizing: border-box;
}

.site-header {
  --header-height: 104px;
  width: 100%;
  max-width: 100vw;
  min-height: var(--header-height);
  padding: 0 32px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 32px;
  position: sticky;
  top: 0;
  z-index: 5000;
  isolation: isolate;
  overflow: visible;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--theme-surface) 98%, transparent),
    color-mix(in srgb, var(--theme-surface) 94%, transparent)
  );
  border-bottom: 1px solid var(--theme-border);
  box-shadow:
    0 10px 28px rgba(var(--theme-shadow-rgb), 0.055),
    0 1px 0 color-mix(in srgb, var(--theme-surface) 85%, transparent) inset;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

/* ============================================================
   BRAND
   ============================================================ */

.brand {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 16px;
  justify-self: start;
  text-decoration: none;
}

.logo {
  width: 88px;
  height: 88px;
  flex-shrink: 0;
  object-fit: contain;
  display: block;
  filter: drop-shadow(0 12px 22px rgba(var(--theme-shadow-rgb), 0.18));
}

.brand-name {
  min-width: 0;
  margin: 0;
  color: var(--theme-text);
  font-size: 20px;
  font-weight: 900;
  letter-spacing: -0.035em;
  line-height: 1;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
  white-space: nowrap;
}

/* ============================================================
   DESKTOP NAV
   ============================================================ */

.nav-menu {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(24px, 3.2vw, 54px);
  justify-self: center;
}

.nav-menu a {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 40px;
  color: var(--theme-text);
  font-size: 17px;
  font-weight: 800;
  text-decoration: none;
  white-space: nowrap;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
  border-radius: 999px;
  outline: none;
  transition:
    color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease;
}

.nav-menu a::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 4px;
  width: 0;
  height: 2px;
  border-radius: 999px;
  background: var(--theme-primary);
  box-shadow: 0 0 12px rgba(var(--theme-primary-rgb), 0.28);
  transform: translateX(-50%);
  transition: width 0.22s ease;
}

.nav-menu a:hover,
.nav-menu a.active {
  color: var(--color-accent-text);
}

.nav-menu a:hover::after,
.nav-menu a.active::after {
  width: 100%;
}

.nav-menu a:focus-visible {
  color: var(--color-accent-text);
  background: rgba(var(--theme-primary-rgb), 0.075);
  box-shadow: 0 0 0 4px rgba(var(--theme-primary-rgb), 0.08);
}

/* ============================================================
   HEADER RIGHT
   ============================================================ */

.header-right {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  justify-self: end;
}

/* ============================================================
   AUTH BUTTONS
   ============================================================ */

.btn-login,
.btn-signup {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 9px 20px;
  border-radius: 12px;
  font-size: 15px;
  font-weight: 850;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.btn-login {
  color: var(--theme-text);
  background: color-mix(in srgb, var(--theme-surface) 80%, transparent);
  border: 1.5px solid var(--theme-border);
}

.btn-login:hover {
  color: var(--color-accent-text);
  border-color: rgba(var(--theme-primary-rgb), 0.42);
  background: rgba(var(--theme-primary-rgb), 0.045);
  transform: translateY(-1px);
}

.btn-signup,
.site-header .btn-signup {
  color: var(--theme-text-inverse);
  background: var(--theme-gradient);
  border: 1.5px solid rgba(var(--theme-primary-rgb), 0.32);
  box-shadow:
    0 14px 28px rgba(var(--theme-primary-rgb), 0.24),
    inset 0 1px 0 color-mix(in srgb, var(--theme-text-inverse) 16%, transparent);
}

.btn-signup:hover {
  color: var(--theme-text-inverse);
  background: var(--theme-gradient-hover);
  transform: translateY(-1px);
  box-shadow:
    0 18px 36px rgba(var(--theme-primary-rgb), 0.32),
    0 0 0 4px rgba(var(--theme-primary-rgb), 0.08);
}

/* ============================================================
   LANGUAGE SWITCHER
   ============================================================ */

.lang-switcher {
  position: relative;
}

.lang-toggle {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 14px;
  border: 1.5px solid var(--theme-border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--theme-surface) 80%, transparent);
  color: var(--theme-text);
  font-size: 14px;
  font-weight: 850;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
  cursor: pointer;
  white-space: nowrap;
  transition:
    border-color 0.2s ease,
    color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease;
}

.lang-toggle:hover {
  border-color: rgba(var(--theme-primary-rgb), 0.42);
  color: var(--color-accent-text);
  background: rgba(var(--theme-primary-rgb), 0.045);
}

.lang-toggle:focus-visible {
  outline: none;
  box-shadow: 0 0 0 4px rgba(var(--theme-primary-rgb), 0.08);
}

.lang-chevron {
  transition: transform 0.2s ease;
  flex-shrink: 0;
}

.lang-chevron.open {
  transform: rotate(180deg);
}

.lang-dropdown {
  position: absolute;
  top: calc(100% + 10px);
  right: 0;
  min-width: 104px;
  padding: 7px;
  margin: 0;
  list-style: none;
  z-index: 5400;
  background: color-mix(in srgb, var(--theme-surface) 98%, transparent);
  border: 1px solid var(--theme-border);
  border-radius: 14px;
  box-shadow:
    0 18px 44px rgba(var(--theme-shadow-rgb), 0.14),
    0 1px 0 color-mix(in srgb, var(--theme-surface) 90%, transparent) inset;
  transform-origin: top right;
  animation: dropdownIn 0.15s ease;
}

@keyframes dropdownIn {
  from {
    opacity: 0;
    transform: scaleY(0.92) translateY(-4px);
  }

  to {
    opacity: 1;
    transform: scaleY(1) translateY(0);
  }
}

.lang-dropdown li {
  margin: 0;
  padding: 0;
}

.lang-dropdown button {
  display: block;
  width: 100%;
  padding: 9px 12px;
  background: transparent;
  border: none;
  border-radius: 10px;
  color: var(--theme-text);
  font-size: 14px;
  font-weight: 800;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
  text-align: center;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.lang-dropdown button:hover,
.lang-dropdown button.active {
  background: rgba(var(--theme-primary-rgb), 0.075);
  color: var(--color-accent-text);
}

/* ============================================================
   HAMBURGER
   ============================================================ */

.hamburger {
  display: none;
  width: 48px;
  height: 48px;
  padding: 0;
  border: 0;
  border-radius: 16px;
  background: var(--theme-gradient);
  color: var(--theme-text-inverse);
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  position: relative;
  z-index: 5600;
  box-shadow:
    0 14px 30px rgba(var(--theme-primary-rgb), 0.26),
    inset 0 1px 0 var(--theme-border);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.hamburger:hover {
  transform: translateY(-1px);
  background: var(--theme-gradient-hover);
  box-shadow:
    0 18px 38px rgba(var(--theme-primary-rgb), 0.34),
    0 0 0 4px rgba(var(--theme-primary-rgb), 0.08);
}

.hamburger span {
  width: 22px;
  height: 2px;
  border-radius: 999px;
  background: var(--theme-text-inverse);
  transition:
    transform 0.22s ease,
    opacity 0.18s ease;
}

.hamburger.open span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.hamburger.open span:nth-child(2) {
  opacity: 0;
}

.hamburger.open span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ============================================================
   MOBILE MENU OVERLAY
   ============================================================ */

.mobile-menu-backdrop {
  position: fixed;
  inset: 0;
  z-index: 5800;
  border: 0;
  padding: 0;
  margin: 0;
  background: rgba(var(--theme-shadow-rgb), 0.36);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  cursor: pointer;
}

.mobile-menu {
  position: fixed;
  top: 8px;
  width: min(392px, calc(100vw - 32px));
  z-index: 5900;
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - 16px);
  overflow: hidden;
  border: 1px solid var(--theme-border);
  border-radius: 26px;
  background:
    radial-gradient(circle at 18% 0%, rgba(var(--theme-primary-rgb), 0.12), transparent 28%),
    linear-gradient(180deg, color-mix(in srgb, var(--theme-surface) 99%, transparent), color-mix(in srgb, var(--theme-surface-2) 99%, transparent));
  box-shadow:
    0 28px 70px rgba(var(--theme-shadow-rgb), 0.22),
    0 12px 30px rgba(var(--theme-black-rgb), 0.12);
  animation: mobileMenuIn 0.2s ease;
}

.mobile-menu[dir="ltr"] {
  left: 38px;
  right: auto;
}

.mobile-menu[dir="rtl"] {
  right: 38px;
  left: auto;
}

@keyframes mobileMenuIn {
  from {
    opacity: 0;
    transform: translateY(-12px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* ============================================================
   MOBILE MENU HEADER
   ============================================================ */

.mobile-menu-head {
  position: relative;
  min-height: 82px;
  padding: 16px 72px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  border-bottom: 1px solid var(--theme-border);
  background: color-mix(in srgb, var(--theme-surface) 56%, transparent);
}

.mobile-menu-brand {
  min-width: 0;
  grid-column: 2;
  justify-self: center;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  text-decoration: none;
  white-space: nowrap;
}

.mobile-menu-brand img {
  width: 42px;
  height: 42px;
  object-fit: contain;
  display: block;
}

.mobile-menu-brand span {
  color: var(--theme-text);
  font-size: 18px;
  font-weight: 950;
  line-height: 1;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
}

/* ============================================================
   CLOSE BUTTON
   EN = top-left
   AR = top-right
   ============================================================ */

.mobile-menu-close {
  position: fixed;
  top: 0;
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  color: var(--theme-text-inverse);
  background: var(--theme-gradient);
  box-shadow:
    0 16px 34px rgba(var(--theme-primary-rgb), 0.26),
    inset 0 1px 0 var(--theme-border);
  cursor: pointer;
  z-index: 6100;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.mobile-menu[dir="ltr"] .mobile-menu-close {
  left: 0;
  right: auto;
  border-radius: 0 0 18px 0;
}

.mobile-menu[dir="rtl"] .mobile-menu-close {
  right: 0;
  left: auto;
  border-radius: 0 0 0 18px;
}

.mobile-menu-close:hover {
  background: var(--theme-gradient);
  box-shadow:
    0 16px 34px rgba(var(--theme-primary-rgb), 0.26),
    inset 0 1px 0 var(--theme-border);
}

.mobile-menu-close:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 4px rgba(var(--theme-primary-rgb), 0.16),
    0 16px 34px rgba(var(--theme-primary-rgb), 0.26);
}

.mobile-menu-close svg {
  width: 21px;
  height: 21px;
  display: block;
}

/* ============================================================
   MOBILE MENU BODY
   ============================================================ */

.mobile-menu-body {
  padding: 18px;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.mobile-menu-title {
  margin-bottom: 12px;
  color: var(--theme-text-soft);
  font-size: 12px;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
}

.mobile-menu-links {
  display: grid;
  gap: 8px;
}

.mobile-menu-links a {
  min-height: 52px;
  padding: 12px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  color: var(--theme-text);
  background: var(--theme-surface-2);
  border: 1px solid var(--theme-border);
  border-radius: 16px;
  text-decoration: none;
  font-size: 15px;
  font-weight: 900;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
  transition:
    color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.mobile-menu-links a.active {
  color: var(--theme-text-inverse);
  background: var(--theme-gradient);
  box-shadow:
    0 14px 26px var(--theme-primary-soft),
    inset 0 1px 0 var(--theme-border-strong);
}

.mobile-menu-links a:hover:not(.active) {
  color: var(--theme-text);
  background: var(--theme-surface-2);
  box-shadow: none;
  transform: none;
}

.mobile-menu-links a svg {
  flex: 0 0 auto;
}

/* ============================================================
   MOBILE AUTH
   ============================================================ */

.mobile-menu-auth {
  margin-top: 16px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.mobile-menu-auth .btn-login,
.mobile-menu-auth .btn-signup,
.mobile-auth-full {
  min-height: 48px;
  width: 100%;
  border-radius: 16px;
}

.mobile-menu-auth .btn-login {
  background: color-mix(in srgb, var(--theme-surface) 74%, transparent);
  border: 1.5px solid var(--theme-border);
}

.mobile-menu-auth .btn-signup,
.mobile-auth-full {
  color: var(--theme-text-inverse);
  background: var(--theme-gradient);
}

.mobile-auth-full {
  grid-column: 1 / -1;
}

/* ============================================================
   MOBILE LANGUAGE
   ============================================================ */

.mobile-menu-lang-wrap {
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--theme-border);
  display: grid;
  gap: 10px;
}

.mobile-menu-lang-wrap > span {
  color: var(--theme-text-soft);
  font-size: 12px;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
}

.mobile-menu-lang {
  width: 100% !important;
  min-width: 0 !important;
  height: 52px !important;
  min-height: 52px !important;
  grid-template-columns: 38px minmax(0, 1fr) 8px !important;
  column-gap: 12px !important;
  padding: 7px 14px !important;
  border: 1px solid var(--theme-border) !important;
  border-radius: 16px !important;
  background: var(--theme-surface-2) !important;
  color: var(--theme-text) !important;
  box-shadow: none !important;
}

.mobile-menu-lang:hover,
.mobile-menu-lang:focus-visible {
  transform: none !important;
  border-color: var(--theme-border) !important;
  background: var(--theme-surface-2) !important;
  color: var(--theme-text) !important;
  box-shadow: none !important;
}

.mobile-menu-lang .language-toggle-animation {
  width: 36px !important;
  min-width: 36px !important;
  height: 36px !important;
  border-radius: 12px !important;
  background: var(--theme-primary-soft) !important;
  color: var(--color-accent-text) !important;
  border: 0 !important;
  box-shadow: none !important;
}

.mobile-menu-lang .language-toggle-current {
  color: var(--theme-text) !important;
  font-size: 14px !important;
  font-weight: 900 !important;
  letter-spacing: 0 !important;
}

.mobile-menu-lang .language-toggle-dot {
  display: block !important;
  background: var(--theme-primary) !important;
  box-shadow: 0 0 0 4px var(--theme-primary-soft) !important;
}

.lang-mobile-btn {
  min-height: 44px;
  border: 0;
  border-radius: 14px;
  color: var(--theme-text);
  background: var(--theme-surface-2);
  font-size: 14px;
  font-weight: 950;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
  cursor: pointer;
}

.lang-mobile-btn.active {
  color: var(--theme-text-inverse);
  background: var(--theme-text);
}

body.mobile-menu-open {
  overflow: hidden;
}

/* ============================================================
   RTL HEADER
   ============================================================ */

html[dir="rtl"] .site-header,
.site-header[dir="rtl"] {
  direction: rtl;
}

html[dir="rtl"] .brand,
.site-header[dir="rtl"] .brand {
  justify-self: start;
}

html[dir="rtl"] .header-right,
.site-header[dir="rtl"] .header-right {
  justify-self: end;
}

html[dir="rtl"] .lang-dropdown,
.site-header[dir="rtl"] .lang-dropdown {
  right: auto;
  left: 0;
  transform-origin: top left;
}

html[dir="rtl"] .mobile-menu,
.mobile-menu[dir="rtl"] {
  direction: rtl;
  text-align: right;
}

html[dir="rtl"] .mobile-menu-links a,
.mobile-menu[dir="rtl"] .mobile-menu-links a {
  direction: rtl;
}

html[dir="rtl"] .mobile-menu-title,
html[dir="rtl"] .mobile-menu-lang-wrap > span,
.mobile-menu[dir="rtl"] .mobile-menu-title,
.mobile-menu[dir="rtl"] .mobile-menu-lang-wrap > span {
  text-align: right;
}

/* ============================================================
   DARK READER FIX
   ============================================================ */

html[data-darkreader-mode] .site-header,
html[data-darkreader-scheme] .site-header {
  background: linear-gradient(180deg, var(--theme-surface), var(--theme-surface-2)) !important;
  border-bottom-color: rgba(var(--theme-shadow-rgb), 0.1) !important;
}

html[data-darkreader-mode] .brand-name,
html[data-darkreader-mode] .nav-menu a,
html[data-darkreader-mode] .btn-login,
html[data-darkreader-mode] .lang-toggle,
html[data-darkreader-scheme] .brand-name,
html[data-darkreader-scheme] .nav-menu a,
html[data-darkreader-scheme] .btn-login,
html[data-darkreader-scheme] .lang-toggle {
  color: var(--theme-text) !important;
}

html[data-darkreader-mode] .hamburger,
html[data-darkreader-scheme] .hamburger,
html[data-darkreader-mode] .mobile-menu-close,
html[data-darkreader-scheme] .mobile-menu-close {
  background: var(--theme-gradient) !important;
  color: var(--theme-text-inverse) !important;
}

html[data-darkreader-mode] .hamburger span,
html[data-darkreader-scheme] .hamburger span {
  background: var(--theme-surface) !important;
}

/* ============================================================
   RESPONSIVE HEADER
   ============================================================ */

@media (max-width: 1400px) {
  .site-header {
    --header-height: 86px;
    min-height: var(--header-height);
    grid-template-columns: auto minmax(0, 1fr) auto;
    padding: 0 24px;
