.site-header .header-theme-toggle:hover,
.site-header .header-language-switcher.language-toggle-button:hover,
:root[data-theme="dark"] .site-header .header-theme-toggle:hover,
html.theme-dark .site-header .header-theme-toggle:hover,
body.theme-dark .site-header .header-theme-toggle:hover,
:root[data-theme="dark"] .site-header .header-language-switcher.language-toggle-button:hover,
html.theme-dark .site-header .header-language-switcher.language-toggle-button:hover,
