/* ============================================================
   HERO
   ============================================================ */

.hero-section {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  flex: 1;
  padding: 80px 5% 0 5%;
  display: flex;
  align-items: flex-start;
  gap: 48px;
}

.hero-section::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: url("/eduhope/assets/99db75d2aff13cc6.svg") center / clamp(420px, 48vw, 720px) auto no-repeat;
  opacity: 0.045;
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  flex: 1.05;
  max-width: 720px;
}

.hero-visual {
  position: relative;
  z-index: 1;
  flex: 0.95;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
  min-height: 460px;
}

.hero-visual-placeholder {
  position: relative;
  width: 100%;
  height: 700px;
  overflow: hidden;
  border-radius: 16px;
  flex-shrink: 0;
}

.hero-visual-ready {
  width: 100%;
  animation: hero-visual-fade-in 420ms ease-out both;
}

.hero-visual-placeholder-core,
.hero-visual-placeholder-ring {
  position: absolute;
  left: 50%;
  top: 50%;
  display: block;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.hero-visual-placeholder-core {
  width: 96px;
  height: 96px;
  border-radius: 999px;
  background:
    radial-gradient(circle at 34% 28%, rgba(var(--theme-text-inverse-rgb), 0.7), transparent 24%),
    linear-gradient(145deg, rgba(var(--theme-primary-rgb), 0.34), rgba(var(--theme-primary-rgb), 0.08));
  box-shadow:
    0 0 42px rgba(var(--theme-primary-rgb), 0.18),
    inset 0 0 28px rgba(var(--theme-primary-rgb), 0.16);
}

.hero-visual-placeholder-ring {
  border: 1px solid rgba(var(--theme-primary-rgb), 0.22);
  border-radius: 50%;
}

.hero-visual-placeholder-ring-one {
  width: 34%;
  height: 18%;
  transform: translate(-50%, -50%) rotate(12deg);
}

.hero-visual-placeholder-ring-two {
  width: 54%;
  height: 28%;
  transform: translate(-50%, -50%) rotate(-18deg);
}

.hero-visual-placeholder-ring-three {
  width: 72%;
  height: 36%;
  transform: translate(-50%, -50%) rotate(24deg);
}

@keyframes hero-visual-fade-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-visual-ready {
    animation: none;
  }
}

.hero-title {
  margin: 0 0 20px 0;
  color: var(--color-text-main);
  font-size: var(--font-size-2xl);
  font-weight: var(--font-weight-bold);
  font-family: var(--font-heading);
}

.hero-title .gradient-text,
.hero-description .arabic-name {
  unicode-bidi: isolate;
}

.hero-subtitle {
  margin: 40px 0 12px 0;
  color: var(--color-text-main);
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-bold);
  font-family: var(--font-heading);
}

.hero-description {
  margin: 0 0 20px 0;
  color: var(--color-text-muted);
  font-size: var(--font-size-lg);
  line-height: 1.8;
  font-family: var(--font-main);
}

.arabic-name {
  display: inline;
  color: var(--color-accent-text);
  font-weight: var(--font-weight-bold);
  font-size: 22px;
  font-family: var(--font-main);
}

/* ============================================================
   DARK MODE
   ============================================================ */

[data-theme="dark"] .hero-section,
body.theme-dark .hero-section {
  background:
    radial-gradient(circle at 18% 12%, rgba(var(--theme-primary-rgb), 0.08), transparent 30%),
    linear-gradient(180deg, var(--theme-bg) 0%, var(--theme-bg) 100%);
  color: var(--theme-text);
}

[data-theme="dark"] .hero-title,
[data-theme="dark"] .hero-subtitle,
body.theme-dark .hero-title,
body.theme-dark .hero-subtitle {
  color: var(--theme-text);
}

[data-theme="dark"] .hero-description,
body.theme-dark .hero-description {
  color: var(--theme-text-muted);
}

[data-theme="dark"] .arabic-name,
body.theme-dark .arabic-name {
  color: var(--color-accent-text);
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 980px) {
  .hero-section {
    flex-direction: column;
    align-items: center;
    padding-top: 56px;
    gap: 24px;
  }

  .hero-content {
    max-width: 100%;
  }

  .hero-visual {
    width: 100%;
    min-height: auto;
  }

  .hero-visual-placeholder {
    height: 580px;
  }
}

@media (max-width: 640px) {
  .hero-section::before {
    background-size: min(110vw, 480px) auto;
    background-position: center 32%;
    opacity: 0.04;
  }

  .hero-title {
    font-size: 34px;
  }

  .hero-subtitle {
    font-size: 22px;
  }

  .hero-description {
    font-size: 16px;
  }

  .arabic-name {
    font-size: 20px;
  }

  .hero-visual-placeholder {
    height: 420px;
  }
}

@media (max-width: 400px) {
  .hero-visual-placeholder {
    height: 360px;
  }
}

/* ============================================================
   ABOUT
   ============================================================ */

.about-section {
  width: 100%;
  max-width: 1120px;
  margin: 0 auto;
  padding: 64px 5% 90px;
  color: var(--theme-text);
}

.about-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.75fr);
  gap: 24px;
  align-items: stretch;
  margin-bottom: 18px;
}

.about-hero-copy,
.about-hero-panel,
.about-metric,
.about-card,
.about-closing {
  border: 1px solid var(--theme-border);
  border-radius: 18px;
  background: var(--theme-surface);
  box-shadow: 0 16px 38px rgba(var(--theme-shadow-rgb), 0.07);
}

.about-hero-copy {
  padding: clamp(28px, 4vw, 42px);
}


.about-hero h1 {
  max-width: 760px;
