  font-weight: 950;
  letter-spacing: 0;
}

.about-hero h1 span {
  color: var(--color-accent-text);
}

.about-hero p {
  max-width: 780px;
  margin: 16px 0 0;
  color: var(--theme-text-soft);
  font-size: 17px;
  line-height: 1.72;
  font-weight: 650;
}

.about-hero p strong {
  color: var(--theme-text);
