}

.about-hero-panel h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: 24px;
  line-height: 1.18;
  font-weight: 950;
}

.about-hero-panel p {
  margin: 0;
  color: var(--theme-text-soft);
  font-size: 15px;
  line-height: 1.62;
  font-weight: 650;
}

.about-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
