  margin-bottom: 18px;
}

.about-metric {
  min-width: 0;
  padding: 18px;
  display: grid;
  gap: 8px;
}

.about-metric svg {
  color: var(--color-accent-text);
}

.about-metric strong {
  color: var(--theme-text);
  font-size: 18px;
  line-height: 1.2;
  font-weight: 950;
}

.about-metric span {
  color: var(--theme-text-soft);
  font-size: 14px;
  line-height: 1.5;
  font-weight: 650;
}

.about-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.about-card {
  min-width: 0;
  padding: 24px;
}

.about-card > span {
  display: inline-flex;
  margin-bottom: 18px;
  color: var(--color-accent-text);
  font-size: 13px;
  font-weight: 950;
}

.about-card h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: 22px;
  line-height: 1.2;
  font-weight: 950;
}

.about-card p {
  margin: 12px 0 0;
  color: var(--theme-text-soft);
  font-size: 15px;
  line-height: 1.66;
  font-weight: 650;
}

.about-closing {
  margin: 18px 0 0;
  padding: 22px 24px;
  color: var(--theme-text);
  font-size: 17px;
  line-height: 1.65;
