}

[data-theme="dark"] .about-hero-copy,
[data-theme="dark"] .about-hero-panel,
[data-theme="dark"] .about-metric,
[data-theme="dark"] .about-card,
[data-theme="dark"] .about-closing,
body.theme-dark .about-hero-copy,
body.theme-dark .about-hero-panel,
body.theme-dark .about-metric,
body.theme-dark .about-card,
body.theme-dark .about-closing {
  background: var(--theme-surface);
  border-color: var(--theme-border);
  box-shadow: 0 22px 56px rgba(var(--theme-black-rgb), 0.24);
}

@media (max-width: 900px) {
  .about-section {
    max-width: 100%;
    padding-left: 32px;
    padding-right: 32px;
  }

  .about-hero,
  .about-metrics,
  .about-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 620px) {
  .about-section {
    padding: 36px 20px 60px;
  }

  .about-hero-copy,
  .about-hero-panel,
  .about-card,
  .about-closing {
    padding: 20px;
    border-radius: 16px;
  }

  .about-hero h1 {
    font-size: clamp(30px, 8vw, 36px);
    line-height: 1.12;
  }

  .about-hero p,
  .about-closing {
