/* ============================================================
   CONTACT PAGE
   ============================================================ */

.contact-page {
  flex: 1;
  max-width: 1060px;
  margin: 0 auto;
  padding: 60px 5% 80px;
  width: 100%;
}

.contact-hero {
  margin-bottom: 48px;
}

.contact-hero h1 {
  margin: 0 0 12px 0;
  color: var(--theme-text);
  font-size: 42px;
  font-weight: 800;
  font-family: inherit;
}

.contact-hero p {
  margin: 0;
  color: var(--theme-text-soft);
  font-size: 18px;
  line-height: 1.8;
}

.contact-content {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 48px;
  align-items: start;
}

.contact-form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.contact-form label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  color: var(--theme-text);
  font-size: 15px;
  font-weight: 700;
  font-family: inherit;
}

.contact-form input,
.contact-form textarea {
  padding: 12px 16px;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.18);
  border-radius: 10px;
  font-size: 15px;
  font-family: Inter, "IBM Plex Sans Arabic", sans-serif;
  color: var(--theme-text);
  background: var(--theme-surface);
  outline: none;
  transition: border-color 0.2s ease;
  resize: vertical;
}

.contact-form input:focus,
.contact-form textarea:focus {
  border-color: var(--color-accent-text);
}

.contact-form button {
  align-self: center;
  padding: 12px 32px;
  background: var(--theme-primary);
  color: var(--theme-text-inverse);
  font-size: 16px;
  font-weight: 700;
  font-family: inherit;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.2s ease;
}

.contact-form button:hover {
  background: var(--theme-primary-hover);
}

.contact-form button:disabled {
  cursor: not-allowed;
  opacity: 0.72;
}

.contact-form-status {
  margin: -4px 0 2px;
  font-size: 14px;
  font-weight: 700;
  text-align: center;
}

.contact-form-status-success {
  color: var(--color-status-success-text);
}

.contact-form-status-error {
  color: var(--color-status-danger-text);
}

.contact-info-card {
  background: var(--theme-surface);
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.08);
  border-radius: 16px;
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  text-align: center;
  align-items: center;
}

.contact-info-card h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: 20px;
  font-weight: 800;
  font-family: inherit;
}

.contact-info-card strong {
  display: block;
  color: var(--color-accent-text);
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.contact-info-card p {
  margin: 0;
  color: var(--theme-text-soft);
  font-size: 15px;
  line-height: 1.6;
}

/* direction:ltr keeps the number rendering correctly in both LTR & RTL contexts;
   text-align is intentionally NOT set here so it inherits from the parent
   (.footer-contact is centered; .contact-info-card flows naturally). */
.phone-number {
  direction: ltr;
  unicode-bidi: isolate;
}

html[data-theme="dark"] .contact-page,
body.theme-dark .contact-page {
  color: var(--theme-text);
}

html[data-theme="dark"] .contact-hero h1,
body.theme-dark .contact-hero h1 {
  color: var(--theme-text);
}

html[data-theme="dark"] .contact-hero p,
body.theme-dark .contact-hero p {
  color: var(--theme-text-muted);
}

html[data-theme="dark"] .contact-form label,
body.theme-dark .contact-form label {
  color: var(--theme-text-soft);
}

html[data-theme="dark"] .contact-form input,
html[data-theme="dark"] .contact-form textarea,
body.theme-dark .contact-form input,
body.theme-dark .contact-form textarea {
  background: var(--theme-surface);
  border-color: var(--theme-border);
  color: var(--theme-text);
  box-shadow: inset 0 1px 0 rgba(244, 240, 232, 0.04);
}

html[data-theme="dark"] .contact-form input:focus,
html[data-theme="dark"] .contact-form textarea:focus,
body.theme-dark .contact-form input:focus,
body.theme-dark .contact-form textarea:focus {
  border-color: rgba(var(--theme-primary-rgb), 0.68);
  box-shadow:
    0 0 0 4px rgba(var(--theme-primary-rgb), 0.12),
    inset 0 1px 0 rgba(244, 240, 232, 0.05);
}

html[data-theme="dark"] .contact-form button,
body.theme-dark .contact-form button {
  background: var(--theme-gradient);
  box-shadow: 0 14px 30px rgba(var(--theme-primary-rgb), 0.22);
}

html[data-theme="dark"] .contact-form button:hover,
body.theme-dark .contact-form button:hover {
  background: var(--theme-gradient-hover);
}

html[data-theme="dark"] .contact-info-card,
body.theme-dark .contact-info-card {
  background: var(--theme-surface);
  border-color: var(--theme-border);
  color: var(--theme-text);
  box-shadow: 0 22px 56px rgba(var(--theme-black-rgb), 0.24);
}

html[data-theme="dark"] .contact-info-card h2,
body.theme-dark .contact-info-card h2 {
  color: var(--theme-text);
}

html[data-theme="dark"] .contact-info-card p,
body.theme-dark .contact-info-card p {
  color: var(--theme-text-soft);
}
/* ============================================================
   MADAR FOOTER
   FULL LTR + RTL SUPPORT
   ============================================================ */

.site-footer,
.site-footer * {
  box-sizing: border-box;
}

.site-footer {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  margin-top: auto;
  padding: 56px 6% 24px;
  color: var(--theme-footer-text);
  border-top: 1px solid var(--theme-footer-border);
  background:
    radial-gradient(circle at 12% 18%, rgba(var(--theme-primary-rgb), 0.34), transparent 30%),
    radial-gradient(circle at 86% 12%, color-mix(in srgb, var(--theme-text-inverse) 4.5%, transparent), transparent 24%),
    linear-gradient(135deg, var(--theme-footer-bg-soft) 0%, var(--theme-bg) 48%, var(--theme-footer-bg) 100%);
}

.site-footer::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -2;
  pointer-events: none;
  background:
    linear-gradient(color-mix(in srgb, var(--theme-text-inverse) 2.5%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--theme-text-inverse) 2.5%, transparent) 1px, transparent 1px);
  background-size: 54px 54px;
  mask-image: linear-gradient(to bottom, rgba(var(--theme-black-rgb), 0.45), transparent 80%);
}

.footer-shell {
  width: 100%;
  max-width: 1180px;
  margin-inline: auto;
}

/* ============================================================
   MAIN GRID
   ============================================================ */

.footer-main {
  display: grid;
  gap: 34px;
  align-items: stretch;
}

.footer-brand {
  grid-area: brand;
}

.footer-links {
  grid-area: links;
}

.footer-contact {
  grid-area: contact;
}

/* ============================================================
   BRAND
   ============================================================ */

.footer-brand {
  max-width: 430px;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
}

.footer-logo-link {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 16px;
  color: var(--theme-text-inverse);
  text-decoration: none;
}

.footer-logo {
  width: 68px;
  height: 68px;
  display: block;
  object-fit: contain;
  filter:
    drop-shadow(0 14px 24px rgba(var(--theme-shadow-rgb), 0.42))
    drop-shadow(0 0 14px rgba(var(--theme-primary-rgb), 0.24));
}

.footer-logo-link span {
  color: var(--theme-text-inverse);
  font-size: 31px;
  font-weight: 900;
  line-height: 1;
}

.footer-brand p {
  max-width: 390px;
  margin: 0;
  color: var(--theme-footer-text-soft);
  font-size: 15px;
  font-weight: 500;
  line-height: 1.75;
}

/* ============================================================
   CARDS
   ============================================================ */

.footer-links,
.footer-contact {
  padding: 24px;
  border-radius: 26px;
  background: linear-gradient(
    180deg,
    var(--theme-footer-surface),
    color-mix(in srgb, var(--theme-footer-surface) 46%, transparent)
  );
  border: 1px solid var(--theme-footer-border);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--theme-text-inverse) 7%, transparent),
    0 18px 40px rgba(var(--theme-shadow-rgb), 0.16);
  backdrop-filter: blur(14px);
}

.footer-links h4,
.footer-contact h4 {
  margin: 0 0 17px;
  color: var(--theme-text-inverse);
  font-size: 16px;
  font-weight: 900;
}

/* ============================================================
   LINKS
   ============================================================ */

.footer-links-grid {
  display: grid;
  gap: 12px;
}

.footer-link {
  position: relative;
  width: fit-content;
  color: var(--theme-footer-text-soft);
  text-decoration: none;
  font-size: 14.5px;
  font-weight: 750;
  line-height: 1.3;
  transition:
    color 0.2s ease,
    transform 0.2s ease;
}

.footer-link::after {
  content: "";
  position: absolute;
  bottom: -5px;
  width: 0;
  height: 2px;
  border-radius: 999px;
  background: var(--theme-primary);
  box-shadow: 0 0 14px rgba(var(--theme-primary-rgb), 0.55);
  transition: width 0.22s ease;
}

.footer-link:hover,
.footer-link.active {
  color: var(--color-accent-text);
}

.footer-link:hover::after,
.footer-link.active::after {
  width: 100%;
}

/* ============================================================
   CONTACT
   ============================================================ */

.footer-contact {
  display: flex;
  flex-direction: column;
}

.footer-contact-list {
  display: grid;
  gap: 15px;
}

.footer-contact-item {
  display: grid;
  gap: 5px;
  color: var(--theme-text-inverse);
  text-decoration: none;
  transition:
    color 0.2s ease,
    transform 0.2s ease;
}

.footer-contact-item span {
  color: var(--theme-footer-text-muted);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}

.footer-contact-item strong {
  color: var(--theme-footer-text);
  font-size: 15px;
  font-weight: 800;
  line-height: 1.4;
  word-break: break-word;
  unicode-bidi: isolate;
}

.footer-contact-item:hover strong {
  color: var(--theme-text-inverse);
}

/* ============================================================
   SOCIAL
   ============================================================ */

.footer-social-row {
  margin-top: auto;
  padding-top: 22px;
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.footer-social-row span {
  color: var(--theme-footer-text-muted);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}

.footer-social-link {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--theme-text-inverse);
  text-decoration: none;
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--theme-text-inverse) 12%, transparent),
    color-mix(in srgb, var(--theme-text-inverse) 5%, transparent)
  );
  border: 1px solid var(--theme-footer-border);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--theme-text-inverse) 8%, transparent),
    0 10px 20px rgba(var(--theme-shadow-rgb), 0.18);
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.footer-social-link:hover {
  color: var(--theme-text-inverse);
  background: linear-gradient(180deg, var(--theme-primary), var(--theme-primary-hover));
  border-color: rgba(var(--theme-primary-rgb), 0.85);
  transform: translateY(-3px);
  box-shadow:
    0 14px 28px rgba(var(--theme-primary-rgb), 0.34),
    0 0 0 4px rgba(var(--theme-primary-rgb), 0.1);
}

.footer-social-link svg {
  width: 17px;
  height: 17px;
  display: block;
}

/* ============================================================
   BOTTOM
   ============================================================ */

.footer-bottom {
  margin-top: 38px;
  padding-top: 18px;
  display: flex;
  justify-content: center;
  text-align: center;
  border-top: 1px solid var(--theme-footer-border);
}

.footer-bottom p {
  margin: 0;
  color: var(--theme-footer-text-muted);
  font-size: 13px;
  font-weight: 500;
  line-height: 1.5;
}

/* ============================================================
   ENGLISH / LTR
   ============================================================ */

.footer-en {
  direction: ltr;
  text-align: left;
}

.footer-en .footer-shell {
  direction: ltr;
}

.footer-en .footer-main {
  direction: ltr;
  grid-template-columns:
    minmax(280px, 1.35fr)
    minmax(210px, 0.85fr)
    minmax(250px, 1fr);
  grid-template-areas: "brand links contact";
}

.footer-en .footer-brand,
.footer-en .footer-links,
.footer-en .footer-contact {
  direction: ltr;
  text-align: left;
}

.footer-en .footer-brand {
  justify-self: start;
  align-items: flex-start;
}

.footer-en .footer-logo-link {
  direction: ltr;
  flex-direction: row;
  align-self: flex-start;
}

.footer-en .footer-logo-link span {
  letter-spacing: -0.055em;
}

.footer-en .footer-brand p {
  text-align: left;
}

.footer-en .footer-links h4,
.footer-en .footer-contact h4 {
  text-align: left;
}

.footer-en .footer-links-grid {
  justify-items: start;
}

.footer-en .footer-link {
  text-align: left;
  justify-self: start;
}

.footer-en .footer-link::after {
  left: 0;
  right: auto;
}

.footer-en .footer-contact-list {
  justify-items: start;
}

.footer-en .footer-contact-item {
  width: 100%;
  direction: ltr;
  text-align: left;
  justify-items: start;
}

.footer-en .footer-contact-item span,
.footer-en .footer-contact-item strong {
  width: 100%;
  text-align: left;
}

.footer-en .footer-social-row {
  direction: ltr;
  justify-content: flex-start;
  flex-direction: row;
  text-align: left;
}

.footer-en .footer-link:hover,
.footer-en .footer-link.active,
.footer-en .footer-contact-item:hover {
  transform: translateX(4px);
}

/* ============================================================
   ARABIC / RTL
   Desktop physical layout:
   left   = contact
   middle = links
   right  = brand
   ============================================================ */

.footer-ar {
  direction: rtl;
  text-align: right;
}

.footer-ar .footer-shell {
  direction: rtl;
}

/* This controls physical desktop column order only */
.footer-ar .footer-main {
  direction: ltr;
  grid-template-columns:
    minmax(250px, 1fr)
    minmax(210px, 0.85fr)
    minmax(280px, 1.35fr);
  grid-template-areas: "contact links brand";
}

/* This restores Arabic behavior inside each column */
.footer-ar .footer-brand,
.footer-ar .footer-links,
.footer-ar .footer-contact {
  direction: rtl;
  text-align: right;
}

/* BRAND */
.footer-ar .footer-brand {
  justify-self: end;
  align-items: flex-start;
}

.footer-ar .footer-logo-link {
  direction: rtl;
  flex-direction: row;
  align-self: flex-start;
  justify-content: flex-start;
  text-align: right;
}

.footer-ar .footer-logo-link span {
  direction: rtl;
  text-align: right;
  letter-spacing: 0;
}

.footer-ar .footer-brand p {
  width: 100%;
  direction: rtl;
  text-align: right;
  unicode-bidi: plaintext;
}

/* LINKS */
.footer-ar .footer-links h4 {
  direction: rtl;
  text-align: right;
}

.footer-ar .footer-links-grid {
  direction: rtl;
  justify-items: start;
  text-align: right;
}

.footer-ar .footer-link {
  direction: rtl;
  text-align: right;
  justify-self: start;
}

.footer-ar .footer-link::after {
  right: 0;
  left: auto;
}

/* CONTACT */
.footer-ar .footer-contact h4 {
  direction: rtl;
  text-align: right;
}

.footer-ar .footer-contact-list {
  direction: rtl;
  justify-items: start;
  text-align: right;
}

.footer-ar .footer-contact-item {
  width: 100%;
  direction: rtl;
  text-align: right;
  justify-items: start;
}

.footer-ar .footer-contact-item span {
  width: 100%;
  display: block;
  direction: rtl;
  text-align: right;
}

.footer-ar .footer-contact-item strong {
  width: 100%;
  display: block;
  direction: ltr;
  text-align: right;
  unicode-bidi: isolate;
}

/* SOCIAL */
.footer-ar .footer-social-row {
  width: 100%;
  direction: rtl;
  flex-direction: row;
  justify-content: flex-start;
  text-align: right;
}

.footer-ar .footer-social-row span {
  direction: rtl;
  text-align: right;
}

.footer-ar .footer-link:hover,
.footer-ar .footer-link.active,
.footer-ar .footer-contact-item:hover {
  transform: translateX(-4px);
}

/* ============================================================
   TABLET
   ============================================================ */

@media (max-width: 980px) {
  .site-footer {
    padding: 46px 6% 22px;
  }

  .footer-en .footer-main {
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      "brand brand"
      "links contact";
    gap: 26px;
  }

  .footer-ar .footer-main {
    direction: ltr;
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      "brand brand"
      "contact links";
    gap: 26px;
  }

  .footer-brand {
    max-width: 640px;
  }

  .footer-brand p {
    max-width: 560px;
  }

  .footer-ar .footer-brand {
    justify-self: end;
    align-items: flex-start;
  }
}

/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 620px) {
  .site-footer {
    padding: 40px 18px 22px;
  }

  .footer-en .footer-main,
  .footer-ar .footer-main {
    grid-template-columns: 1fr;
    grid-template-areas:
      "brand"
      "links"
      "contact";
    gap: 20px;
  }

  .footer-brand,
  .footer-links,
  .footer-contact {
    width: 100%;
    max-width: 100%;
    justify-self: stretch;
  }

  .footer-logo-link {
    gap: 14px;
    margin-bottom: 12px;
  }

  .footer-logo {
    width: 58px;
    height: 58px;
  }

  .footer-logo-link span {
    font-size: 28px;
  }

  .footer-brand p {
    max-width: 100%;
    font-size: 14px;
    line-height: 1.65;
  }

  .footer-links,
  .footer-contact {
    padding: 20px;
    border-radius: 22px;
  }

  .footer-links h4,
  .footer-contact h4 {
    margin-bottom: 15px;
    font-size: 16px;
  }

  .footer-links-grid {
    gap: 12px;
  }

  .footer-link {
    font-size: 14.5px;
  }

  .footer-contact-list {
    gap: 14px;
  }

  .footer-contact-item strong {
    font-size: 14.5px;
  }

  .footer-social-row {
    margin-top: 20px;
    padding-top: 0;
  }

  .footer-bottom {
    margin-top: 26px;
    padding-top: 16px;
  }

  .footer-bottom p {
    font-size: 12.5px;
  }

  /* EN mobile */
  .footer-en .footer-main {
    direction: ltr;
  }

  .footer-en .footer-brand,
  .footer-en .footer-links,
  .footer-en .footer-contact {
    direction: ltr;
    text-align: left;
  }

  .footer-en .footer-brand {
    align-items: flex-start;
  }

  .footer-en .footer-logo-link {
    align-self: flex-start;
  }

  .footer-en .footer-links-grid,
  .footer-en .footer-contact-list {
    justify-items: start;
  }

  .footer-en .footer-link,
  .footer-en .footer-contact-item {
    justify-self: start;
    text-align: left;
  }

  .footer-en .footer-social-row {
    justify-content: flex-start;
  }

  /* AR mobile */
  .footer-ar .footer-main {
    direction: rtl;
  }

  .footer-ar .footer-brand,
  .footer-ar .footer-links,
  .footer-ar .footer-contact {
    direction: rtl;
    text-align: right;
  }

  .footer-ar .footer-brand {
    align-items: flex-start;
  }

  .footer-ar .footer-logo-link {
    align-self: flex-start;
    direction: rtl;
  }

  .footer-ar .footer-brand p {
    text-align: right;
  }

  .footer-ar .footer-links h4,
  .footer-ar .footer-contact h4 {
    text-align: right;
  }

  .footer-ar .footer-links-grid,
  .footer-ar .footer-contact-list {
    justify-items: start;
  }

  .footer-ar .footer-link,
  .footer-ar .footer-contact-item {
    justify-self: start;
    text-align: right;
  }

  .footer-ar .footer-social-row {
    justify-content: flex-start;
  }
}

/* ============================================================
   SMALL MOBILE
   ============================================================ */

@media (max-width: 420px) {
  .site-footer {
    padding: 36px 16px 20px;
  }

  .footer-main {
    gap: 18px;
  }

  .footer-logo {
    width: 52px;
    height: 52px;
  }

  .footer-logo-link span {
    font-size: 25px;
  }

  .footer-brand p {
    font-size: 13.5px;
  }

  .footer-links,
  .footer-contact {
    padding: 18px;
    border-radius: 20px;
  }

  .footer-link,
  .footer-contact-item strong {
    font-size: 14px;
  }
}

/* ============================================================
   DARK READER FIX
   ============================================================ */

html[data-darkreader-mode] .site-footer,
html[data-darkreader-scheme] .site-footer {
  color: var(--theme-footer-text) !important;
  background:
    radial-gradient(circle at 12% 18%, rgba(var(--theme-primary-rgb), 0.34), transparent 30%),
    radial-gradient(circle at 86% 12%, rgba(var(--theme-text-inverse-rgb), 0.045), transparent 24%),
    linear-gradient(135deg, var(--theme-footer-bg-soft) 0%, var(--theme-footer-bg) 48%, var(--theme-footer-bg) 100%) !important;
}

html[data-darkreader-mode] .footer-links,
html[data-darkreader-mode] .footer-contact,
html[data-darkreader-scheme] .footer-links,
html[data-darkreader-scheme] .footer-contact {
  background: linear-gradient(
    180deg,
    rgba(var(--theme-text-inverse-rgb), 0.07),
    rgba(var(--theme-text-inverse-rgb), 0.032)
  ) !important;
  border-color: rgba(var(--theme-text-inverse-rgb), 0.105) !important;
}

/* ============================================================
   RTL
   ============================================================ */

html[dir="rtl"] .site-header       { direction: rtl; }
html[dir="rtl"] .brand             { justify-self: end; }
html[dir="rtl"] .nav-menu          { direction: rtl; }
html[dir="rtl"] .nav-menu a        { font-family: inherit; }
html[dir="rtl"] .lang-switcher     { justify-self: start; }
html[dir="rtl"] .lang-dropdown     { right: auto; left: 0; transform-origin: top left; }
html[dir="rtl"] .hero-section      { text-align: right; }
html[dir="rtl"] .about-section     { margin-left: auto; margin-right: auto; text-align: right; }
html[dir="rtl"] .mobile-menu a     { font-family: inherit; }
html[dir="rtl"] .contact-page      { text-align: right; }
html[dir="rtl"] .contact-form button { align-self: center; }
html[dir="rtl"] .header-right      { justify-self: start; }
html[dir="rtl"] .btn-login,
html[dir="rtl"] .btn-signup        { font-family: inherit; }

html[dir="rtl"] .phone-number {
  direction: ltr;
  unicode-bidi: isolate;
  text-align: center;
}

html[dir="rtl"] .contact-info-card {
  text-align: center;
  align-items: center;
}

html[dir="rtl"] .contact-info-card strong,
html[dir="rtl"] .contact-info-card p {
  text-align: center;
}

/* --- RTL footer: flex so we can control column order --- */
html[dir="rtl"] .site-footer {
  direction: rtl;
}

html[dir="rtl"] .footer-content {
  display: flex;
  flex-direction: row;          /* explicit: columns side by side  */
  justify-content: center;
  align-items: flex-start;
  gap: 48px;
  direction: rtl;
}

html[dir="rtl"] .footer-brand   { order: 1; flex: 1 1 0; max-width: 320px; text-align: center; }
html[dir="rtl"] .footer-links   { order: 2; flex: 1 1 0; max-width: 320px; text-align: center; }
html[dir="rtl"] .footer-contact { order: 3; flex: 1 1 0; max-width: 320px; text-align: center; }

html[dir="rtl"] .footer-logo-row {
  align-items: center;
}

html[dir="rtl"] .footer-bottom {
  text-align: center;
  direction: rtl;
}

html[dir="rtl"] .footer-links {
  align-items: center;
}
/* ============================================================
   RESPONSIVE — 900px
   ============================================================ */

@media (max-width: 900px) {
  .site-header {
    grid-template-columns: minmax(0, 1fr) auto;
    min-height: auto;
    padding: 20px;
    column-gap: 14px;
    overflow: hidden;
  }

  .brand {
    grid-column: 1;
    min-width: 0;
  }

  .brand-name {
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .header-right {
    grid-column: 2;
    justify-self: end;
    min-width: max-content;
  }

  .header-right .lang-switcher {
    display: none;
  }

  .nav-menu {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .mobile-menu {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0;
    grid-column: 1 / -1;
    width: 100%;
    background: rgba(var(--theme-text-inverse-rgb), 0.97);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(var(--theme-shadow-rgb), 0.1);
    border-radius: 16px;
    padding: 8px 0;
    margin-top: 4px;
    box-shadow: 0 16px 40px rgba(var(--theme-shadow-rgb), 0.12);
  }

  .hero-section {
    flex-direction: column;
    align-items: flex-start;
    min-height: auto;
    padding: 32px 5% 64px;
  }

  .hero-content   { flex: none; width: 100%; }
  .hero-visual    { flex: none; width: 100%; margin-top: 24px; padding: 10px; }

  .orbit-wrapper  { width: 300px; height: 300px; }
  .center-core    { width: 105px; height: 105px; }
  .center-core span { font-size: 16px; }
  .orbit-one      { width: 145px; height: 145px; }
  .orbit-two      { width: 215px; height: 215px; }
  .orbit-three    { width: 290px; height: 290px; }
  .orbit-dot      { font-size: 11px; padding: 7px 10px; }

  .about-section,
  html[dir="rtl"] .about-section {
    margin-left: 20px;
    margin-right: 20px;
    max-width: none;
  }

  .contact-content  { grid-template-columns: 1fr; }
  .contact-page     { padding: 40px 5% 60px; }
  .contact-hero h1  { font-size: 32px; }

  /* Footer: stack columns vertically on mobile (both LTR & RTL) */
  .footer-content {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  html[dir="rtl"] .footer-content {
    flex-direction: column;
    align-items: center;
    gap: 28px;
  }

  html[dir="rtl"] .footer-brand,
  html[dir="rtl"] .footer-links,
  html[dir="rtl"] .footer-contact {
    order: unset;
    max-width: 100%;
    width: 100%;
  }

  .site-footer {
    padding: 40px 5% 22px;
  }

  /* Auth buttons in mobile menu */
  .mobile-menu-auth {
    display: flex;
    gap: 10px;
    padding: 12px 24px;
    width: 100%;
    justify-content: center;
    border-top: 1px solid rgba(var(--theme-shadow-rgb), 0.07);
  }

  .mobile-menu-auth .btn-login {
    flex: 1;
    justify-content: center;
    font-size: 14px;
    padding: 10px 16px;
    border-color: rgba(var(--theme-shadow-rgb), 0.3);
    color: var(--theme-text);
    background: transparent;
  }

  .mobile-menu-auth .btn-login:hover {
    border-color: var(--color-accent-text);
    color: var(--color-accent-text);
    background: rgba(var(--theme-primary-rgb), 0.04);
  }

  .mobile-menu-auth .btn-signup {
    flex: 1;
    justify-content: center;
    font-size: 14px;
    padding: 10px 16px;
    color: var(--theme-text-inverse);
  }

  /* Lang buttons on white bg */
  .mobile-menu-lang .lang-mobile-btn {
    border-color: rgba(var(--theme-shadow-rgb), 0.3);
    color: var(--theme-text);
    background: transparent;
  }

  .mobile-menu-lang .lang-mobile-btn.active,
  .mobile-menu-lang .lang-mobile-btn:hover {
    border-color: var(--color-accent-text);
    color: var(--color-accent-text);
    background: rgba(var(--theme-primary-rgb), 0.05);
  }

  /* Hide desktop auth buttons on mobile */
  .header-right .btn-login,
  .header-right .btn-signup {
    display: none;
  }
}

/* ============================================================
   RESPONSIVE — 600px
   ============================================================ */

@media (max-width: 600px) {
  .logo             { width: 48px; }
  .brand-name       { font-size: 17px; }
  .hero-title       { font-size: 28px; }
  .hero-subtitle    { font-size: 20px; }
  .hero-description { font-size: 15px; }

  .orbit-wrapper  { width: 260px; height: 260px; }
  .center-core    { width: 90px;  height: 90px; }
  .center-core span { font-size: 14px; }
  .orbit-one      { width: 125px; height: 125px; }
  .orbit-two      { width: 185px; height: 185px; }
  .orbit-three    { width: 245px; height: 245px; }
  .orbit-dot      { font-size: 10px; padding: 6px 9px; }
}

/* ============================================================
   REGISTER / SIGN UP PAGE
   ============================================================ */

.login-page,
.register-page {
  position: relative;
  isolation: isolate;
}

.login-page::after,
.register-page::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: url("/eduhope/assets/99db75d2aff13cc6.svg") center / clamp(320px, 50vw, 680px) auto no-repeat;
  opacity: 0.055;
  pointer-events: none;
}

.login-page > *,
.register-page > * {
  position: relative;
  z-index: 1;
}

.register-page {
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  gap: clamp(28px, 5vw, 88px);
  padding: 60px 5% 90px;
  color: var(--theme-text);
}

.register-card {
  width: 100%;
  max-width: 780px;
  background: var(--theme-surface);
  border: 1px solid var(--theme-border);
  border-radius: 18px;
  padding: 32px;
  box-shadow: 0 18px 45px rgba(var(--theme-shadow-rgb), 0.08);
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.register-card h1 {
  margin: 0 0 6px;
  color: var(--theme-text);
