html[dir="rtl"] .forgot-card .form-status-message {
  direction: ltr;
  unicode-bidi: isolate;
  text-align: center;
  margin-inline: auto;
  align-self: center;
}

@media (max-width: 600px) {
  .forgot-page {
    padding: 40px 5% 70px;
  }

  .forgot-card {
    padding: 28px;
  }

  .forgot-card h1 {
    font-size: 28px;
  }
}

.auth-section-title {
  position: relative;
  z-index: 1;
  margin: 2px 0 -2px;
  color: var(--theme-text-soft);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0;
  text-transform: uppercase;
  text-align: left;
}

.subdomain-preview {
  color: var(--theme-text-soft);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.auth-terms-consent {
  display: grid;
  gap: 7px;
  margin-top: 2px;
}

.register-card .auth-terms-row {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
}

.register-card .auth-terms-row input[type="checkbox"] {
  flex: 0 0 18px;
  width: 18px;
  height: 18px;
  margin: 2px 0 0;
  padding: 0;
  border-radius: 5px;
  accent-color: var(--color-accent-text);
  cursor: pointer;
}

.register-card .auth-terms-row .auth-terms-copy {
  color: var(--theme-text-soft);
  font-size: 13px;
  font-weight: 650;
  line-height: 1.55;
}

.register-card .auth-terms-copy a {
  color: var(--color-accent-text);
  font-weight: 800;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.register-card .auth-terms-copy a:hover {
  color: var(--color-accent-text);
}

.auth-terms-consent.has-error input[type="checkbox"] {
  outline: 2px solid var(--theme-danger, #dc2626);
  outline-offset: 2px;
}

.login-card[dir="rtl"] .auth-section-title,
html[dir="rtl"] .auth-section-title {
  text-align: right;
}


.auth-toast {
  top: calc(116px + env(safe-area-inset-top));
  max-height: calc(100dvh - 132px - env(safe-area-inset-top));
  overflow-y: auto;
  pointer-events: auto;
  align-items: flex-start;
  gap: 12px;
}
.auth-toast[dir="ltr"] { right:24px !important; left:auto !important; direction:ltr !important; text-align:left; }
.auth-toast[dir="rtl"] { left:24px !important; right:auto !important; direction:rtl !important; }
.auth-toast-icon { margin-block-start:8px; }
.auth-toast-message { flex:1; padding-block:6px; }
.auth-toast-message strong { font-size:14px; line-height:1.4; }
.auth-toast-message >span { font-size:13px; line-height:1.5; }
.auth-toast-dismiss { width:44px; height:44px; flex:0 0 44px; display:grid; place-items:center; border:0; border-radius:8px; background:transparent; color:var(--theme-text); cursor:pointer; }
.auth-toast-dismiss:hover { background:var(--theme-primary-soft); }
.auth-toast-dismiss:focus-visible { outline:2px solid var(--theme-primary); outline-offset:2px; }
@media(max-width:600px) {
 .auth-toast {
   top: calc(76px + env(safe-area-inset-top));
   width: min(360px, calc(100vw - 32px));
   max-height: calc(100dvh - 92px - env(safe-area-inset-top));
 }
 .auth-toast[dir="ltr"] { right:16px !important; }
 .auth-toast[dir="rtl"] { left:16px !important; }
}
@media(prefers-reduced-motion:reduce) { .auth-toast { animation:none; } }
/* ============================================================
   PRICING PAGE - FORMAL MADAR DESIGN
   ============================================================ */

.pricing-page {
  width: min(1180px, calc(100% - 32px));
  margin: 0 auto;
  padding: 72px 0 88px;
  color: var(--theme-text);
}

.pricing-page[dir="rtl"] {
  direction: rtl;
  text-align: right;
}

.pricing-page[dir="ltr"] {
  direction: ltr;
  text-align: left;
}

/* HERO */

.pricing-hero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(420px, 520px);
  align-items: center;
  gap: 36px;
  margin-bottom: 36px;
  padding: 8px 0 32px;
  border-bottom: 1px solid var(--theme-border, rgba(var(--theme-shadow-rgb), 0.1));
}

.pricing-hero::after,
.pricing-inner-header::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -1px;
  width: 160px;
  height: 1px;
  background: linear-gradient(
    90deg,
    var(--theme-primary),
    transparent
  );
}

.pricing-page[dir="rtl"] .pricing-hero::after,
.pricing-page[dir="rtl"] .pricing-inner-header::after {
  left: auto;
  right: 0;
}

.pricing-hero-copy {
  max-width: 780px;
}

.pricing-eyebrow,
.pricing-section-heading > span {
  display: inline-flex;
  margin-bottom: 10px;
  color: var(--color-accent-text);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pricing-page[dir="rtl"] .pricing-eyebrow,
.pricing-page[dir="rtl"] .pricing-section-heading > span {
  letter-spacing: 0;
}

.pricing-hero h1 {
  max-width: 760px;
  margin: 0;
  color: var(--theme-text);
  font-size: clamp(34px, 5vw, 54px);
  line-height: 1.04;
  font-weight: 950;
  letter-spacing: -0.055em;
}

.pricing-page[dir="rtl"] .pricing-hero h1 {
  letter-spacing: -0.025em;
}

.pricing-hero p,
.pricing-section-heading p {
  max-width: 740px;
  margin: 16px 0 0;
  color: var(--theme-text-muted);
  font-size: 16px;
  line-height: 1.75;
  font-weight: 650;
}

/* CHOICE PAGE */

.pricing-choice-page {
  min-height: calc(100vh - 110px);
  display: block;
  padding-top: 96px;
}

.pricing-choice-hero {
  width: 100%;
  margin-bottom: 0;
  display: block;
  padding: 0 0 56px;
  border-bottom: 0;
}

.pricing-choice-hero::after {
  display: none;
}

.pricing-choice-hero .pricing-hero-copy {
  max-width: 920px;
  margin: 0 auto 42px;
  text-align: center;
}

.pricing-choice-hero .pricing-hero-copy h1 {
  max-width: 920px;
  margin: 0 auto;
}

.pricing-choice-hero .pricing-hero-copy p {
  max-width: 780px;
  margin: 18px auto 0;
}

.pricing-choice-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
  width: 100%;
  max-width: 980px;
  margin: 0 auto;
}

.pricing-choice-card {
  position: relative;
  min-height: 300px;
  padding: 34px 76px 34px 34px;
  border-radius: 20px;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--theme-surface) 96%, transparent),
      var(--theme-surface)
    );
  border: 1px solid var(--theme-border, rgba(var(--theme-shadow-rgb), 0.11));
  box-shadow: 0 14px 34px rgba(var(--theme-shadow-rgb), 0.06);
  cursor: pointer;
  text-align: start;
  font: inherit;
  overflow: hidden;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease;
}

.pricing-page[dir="rtl"] .pricing-choice-card {
  padding: 34px 34px 34px 76px;
}

.pricing-choice-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 3px;
  background: transparent;
}

.pricing-choice-card:hover,
.pricing-choice-card:focus-visible {
  transform: translateY(-2px);
  border-color: rgba(var(--theme-primary-rgb), 0.38);
  box-shadow: 0 20px 44px rgba(var(--theme-primary-rgb), 0.11);
}

.pricing-choice-card:hover,
.pricing-choice-card:focus-visible {
  background:
    linear-gradient(
      180deg,
      rgba(var(--theme-primary-rgb), 0.045),
      transparent 58%
    ),
    var(--theme-surface);
}

.pricing-choice-card:hover::before,
.pricing-choice-card:focus-visible::before {
  background: var(
    --theme-gradient,
    linear-gradient(90deg, var(--theme-primary), var(--theme-text))
  );
}

.pricing-choice-card span {
  display: inline-flex;
  margin-bottom: 18px;
  color: var(--color-accent-text);
  font-size: 13px;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pricing-page[dir="rtl"] .pricing-choice-card span {
  letter-spacing: 0;
}

.pricing-choice-card strong {
  display: block;
  color: var(--theme-text);
  font-size: clamp(30px, 3vw, 42px);
  line-height: 1.04;
  font-weight: 950;
  letter-spacing: -0.035em;
}

.pricing-choice-card p {
  max-width: 420px;
  margin: 18px 0 0;
  color: var(--theme-text-muted);
  font-size: 16px;
  line-height: 1.7;
  font-weight: 650;
}

.pricing-choice-card em {
  position: absolute;
  inset-inline-end: 28px;
  bottom: 28px;
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: var(--theme-surface-2);
  color: var(--color-accent-text);
  font-style: normal;
  font-size: 20px;
  font-weight: 950;
  transition:
    background 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease;
}

.pricing-choice-card:hover em,
.pricing-choice-card:focus-visible em {
  background: var(--theme-primary);
  color: var(--theme-text-inverse);
  transform: translateX(2px);
}

.pricing-page[dir="rtl"] .pricing-choice-card:hover em,
.pricing-page[dir="rtl"] .pricing-choice-card:focus-visible em {
  transform: translateX(-2px);
}

/* INNER PAGES */

.pricing-inner-header {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 30px;
  padding-bottom: 28px;
  border-bottom: 1px solid var(--theme-border, rgba(var(--theme-shadow-rgb), 0.1));
}

.pricing-back-button {
  min-height: 42px;
  border-radius: 999px;
  padding: 10px 15px;
  border: 1px solid var(--color-border-control);
  background: var(--theme-surface);
  color: var(--theme-text);
  cursor: pointer;
  font: inherit;
  font-size: 14px;
  font-weight: 900;
  white-space: nowrap;
  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease,
    box-shadow 0.18s ease;
}

.pricing-back-button:hover {
  transform: translateY(-1px);
  color: var(--color-accent-text);
  border-color: rgba(var(--theme-primary-rgb), 0.38);
  box-shadow: 0 12px 28px rgba(var(--theme-shadow-rgb), 0.08);
}

.pricing-section-heading {
  max-width: 840px;
}

.pricing-section-heading h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: clamp(28px, 4vw, 38px);
  line-height: 1.1;
  font-weight: 950;
  letter-spacing: -0.04em;
}

/* PLAN GRID */

.pricing-plan-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

/* PLAN CARD */

.pricing-plan-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 100%;
  padding: 24px;
  border-radius: 20px;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--theme-surface) 96%, transparent),
      var(--theme-surface)
    );
  border: 1px solid var(--theme-border, rgba(var(--theme-shadow-rgb), 0.11));
  box-shadow: 0 14px 34px rgba(var(--theme-shadow-rgb), 0.06);
  overflow: hidden;
}

.pricing-plan-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 3px;
  background: transparent;
}

.pricing-plan-card.recommended {
  border-color: color-mix(
    in srgb,
    var(--theme-primary) 40%,
    var(--theme-border, rgba(var(--theme-shadow-rgb), 0.11))
  );
  box-shadow: 0 20px 44px rgba(var(--theme-primary-rgb), 0.12);
}

.pricing-plan-card.recommended::before {
  background: var(
    --theme-gradient,
    linear-gradient(90deg, var(--theme-primary), var(--theme-text))
  );
}

.pricing-plan-content {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.pricing-plan-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.pricing-plan-top span,
.pricing-plan-top strong {
  display: inline-flex;
  min-height: 28px;
  align-items: center;
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 900;
}

.pricing-plan-top span {
  background: var(--theme-surface-2);
  color: var(--theme-text-muted);
}

.pricing-plan-top strong {
  background: rgba(var(--theme-primary-rgb), 0.1);
  color: var(--color-accent-text);
}

.pricing-plan-card h3 {
  margin: 20px 0 10px;
  color: var(--theme-text);
  font-size: 26px;
  line-height: 1.15;
  font-weight: 950;
  letter-spacing: -0.035em;
}

.pricing-plan-description {
  min-height: 78px;
  margin: 0 0 20px;
  color: var(--theme-text-muted);
  font-size: 14px;
  line-height: 1.65;
  font-weight: 650;
}

.pricing-price-row {
  display: flex;
  align-items: baseline;
  gap: 7px;
  margin-bottom: 20px;
}

.pricing-price-row strong {
  color: var(--theme-text);
  font-size: 42px;
  line-height: 1;
  font-weight: 950;
  letter-spacing: -0.05em;
}

.pricing-price-row span {
  color: var(--theme-text-muted);
  font-size: 14px;
  font-weight: 800;
}

/* META BLOCKS */

.pricing-plan-meta {
  display: grid;
  gap: 10px;
}

.pricing-plan-meta div,
.pricing-limit-list {
  padding: 14px;
  border-radius: 14px;
  background: var(--theme-surface-2);
  border: 1px solid var(--theme-border, rgba(var(--theme-shadow-rgb), 0.08));
}

.pricing-plan-meta span,
.pricing-limit-list > span,
.pricing-selected-modules > span {
  display: block;
  margin-bottom: 6px;
  color: var(--theme-text);
  font-size: 12px;
  font-weight: 950;
}

.pricing-plan-meta p {
  margin: 0;
  color: var(--theme-text-muted);
  font-size: 13px;
  line-height: 1.55;
  font-weight: 650;
}

.pricing-limit-list {
  margin-top: 10px;
}

.pricing-limit-list ul,
.pricing-feature-list,
.pricing-selected-modules ul {
  padding: 0;
  margin: 0;
  list-style: none;
}

.pricing-limit-list ul {
  display: grid;
  gap: 7px;
}

.pricing-limit-list li {
  color: var(--theme-text-muted);
  font-size: 13px;
  font-weight: 750;
}

/* FEATURES */

.pricing-feature-list {
  display: grid;
  gap: 10px;
  margin-top: 18px;
}

.pricing-feature-list li {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  color: var(--theme-text);
  font-size: 13px;
  line-height: 1.45;
  font-weight: 750;
}

.pricing-page[dir="rtl"] .pricing-feature-list li {
  flex-direction: row-reverse;
}

.pricing-feature-list li span {
  width: 18px;
  min-width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 950;
}

.pricing-feature-list li.included span {
  background: rgba(var(--theme-success-rgb), 0.11);
  color: var(--color-status-success-text);
}

.pricing-feature-list li.muted {
  color: var(--theme-text-muted);
}

.pricing-feature-list li.muted span {
  background: color-mix(in srgb, var(--theme-text-muted) 12%, transparent);
  color: var(--theme-text-muted);
}

/* BUTTONS */

.pricing-plan-footer {
  margin-top: 22px;
}

.pricing-plan-button {
  width: 100%;
  min-height: 46px;
  border-radius: 12px;
  padding: 12px 16px;
  cursor: pointer;
  font: inherit;
  font-size: 14px;
  font-weight: 950;
  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    border-color 0.18s ease,
    background 0.18s ease,
    color 0.18s ease;
}

.pricing-plan-button:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}

.pricing-plan-button:hover:not(:disabled) {
  transform: translateY(-1px);
}

.pricing-plan-button.primary {
  border: 0;
  background: var(
    --theme-gradient,
    linear-gradient(135deg, var(--theme-text), var(--theme-primary))
  );
  color: var(--theme-text-inverse);
  box-shadow: 0 14px 28px rgba(var(--theme-primary-rgb), 0.2);
}

.pricing-plan-button.primary:hover:not(:disabled) {
  box-shadow: 0 18px 34px rgba(var(--theme-primary-rgb), 0.26);
}

.pricing-plan-button.secondary {
  border: 1px solid var(--theme-border, rgba(var(--theme-shadow-rgb), 0.14));
  background: var(--theme-surface);
  color: var(--theme-text);
}

.pricing-plan-button.secondary:hover:not(:disabled) {
  border-color: rgba(var(--theme-primary-rgb), 0.38);
  color: var(--color-accent-text);
}

/* CUSTOM PLAN */

.pricing-custom-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 370px;
  gap: 20px;
  align-items: start;
}

.pricing-module-list {
  display: grid;
  gap: 12px;
}

.pricing-module-card {
  display: flex;
  gap: 14px;
  width: 100%;
  padding: 18px;
  border-radius: 18px;
  background: var(--theme-surface);
  border: 1px solid var(--theme-border, rgba(var(--theme-shadow-rgb), 0.11));
  box-shadow: 0 12px 28px rgba(var(--theme-shadow-rgb), 0.05);
  cursor: pointer;
  text-align: start;
  font: inherit;
  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    background 0.18s ease;
}

.pricing-module-card:hover,
.pricing-module-card.selected {
  transform: translateY(-1px);
  border-color: rgba(var(--theme-primary-rgb), 0.38);
  box-shadow: 0 16px 34px rgba(var(--theme-primary-rgb), 0.1);
}

.pricing-module-card.selected {
  background:
    linear-gradient(
      180deg,
      rgba(var(--theme-primary-rgb), 0.035),
      transparent
    ),
    var(--theme-surface);
}

.pricing-module-check span {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: var(--theme-surface-2);
  color: var(--theme-text-muted);
  font-size: 14px;
  font-weight: 950;
}

.pricing-module-card.selected .pricing-module-check span {
  background: var(--theme-primary);
  color: var(--theme-text-inverse);
}

.pricing-module-content {
  flex: 1;
}

.pricing-module-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 6px;
}

.pricing-module-head strong {
  color: var(--theme-text);
  font-size: 16px;
  font-weight: 950;
}

.pricing-module-head em {
  color: var(--theme-text);
  font-style: normal;
  font-size: 14px;
  font-weight: 950;
  white-space: nowrap;
}

.pricing-module-content p {
  margin: 0;
  color: var(--theme-text-muted);
  font-size: 14px;
  line-height: 1.6;
  font-weight: 650;
}

.pricing-module-content small {
  display: block;
  margin-top: 8px;
  color: var(--color-accent-text);
  font-size: 12px;
  line-height: 1.5;
  font-weight: 900;
}

/* SUMMARY */

.pricing-custom-summary {
  position: sticky;
  top: 92px;
  padding: 22px;
  border-radius: 20px;
  background:
    linear-gradient(
      180deg,
      rgba(var(--theme-primary-rgb), 0.045),
      transparent 42%
    ),
    var(--theme-surface);
  border: 1px solid rgba(var(--theme-primary-rgb), 0.24);
  box-shadow: 0 18px 42px rgba(var(--theme-shadow-rgb), 0.08);
}

.pricing-custom-summary h3 {
  margin: 0;
  color: var(--theme-text);
  font-size: 24px;
  font-weight: 950;
  letter-spacing: -0.035em;
}

.pricing-custom-summary > p {
  margin: 10px 0 18px;
  color: var(--theme-text-muted);
  font-size: 14px;
  line-height: 1.65;
  font-weight: 650;
}

.pricing-custom-price {
  padding: 16px;
  border-radius: 16px;
  background: var(--theme-surface-2);
  border: 1px solid var(--theme-border, rgba(var(--theme-shadow-rgb), 0.08));
  margin-bottom: 16px;
}

.pricing-custom-price span {
  display: block;
  margin-bottom: 8px;
  color: var(--theme-text-muted);
  font-size: 12px;
  font-weight: 900;
}

.pricing-custom-price strong {
  color: var(--theme-text);
  font-size: 34px;
  line-height: 1;
  font-weight: 950;
  letter-spacing: -0.04em;
}

.pricing-custom-price small {
  margin-inline-start: 5px;
  color: var(--theme-text-muted);
  font-size: 13px;
  font-weight: 800;
}

.pricing-selected-modules {
  margin-bottom: 16px;
}

.pricing-selected-modules ul {
  display: grid;
  gap: 8px;
}

.pricing-selected-modules li {
  display: flex;
  justify-content: space-between;
