   ============================================================ */
.pricing-catalog-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 28px;
  margin-bottom: 18px;
}

.pricing-catalog-heading > div {
  display: grid;
  gap: 4px;
}

.pricing-catalog-heading > div > span,
.pricing-includes-label {
  color: var(--color-accent-text);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pricing-catalog-heading h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: clamp(25px, 3vw, 34px);
  line-height: 1.15;
}

