/* ============================================================
   GLOBAL MADAR GRADIENT BUTTON SYSTEM
   Applies to main buttons across the whole website
   ============================================================ */

:root {
  --madar-bg: var(--theme-bg-soft);
  --madar-navy: var(--theme-text);
  --madar-navy-dark: var(--theme-bg);
  --madar-red: var(--theme-primary);
  --madar-red-dark: var(--theme-primary-hover);
  --madar-cream: var(--theme-bg-soft);
  --madar-gradient: var(--theme-gradient);
  --madar-gradient-hover: var(--theme-gradient-hover);
  --madar-button-shadow: 0 10px 24px rgba(var(--theme-primary-rgb), 0.22);
  --madar-button-shadow-hover: 0 14px 30px rgba(var(--theme-primary-rgb), 0.3);
}

/* Main action buttons across pages */
.btn-signup,
.register-submit,
.login-submit,
.forgot-card button,
.contact-form button,
.plan-btn.primary,
.pricing-card:hover .plan-btn,
.primary-action,
.small-action {
  border: none;
  background: var(--madar-gradient);
  color: var(--theme-text-inverse);
  box-shadow: var(--madar-button-shadow);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease;
}

.btn-signup:hover,
.register-submit:hover,
.login-submit:hover,
.forgot-card button:hover,
.contact-form button:hover,
.plan-btn.primary:hover,
.pricing-card:hover .plan-btn:hover,
.primary-action:hover,
.small-action:hover {
  background: var(--madar-gradient-hover);
  color: var(--theme-text-inverse);
  transform: translateY(-2px);
  box-shadow: var(--madar-button-shadow-hover);
}

/* Outline/secondary buttons: gradient on hover */
.btn-login,
.plan-btn,
.secondary-action,
.lang-toggle {
  background: transparent;
  color: var(--madar-navy);
  border: 1.5px solid rgba(var(--theme-shadow-rgb), 0.25);
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease;
}

.btn-login:hover,
.plan-btn:hover,
.secondary-action:hover,
.lang-toggle:hover {
  background: var(--madar-gradient);
  border-color: transparent;
  color: var(--theme-text-inverse);
