  animation-delay: calc(var(--split-text-index) * var(--split-text-delay, 0.035s));
}

.split-text:hover {
  transform: translateY(-0.04em);
}

@keyframes splitTextReveal {
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

@keyframes splitTextLift {
  0%,
  100% {
    transform: translateY(0);
  }

  45% {
    transform: translateY(-0.12em);
  }
}

@media (prefers-reduced-motion: reduce) {
  .split-text-character {
    animation: none;
    opacity: 1;
    transform: none;
  }
}

/* ============================================================
   APP SHELL
   ============================================================ */

.app-shell {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.app-main {
  display: flex;
  flex-direction: column;
  flex: 1;
}

html,
body,
#root {
  scroll-behavior: auto !important;
  overflow-anchor: none;
}
/* ============================================================
   GLOBAL DASHBOARD BOX SIZING
   ============================================================ */

*,
*::before,
*::after {
  box-sizing: border-box;
}

/* ============================================================
   DASHBOARD LAYOUT
   ============================================================ */

.admin-dashboard-layout {
  display: flex;
  flex-direction: row;
  width: 100%;
  min-height: 100vh;
  background: var(--theme-bg-soft);
  direction: ltr;
  overflow-x: hidden;
}

.admin-dashboard-layout.is-ltr,
.admin-dashboard-layout[dir="ltr"] {
  direction: ltr;
}

.admin-dashboard-layout.is-rtl,
.admin-dashboard-layout[dir="rtl"] {
  direction: rtl;
}

/* ============================================================
   DASHBOARD MAIN PAGE
   Normal dashboard pages use full 260px sidebar.
   ============================================================ */

.admin-dashboard-page {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  width: auto;
  min-height: 100vh;

  margin-inline-start: 260px;
  margin-inline-end: 0;

  background: var(--theme-bg-soft);

  padding: 44px 5% 70px;
  color: var(--theme-text);
  overflow-x: hidden;
}

.notification-bell {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.notification-bell-button {
  position: relative;
  min-width: 46px;
  min-height: 46px;
  border: 1px solid var(--theme-border);
  border-radius: 14px;
  background: var(--theme-surface);
  color: var(--theme-text);
  box-shadow: 0 14px 34px rgba(var(--theme-shadow-rgb), 0.1);

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;

  padding: 0 14px;
  cursor: pointer;
  font: inherit;
  font-size: 13px;
  font-weight: 900;
  line-height: 1;

  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    color 0.18s ease,
    transform 0.18s ease,
    box-shadow 0.18s ease;
}

.notification-bell-button:hover,
.notification-bell.is-active .notification-bell-button {
  border-color: transparent;
  background: transparent;
  color: var(--color-accent-text);
  transform: none;
  box-shadow: none;
}

.notification-bell-label {
  white-space: nowrap;
}

.notification-bell-badge {
  position: absolute;
  top: 5px;
  inset-inline-end: 5px;
  min-width: 17px;
  height: 17px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--theme-primary);
  color: var(--theme-text-inverse);
  border: 2px solid var(--theme-surface);

  display: inline-flex;
  align-items: center;
  justify-content: center;

  font-size: 10px;
  font-weight: 950;
  line-height: 1;
}

.admin-sidebar .notification-bell {
  width: 100%;
  margin: 0 0 10px;
}

.admin-sidebar .notification-bell-button {
  width: 100%;
  justify-content: flex-start;
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

.admin-sidebar .notification-bell-button:hover,
.admin-sidebar .notification-bell.is-active .notification-bell-button {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
  color: var(--color-accent-text);
}

.admin-sidebar .notification-bell.is-compact .notification-bell-button {
  width: 46px;
  min-width: 46px;
  height: 46px;
  min-height: 46px;
  padding: 0;
  margin-inline: auto;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.admin-sidebar:not(.is-compact) .notification-bell-button {
  display: grid;
  grid-template-columns: 20px minmax(0, max-content) auto;
  column-gap: 14px;
  min-height: 46px;
  padding: 12px 14px;
  align-items: center;
  justify-content: start;
}

.admin-sidebar:not(.is-compact) .notification-bell-label {
  grid-column: 2;
  grid-row: 1;
  min-width: 0;
  overflow: hidden;
  text-align: start;
  text-overflow: ellipsis;
}

.admin-sidebar:not(.is-compact) .notification-bell-badge {
  position: static;
  grid-column: 3;
  grid-row: 1;
  align-self: center;
  justify-self: start;
  margin-inline-start: 4px;
  min-width: 16px;
  height: 16px;
  padding: 0 5px;
  border: 0;
}

.notification-popover {
  position: fixed;
  z-index: 80;
  width: min(330px, calc(100vw - 32px));
  max-height: min(520px, calc(100vh - 40px));
  overflow: hidden;
  border: 1px solid var(--theme-border);
  border-radius: 16px;
  background: var(--theme-surface);
  color: var(--theme-text);
  box-shadow: 0 22px 60px rgba(var(--theme-shadow-rgb), 0.18);
}

.notification-popover-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--theme-border);
}

.notification-popover-header strong {
  font-size: 14px;
  font-weight: 950;
}

.notification-popover-header span {
  color: var(--color-accent-text);
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
}

.notification-popover-list {
  max-height: 360px;
  overflow-y: auto;
}

.notification-popover-list article {
  display: grid;
  grid-template-columns: 12px minmax(0, 1fr);
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--theme-border);
}

.notification-popover-list article.is-unread {
  background: rgba(var(--theme-primary-rgb), 0.045);
}

.notification-popover-dot {
  width: 8px;
  height: 8px;
  margin-top: 5px;
  border-radius: 999px;
  background: var(--theme-border-strong);
}

.notification-popover-list article.is-unread .notification-popover-dot {
  background: var(--theme-primary);
}

.notification-popover-list strong {
  display: block;
  color: var(--theme-text);
  font-size: 13px;
  font-weight: 950;
  line-height: 1.25;
}

.notification-popover-list p {
  margin: 4px 0 0;
  color: var(--theme-text-soft);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.4;
}

.notification-popover-list time {
  display: block;
  margin-top: 6px;
  color: var(--theme-text-muted);
  font-size: 11px;
  font-weight: 800;
}

.notification-popover-view-all {
  width: 100%;
  min-height: 48px;
  border: 0;
  background: transparent;
  color: var(--color-accent-text);
  cursor: pointer;
  font: inherit;
  font-size: 13px;
  font-weight: 950;
}

.notification-popover-view-all:hover {
  background: var(--theme-primary-soft);
}

.notification-toast-viewport {
  position: fixed;
  z-index: 120;
  top: 20px;
  inset-inline-end: 20px;
  width: min(380px, calc(100vw - 32px));
  display: grid;
  gap: 10px;
  pointer-events: none;
}

.notification-toast {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: start;
  gap: 10px;
  padding: 13px;
  border: 1px solid var(--theme-border);
  border-radius: 16px;
  background: var(--theme-surface);
  color: var(--theme-text);
  box-shadow: 0 18px 48px rgba(var(--theme-shadow-rgb), 0.2);
  pointer-events: auto;
  animation: notification-toast-enter 180ms ease-out;
}

.notification-toast-icon {
  width: 34px;
  height: 34px;
  border-radius: 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--theme-primary-soft);
  color: var(--color-accent-text);
}

.notification-toast-content,
.notification-toast-dismiss {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
}

.notification-toast-content {
  min-width: 0;
  padding: 1px 0;
  text-align: start;
}

.notification-toast-content strong,
.notification-toast-content span {
  display: block;
  overflow-wrap: anywhere;
}

.notification-toast-content strong {
  font-size: 13px;
  font-weight: 950;
  line-height: 1.3;
}

.notification-toast-content span {
  margin-top: 4px;
  color: var(--theme-text-soft);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.4;
}

.notification-toast-dismiss {
  width: 32px;
  height: 32px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--theme-text-soft);
}

.notification-toast-content:focus-visible,
.notification-toast-dismiss:focus-visible {
  outline: 2px solid var(--theme-primary);
  outline-offset: 2px;
}

.notification-toast-dismiss:hover {
  background: var(--theme-primary-soft);
  color: var(--color-accent-text);
}

@keyframes notification-toast-enter {
  from {
    opacity: 0;
    transform: translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .notification-toast {
    animation: none;
  }
}

@media (max-width: 600px) {
  .notification-toast-viewport {
    top: 12px;
    inset-inline: 12px;
    width: auto;
  }
}

.notifications-page {
  width: min(1120px, 100%);
  margin: 0 auto;
  display: grid;
  gap: 18px;
  color: var(--theme-text);
  color-scheme: inherit;
}

/* Keep Notifications on the same app canvas as Calendar. The global
   data-theme tokens update this route immediately when the theme changes. */
.admin-dashboard-page:has(> .notifications-page) {
  background: var(--theme-bg);
}

.notification-popover {
  color-scheme: inherit;
}

.notifications-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--theme-border);
}

.notifications-kicker,
.notifications-summary-grid span,
.notifications-group-header span,
.notifications-title-row span {
  color: var(--color-accent-text);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.notifications-page-header h1 {
  margin: 6px 0 8px;
  color: var(--theme-text);
  font-size: clamp(30px, 4vw, 48px);
  line-height: 1.05;
  font-weight: 950;
  letter-spacing: -0.04em;
}

.notifications-page-header p {
  margin: 0;
  max-width: 620px;
  color: var(--theme-text-soft);
  font-size: 16px;
  line-height: 1.6;
}

.notifications-header-count {
  min-width: 132px;
  min-height: 54px;
  border: 1px solid var(--theme-border);
  border-radius: 14px;
  background: var(--theme-surface);
  color: var(--color-accent-text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 14px;
}

.notifications-header-count strong {
  color: var(--theme-text);
  font-size: 22px;
  font-weight: 950;
}

.notifications-header-count span {
  color: var(--theme-text-soft);
  font-size: 12px;
  font-weight: 900;
}

.notifications-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.notifications-actions button {
  min-height: 40px;
  border: 1px solid var(--theme-border);
  border-radius: 12px;
  background: var(--theme-surface);
  color: var(--theme-text);
  font-weight: 900;
  padding: 0 14px;
  cursor: pointer;
}

.notifications-actions button:hover:not(:disabled) {
  border-color: var(--color-accent-text);
  color: var(--color-accent-text);
}

.notifications-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.notifications-actions span {
  color: var(--theme-text-soft);
  font-size: 13px;
  font-weight: 800;
}

.notifications-summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.notifications-summary-grid article {
  min-height: 96px;
  border: 1px solid var(--theme-border);
  border-radius: 14px;
  background: var(--theme-surface);
  padding: 16px;
}

.notifications-summary-grid strong {
  display: block;
  margin-top: 10px;
  color: var(--theme-text);
  font-size: 30px;
  line-height: 1;
  font-weight: 950;
}

.notifications-board {
  display: grid;
  gap: 16px;
}

.notifications-group {
  border: 1px solid var(--theme-border);
  border-radius: 16px;
  background: var(--theme-surface);
  overflow: hidden;
}

.notifications-group-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--theme-border);
}

.notifications-group-header h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: 18px;
  font-weight: 950;
}

.notifications-list {
  display: grid;
}

.notifications-list article {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr) auto;
  align-items: start;
  gap: 14px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--theme-border);
}

.notifications-list article:last-child {
  border-bottom: 0;
}

.notifications-list article.is-unread {
  background: rgba(var(--theme-primary-rgb), 0.045);
}

.notifications-status {
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  color: var(--theme-text-muted);
}

.notifications-list article.is-unread .notifications-status {
  color: var(--color-accent-text);
}

.notifications-copy {
  min-width: 0;
}

.notifications-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.notifications-title-row h3 {
  margin: 0;
  color: var(--theme-text);
  font-size: 15px;
  font-weight: 950;
  line-height: 1.25;
}

.notifications-copy p {
  margin: 6px 0 0;
  color: var(--theme-text-soft);
  font-size: 13px;
  font-weight: 750;
  line-height: 1.45;
}

.notifications-copy time {
  display: block;
  margin-top: 8px;
  color: var(--theme-text-muted);
  font-size: 12px;
  font-weight: 850;
}

.notifications-state {
  min-width: 68px;
  border-radius: 999px;
  background: var(--theme-surface-2);
  color: var(--theme-text-soft);
  padding: 6px 10px;
  text-align: center;
  font-size: 12px;
  font-weight: 950;
}

.notifications-list article.is-unread .notifications-state {
  background: var(--theme-primary-soft);
  color: var(--color-accent-text);
}

@media (max-width: 760px) {
  .notification-popover {
    max-height: calc(100vh - 96px);
  }

  .notifications-page {
    gap: 14px;
  }

  .notifications-page-header {
    display: grid;
  }

  .notifications-header-count {
    width: 100%;
    justify-content: flex-start;
  }

  .notifications-summary-grid {
    grid-template-columns: 1fr;
  }

  .notifications-list article {
    grid-template-columns: 24px minmax(0, 1fr);
  }

  .notifications-state {
    grid-column: 2;
    justify-self: start;
  }

  .notifications-title-row {
    display: grid;
    justify-content: stretch;
    gap: 6px;
  }
}

.admin-dashboard-layout.is-rtl .admin-dashboard-page,
.admin-dashboard-layout[dir="rtl"] .admin-dashboard-page {
  margin-inline-start: 0;
  margin-inline-end: 260px;
  margin-left: 0 !important;
  margin-right: 260px !important;
  direction: rtl;
  text-align: right;
}

.admin-dashboard-layout.is-ltr .admin-dashboard-page,
.admin-dashboard-layout[dir="ltr"] .admin-dashboard-page {
  margin-left: 260px;
  margin-right: 0;
  direction: ltr;
  text-align: left;
}

.admin-dashboard-shell {
  width: min(1280px, 100%);
  margin: 0 auto;
}

.admin-dashboard-header {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: flex-start;
  margin-bottom: 28px;
}

.admin-dashboard-header h1 {
  margin: 0 0 10px;
  color: var(--theme-text);
  font-size: clamp(32px, 4vw, 48px);
  line-height: 1.05;
  font-weight: 900;
  letter-spacing: -0.05em;
}

.admin-dashboard-header p {
  margin: 0;
  color: var(--theme-text-soft);
  font-size: 17px;
  line-height: 1.7;
  max-width: 720px;
}

/* ============================================================
   PAGEBUILDER SINGLE-TAB DASHBOARD PAGES
   Used by /builder-data and /builder-responses.
   These pages use the compact icon sidebar, so content starts
   after 76px, not 260px.
   ============================================================ */

.admin-dashboard-layout:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) {
  margin-left: 72px !important;
  margin-right: 0 !important;
  width: calc(100vw - 72px) !important;
  max-width: calc(100vw - 72px) !important;
  padding: 0 !important;
  overflow-x: hidden !important;
  background: var(--theme-bg-soft) !important;
}

.admin-dashboard-layout-builder .admin-dashboard-page {
  margin-left: 72px !important;
  margin-right: 0 !important;
  width: calc(100vw - 72px) !important;
  max-width: calc(100vw - 72px) !important;
  padding: 0 !important;
  overflow-x: hidden !important;
}

.admin-dashboard-layout-builder.is-rtl .admin-dashboard-page,
.admin-dashboard-layout-builder[dir="rtl"] .admin-dashboard-page {
  margin-left: 0 !important;
  margin-right: 72px !important;
}

.admin-dashboard-layout.is-rtl:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page),
.admin-dashboard-layout[dir="rtl"]:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) {
  margin-left: 0 !important;
  margin-right: 72px !important;
  width: calc(100vw - 72px) !important;
  max-width: calc(100vw - 72px) !important;
  direction: rtl;
  text-align: right;
}

/* Keep the data/responses workspace visually aligned */
.admin-dashboard-layout:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .page-builder {
  width: 100% !important;
  max-width: 100% !important;
  min-height: 100vh;
}

.admin-dashboard-layout:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-desktop-shell {
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
}

.admin-dashboard-layout:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-main,
.admin-dashboard-layout:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-workspace,
.admin-dashboard-layout:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-panel {
  min-width: 0 !important;
}

/* The data analysis page itself */
.admin-dashboard-layout:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .daw-page {
  --daw-page-gutter: clamp(18px, 2vw, 34px);

  width: calc(100% - (var(--daw-page-gutter) * 2)) !important;
