}

.admin-dashboard-layout.is-rtl:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .daw-page,
.admin-dashboard-layout[dir="rtl"]:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .daw-page {
  margin-left: var(--daw-page-gutter) !important;
  margin-right: var(--daw-page-gutter) !important;
}

/* Better alignment for builder demo header above the data page */
.admin-dashboard-layout:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-topbar,
.admin-dashboard-layout:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-header,
.admin-dashboard-layout:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-demo-header {
  padding-left: clamp(18px, 2vw, 34px) !important;
  padding-right: clamp(18px, 2vw, 34px) !important;
}

.admin-dashboard-layout.is-rtl:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-topbar,
.admin-dashboard-layout.is-rtl:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-header,
.admin-dashboard-layout.is-rtl:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-demo-header,
.admin-dashboard-layout[dir="rtl"]:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-topbar,
.admin-dashboard-layout[dir="rtl"]:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-header,
.admin-dashboard-layout[dir="rtl"]:has(.page-builder) .admin-dashboard-page:not(.page-builder-dashboard-page) .builder-demo-header {
  direction: rtl;
  text-align: right;
}

/* ============================================================
   DASHBOARD MOBILE MENU BUTTON
   ============================================================ */

.dashboard-mobile-menu-button {
  display: none;
  position: fixed;
