/* ============================================================
   SIDEBAR â€” CLEAN RTL/LTR VERSION
   ============================================================ */

.admin-dashboard-layout {
  --dashboard-sidebar-width: 232px;
}

.admin-dashboard-layout.admin-dashboard-layout-builder {
  --dashboard-sidebar-width: 232px;
}

.admin-sidebar {
  position: fixed;
  top: 0;
  bottom: 0;

  width: 232px;
  min-width: 232px;
  max-width: 232px;
  height: 100vh;

  background: var(--theme-surface);
  padding: 28px 18px 18px;

  display: flex;
  flex-direction: column;

  z-index: 50;
  overflow-y: auto;
  overflow-x: hidden;

  direction: ltr;
  text-align: start;

  border-inline-end: 1px solid rgba(var(--theme-shadow-rgb), 0.12);
  border-inline-start: none;

  inset-inline-start: 0;
  inset-inline-end: auto;
}

.admin-sidebar.is-ltr,
.admin-sidebar[dir="ltr"] {
  direction: ltr;
  text-align: start;
  left: 0;
  right: auto;
  inset-inline-start: 0;
  inset-inline-end: auto;
  border-inline-end: 1px solid rgba(var(--theme-shadow-rgb), 0.12);
  border-inline-start: none;
}

.admin-sidebar.is-rtl,
.admin-sidebar[dir="rtl"] {
  direction: rtl;
  text-align: start;
  left: auto;
  right: 0;
  inset-inline-start: auto;
  inset-inline-end: 0;
  border-inline-start: 1px solid rgba(var(--theme-shadow-rgb), 0.12);
  border-inline-end: none;
}

.admin-dashboard-layout.is-rtl .admin-sidebar,
.admin-dashboard-layout[dir="rtl"] .admin-sidebar {
  direction: rtl;
  text-align: start;
  left: auto !important;
  right: 0 !important;
  inset-inline-start: auto;
  inset-inline-end: 0;
  border-inline-start: 1px solid rgba(var(--theme-shadow-rgb), 0.12);
  border-inline-end: none;
}

.admin-sidebar-top {
  flex: 0 1 auto;
  min-height: 0;

  display: flex;
  flex-direction: column;
}

.admin-sidebar-bottom {
  margin-top: auto;
  padding-top: 18px;
  flex: 0 0 auto;

  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* ============================================================
   BRAND
   ============================================================ */

.admin-sidebar-brand {
  width: 100%;
  max-width: 100%;

  border: none;
  border-radius: 16px;
  background: transparent;
  color: inherit;

  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 12px;

  margin: 2px 0 24px;
  padding: 4px 2px;

  cursor: pointer;
  text-align: start;
  font: inherit;
  direction: inherit;

  transition:
    background 0.18s ease,
    transform 0.18s ease;
}

.admin-sidebar-brand:hover {
  background: rgba(var(--theme-primary-rgb), 0.06);
  transform: translateY(-1px);
}

.admin-sidebar-icon {
  width: 48px;
  height: 48px;
  min-width: 48px;

  border-radius: 15px;

  display: grid;
  place-items: center;

  color: var(--theme-text-inverse);
  background: var(--theme-primary);

  box-shadow:
    0 14px 30px rgba(var(--theme-primary-rgb), 0.24),
    inset 0 1px 0 rgba(var(--theme-text-inverse-rgb), 0.18);

  flex-shrink: 0;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
}

.admin-sidebar-brand-text {
  min-width: 0;
  flex: 1 1 auto;
  display: block;
  text-align: start;
}

.admin-sidebar-brand strong {
  display: block;

  color: var(--theme-text);
  font-size: 18px;
  font-weight: 950;
  line-height: 1.05;
  letter-spacing: -0.02em;

  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.admin-sidebar-brand-text > span {
  display: block;

  color: var(--theme-text-muted);
  font-size: 13px;
  font-weight: 850;
  line-height: 1.15;

  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ============================================================
   NAV
   ============================================================ */

.admin-sidebar-nav {
  width: 100%;
  min-height: 0;
  flex: 0 1 auto;
  max-height: none;
  overflow-y: visible;
  overflow-x: hidden;
  padding-bottom: 6px;
  scrollbar-width: thin;

  display: flex;
  flex-direction: column;
  gap: 6px;
}

.admin-sidebar-nav a,
.admin-sidebar-nav button {
  width: 100%;
  min-height: 46px;

  border: none;
  border-radius: 14px;
  background: transparent;
