}

.admin-sidebar-nav button.active {
  font-weight: 950;
}

.admin-sidebar-nav a svg,
.admin-sidebar-nav button svg,
.admin-sidebar svg {
  flex: 0 0 auto;
}

.admin-sidebar-nav a span,
.admin-sidebar-nav button span {
  flex: 1 1 auto;
  min-width: 0;

  display: inline-block;

  text-align: start;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.admin-sidebar:not(.is-compact) .admin-sidebar-nav > button:not(.admin-sidebar-theme-row),
.admin-sidebar:not(.is-compact) .admin-sidebar-nav > a {
  display: grid;
