.settings-toast-error {
  border-color: rgba(var(--theme-danger-rgb), 0.22);
  background: rgba(var(--theme-danger-rgb), 0.06);
}

.settings-toast-error span {
  color: var(--color-accent-text);
}

.settings-toast button {
  width: 30px;
  height: 30px;
  border: 1px solid var(--color-border-control);
  border-radius: 10px;
  display: grid;
  place-items: center;
  color: var(--theme-text);
  background: rgba(var(--theme-shadow-rgb), 0.06);
  cursor: pointer;
  flex: 0 0 30px;
}

.settings-toast button:hover {
  background: rgba(var(--theme-primary-rgb), 0.1);
  color: var(--color-accent-text);
}

@keyframes settingsToastIn {
  from {
    opacity: 0;
    transform: translateY(-8px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.settings-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}

.settings-card {
  min-width: 0;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.12);
  border-radius: 24px;
  background: var(--theme-surface);
  box-shadow: 0 16px 38px rgba(var(--theme-shadow-rgb), 0.07);
}

.settings-profile-card {
  overflow: hidden;
  display: grid;
  gap: 0;
}

.settings-profile-cover {
  min-height: 168px;
  padding: 24px 28px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  background: var(--theme-primary);
  color: var(--theme-text-inverse);
}

.settings-profile-cover div {
  display: grid;
  gap: 8px;
}

.settings-profile-cover span {
  color: rgba(var(--theme-text-inverse-rgb), 0.74);
  font-size: 12px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.settings-profile-cover strong {
  color: var(--theme-text-inverse);
  font-size: clamp(28px, 4vw, 42px);
  line-height: 1.05;
  font-weight: 950;
  letter-spacing: -0.04em;
}

.settings-profile-summary {
  margin: 0 28px;
  padding-top: 24px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 18px;
  align-items: start;
  position: relative;
  z-index: 1;
}

.settings-profile-avatar {
  width: 116px;
  height: 116px;
  border-radius: 28px;
  padding: 6px;
  background: var(--theme-surface);
  box-shadow: 0 18px 36px rgba(var(--theme-shadow-rgb), 0.16);
  margin-top: -88px;
  overflow: hidden;
  flex: 0 0 116px;
}

.settings-profile-avatar img,
.settings-profile-avatar span {
  width: 100%;
  height: 100%;
  border-radius: 22px;
  display: grid;
  place-items: center;
  object-fit: cover;
  object-position: center;
  background: var(--theme-primary);
  color: var(--theme-text-inverse);
  font-size: 42px;
  font-weight: 950;
  line-height: 1;
}

.settings-profile-avatar img {
  display: block;
}

.settings-profile-summary h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: 30px;
  line-height: 1.08;
  font-weight: 950;
  letter-spacing: -0.04em;
}

.settings-profile-summary p {
  margin: 7px 0 0;
  max-width: 620px;
  color: var(--theme-text-muted);
  line-height: 1.55;
  font-weight: 750;
}

.settings-profile-upload {
  min-width: 170px;
}

.settings-profile-body {
  padding: 24px 28px 28px;
  display: grid;
  gap: 18px;
  align-items: start;
}

.settings-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.settings-card label {
  min-width: 0;
  display: grid;
  gap: 8px;
  color: var(--theme-text);
  font-size: 14px;
  font-weight: 950;
}

.settings-card input,
.settings-card textarea {
  width: 100%;
  min-width: 0;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.16);
  border-radius: 16px;
  background: var(--theme-surface);
  color: var(--theme-text);
  padding: 13px 15px;
  font: inherit;
  font-weight: 850;
  outline: none;
}

.settings-card textarea {
  min-height: 88px;
  resize: vertical;
  line-height: 1.5;
}

.settings-wide-field {
  grid-column: 1 / -1;
}

.settings-card input:focus,
.settings-card textarea:focus {
  border-color: rgba(var(--theme-primary-rgb), 0.56);
  box-shadow: 0 0 0 4px rgba(var(--theme-primary-rgb), 0.09);
}

.settings-card input.field-has-error,
.settings-card textarea.field-has-error {
  border-color: rgba(var(--theme-primary-rgb), 0.68);
  background: rgba(var(--theme-primary-rgb), 0.035);
  box-shadow: 0 0 0 4px rgba(var(--theme-primary-rgb), 0.08);
}

.settings-field-error {
  color: var(--color-accent-text);
  font-size: 12px;
  font-weight: 850;
  line-height: 1.35;
}

.settings-file-button {
  cursor: pointer;
  border: 1px dashed rgba(var(--theme-primary-rgb), 0.42);
  border-radius: 16px;
  padding: 16px;
  background: rgba(var(--theme-primary-rgb), 0.06);
  color: var(--color-accent-text) !important;
  text-align: center;
  min-height: 58px;
  align-content: center;
}

.settings-file-button input {
  display: none;
}

.settings-save-button {
  width: 280px;
  max-width: 100%;
  border: 0;
  border-radius: 16px;
  padding: 14px 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  cursor: pointer;
  background: var(--theme-primary);
  color: var(--theme-text-inverse);
  box-shadow: 0 12px 28px rgba(var(--theme-primary-rgb), 0.2);
  font-weight: 950;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    opacity 0.2s ease;
}

.settings-save-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 16px 32px rgba(var(--theme-primary-rgb), 0.24);
}

.settings-save-button:disabled {
  cursor: not-allowed;
  opacity: 0.65;
  transform: none;
}

.settings-profile-actions {
  grid-column: 1 / -1;
  margin: 0 28px 28px;
  display: grid;
  grid-template-columns: 280px 1fr 280px;
  align-items: center;
  gap: 14px;
}

.settings-reset-password-button {
  grid-column: 1;
  justify-self: start;
  width: 280px;
  max-width: 100%;
  border: 1px solid rgba(var(--theme-primary-rgb), 0.22);
  border-radius: 16px;
  padding: 14px 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  cursor: pointer;
  background: rgba(var(--theme-primary-rgb), 0.055);
  color: var(--color-accent-text);
  font-weight: 950;
  box-shadow: none;
  text-decoration: none;
  transition:
    transform 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.settings-reset-password-button:hover {
  transform: translateY(-1px);
  background: rgba(var(--theme-primary-rgb), 0.09);
  border-color: rgba(var(--theme-primary-rgb), 0.38);
  box-shadow: 0 12px 24px rgba(var(--theme-primary-rgb), 0.12);
}

.settings-profile-actions .settings-save-button {
  grid-column: 3;
  justify-self: end;
  width: 280px;
  margin: 0;
}

.settings-page[dir="rtl"] .settings-header,
.settings-page[dir="rtl"] .settings-card {
  text-align: right;
}

.settings-page[dir="rtl"] .settings-profile-actions {
  direction: rtl;
}

.settings-page[dir="rtl"] .settings-reset-password-button {
  grid-column: 1;
  justify-self: start;
}

.settings-page[dir="rtl"] .settings-profile-actions .settings-save-button {
  grid-column: 3;
  justify-self: end;
}

.settings-website-card {
  width: 100%;
  max-width: none;
  margin-inline: 0;
}

.settings-website-card .settings-profile-avatar {
  background: var(--theme-surface);
}

.settings-website-card .settings-profile-avatar span {
  background: var(--theme-primary);
  color: var(--theme-text-inverse);
}

.settings-website-card .settings-profile-avatar svg {
  width: 32px;
  height: 32px;
}

.settings-website-profile-actions {
  grid-template-columns: 1fr 280px;
}

.settings-website-profile-actions .settings-save-button {
  grid-column: 2;
  justify-self: end;
}

.settings-page[dir="rtl"] .settings-website-profile-actions {
  direction: rtl;
  grid-template-columns: 1fr 280px;
}

.settings-page[dir="rtl"]
  .settings-website-profile-actions
  .settings-save-button {
  grid-column: 2;
  justify-self: end;
}

@media (max-width: 900px) {
  .settings-form-grid {
    grid-template-columns: 1fr;
  }

  .settings-profile-summary {
    grid-template-columns: auto minmax(0, 1fr);
    align-items: start;
  }

  .settings-profile-upload {
    grid-column: 1 / -1;
    justify-self: start;
    margin-top: 0;
  }

  .settings-page[dir="rtl"] .settings-profile-upload {
    justify-self: end;
  }
}

@media (max-width: 640px) {
  .settings-page {
    gap: 18px;
  }

  .settings-header h1 {
    font-size: 32px;
  }

  .settings-toast,
  .settings-toast-rtl {
    top: 14px;
    right: 14px;
    left: 14px;
    width: auto;
  }

  .settings-profile-cover {
    min-height: 138px;
    padding: 20px;
  }

  .settings-profile-summary {
    margin: 0 18px;
    padding-top: 20px;
    grid-template-columns: 1fr;
    justify-items: start;
  }

  .settings-page[dir="rtl"] .settings-profile-summary {
    justify-items: end;
  }

  .settings-profile-avatar {
    width: 100px;
    height: 100px;
    border-radius: 24px;
    margin-top: -70px;
  }

  .settings-profile-avatar img,
  .settings-profile-avatar span {
    border-radius: 19px;
  }

  .settings-profile-summary h2 {
    margin-top: 0;
  }

  .settings-profile-body {
    padding: 22px 18px 24px;
  }

  .settings-profile-actions,
  .settings-website-profile-actions {
    width: calc(100% - 36px);
    margin: 0 18px 24px;
    display: flex;
    flex-direction: column;
    align-items: stretch;
  }

  .settings-profile-actions .settings-save-button,
  .settings-reset-password-button,
  .settings-website-profile-actions .settings-save-button {
    width: 100%;
  }

  .settings-profile-upload {
    min-width: 0;
  }
}


.security-mfa-page {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 32px;
}

.security-mfa-header {
  display: grid;
  gap: 8px;
  max-width: 760px;
}

.security-mfa-header span,
.security-mfa-panel-heading p,
.security-mfa-status-grid span,
.security-mfa-factor span,
.security-mfa-factor-counts {
  color: var(--theme-text-muted);
}

.security-mfa-header h1,
.security-mfa-panel h2 {
  margin: 0;
  color: var(--theme-text);
}

.security-mfa-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.security-mfa-panel {
  background: var(--theme-surface);
  border: 1px solid var(--theme-border);
  border-radius: 8px;
  padding: 22px;
  box-shadow: 0 18px 45px rgba(var(--theme-shadow-rgb), 0.08);
}

.security-mfa-enroll-panel {
  grid-column: 1 / -1;
}

.security-mfa-panel-heading {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 18px;
}

.security-mfa-panel-heading svg {
  color: var(--theme-info);
  flex: 0 0 auto;
  margin-top: 3px;
}

.security-mfa-status-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.security-mfa-status-grid div,
.security-mfa-factor {
  border: 1px solid var(--theme-border);
  border-radius: 8px;
  padding: 14px;
  background: var(--theme-surface-2);
}

.security-mfa-status-grid div,
.security-mfa-factor div {
  display: grid;
  gap: 4px;
}

.security-mfa-factor-list {
  display: grid;
  gap: 10px;
}

.security-mfa-factor {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.security-mfa-factor-counts,
.security-mfa-actions,
.security-mfa-enroll-form {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.security-mfa-factor-counts {
  margin-top: 14px;
}

.security-mfa-enroll-form label,
.security-mfa-verify-flow label {
  display: grid;
  gap: 8px;
  min-width: min(100%, 320px);
}

.security-mfa-enroll-form input,
.security-mfa-verify-flow input {
  min-height: 44px;
  border: 1px solid var(--color-border-control);
  border-radius: 8px;
  padding: 0 12px;
}

.security-mfa-primary,
.security-mfa-danger,
.security-mfa-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.security-mfa-danger {
  border: 1px solid rgba(var(--theme-danger-rgb), 0.24);
  color: var(--color-status-danger-text);
  background: rgba(var(--theme-danger-rgb), 0.08);
  border-radius: 8px;
  min-height: 40px;
  padding: 0 12px;
}

.security-mfa-verify-flow {
  display: grid;
  gap: 16px;
}

.security-mfa-qr {
  width: min(240px, 100%);
  aspect-ratio: 1;
  border: 1px solid var(--theme-border);
  border-radius: 8px;
  padding: 10px;
  background: var(--theme-surface);
}

.security-mfa-uri {
  display: block;
  max-width: 100%;
  overflow-wrap: anywhere;
  border: 1px solid var(--theme-border);
  border-radius: 8px;
  padding: 12px;
  background: var(--theme-surface-2);
  color: var(--theme-text);
}

.security-mfa-success,
.security-mfa-error,
.security-mfa-empty,
.security-mfa-loading {
  border-radius: 8px;
  padding: 12px 14px;
}

.security-mfa-success {
  background: rgba(var(--theme-success-rgb), 0.1);
  color: var(--color-status-success-text);
}

.security-mfa-error {
  background: rgba(var(--theme-danger-rgb), 0.08);
  color: var(--color-status-danger-text);
}

.security-mfa-empty,
.security-mfa-loading {
  background: var(--theme-surface-2);
  color: var(--theme-text-muted);
}

.security-mfa-loading {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.security-mfa-page[dir="rtl"] .security-mfa-panel-heading,
.security-mfa-page[dir="rtl"] .security-mfa-factor,
.security-mfa-page[dir="rtl"] .security-mfa-factor-counts,
.security-mfa-page[dir="rtl"] .security-mfa-actions,
.security-mfa-page[dir="rtl"] .security-mfa-enroll-form {
  direction: rtl;
}

@media (max-width: 900px) {
  .security-mfa-grid,
  .security-mfa-status-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .security-mfa-page {
    padding: 22px;
  }

  .security-mfa-factor,
  .security-mfa-actions,
  .security-mfa-enroll-form {
    align-items: stretch;
    flex-direction: column;
  }

  .security-mfa-danger,
  .security-mfa-primary,
  .security-mfa-actions button {
    width: 100%;
  }
}

