   This applies to:
   /page-builder
   /builder-responses
   /builder-data
   ============================================================ */

.admin-dashboard-layout:has(.page-builder) .admin-sidebar {
  flex: 0 0 84px;
  width: 84px;
  min-width: 84px;
  max-width: 84px;
  padding: 22px 12px;
  align-items: center;
  overflow-x: hidden;
}

/* Prevent clipped brand text */
.admin-dashboard-layout:has(.page-builder) .admin-sidebar-brand {
  width: 56px;
  min-width: 56px;
  height: 56px;
  min-height: 56px;
  justify-content: center;
  padding: 5px;
  margin: 0 auto 22px;
  border-radius: 18px;
}

/* Hide ONLY the brand text, not every span */
.admin-dashboard-layout:has(.page-builder) .admin-sidebar-brand-text {
  display: none !important;
}

.admin-dashboard-layout:has(.page-builder) .admin-sidebar-icon {
  width: 46px;
  height: 46px;
  min-width: 46px;
  border-radius: 16px;
}

/* Nav column */
.admin-dashboard-layout:has(.page-builder) .admin-sidebar-nav {
  width: 100%;
  align-items: center;
  gap: 8px;
}

/* Normal nav buttons become icon-only */
.admin-dashboard-layout:has(.page-builder) .admin-sidebar-nav > button {
  width: 56px;
  min-width: 56px;
  height: 52px;
  min-height: 52px;
  padding: 0;
  justify-content: center;
  border-radius: 16px;
  gap: 0;
  margin-inline: auto;
}

/* Hide labels of normal nav buttons only */
.admin-dashboard-layout:has(.page-builder)
  .admin-sidebar-nav
  > button:not(.admin-sidebar-theme-row)
  > span {
  display: none !important;
}

/* Keep SVG icons visible */
.admin-dashboard-layout:has(.page-builder) .admin-sidebar-nav > button svg {
  width: 19px;
  height: 19px;
  min-width: 19px;
  display: block;
}

/* Active compact icon */
.admin-dashboard-layout:has(.page-builder) .admin-sidebar-nav > button.active {
  background: rgba(var(--theme-primary-rgb), 0.1);
  color: var(--color-accent-text);
}

html.theme-light .admin-dashboard-layout:has(.page-builder) .admin-sidebar-nav > button.active,
html[data-theme="light"] .admin-dashboard-layout:has(.page-builder) .admin-sidebar-nav > button.active,
