.theme-light .admin-dashboard-layout-builder .admin-sidebar .admin-sidebar-nav > button.active,
[data-theme="light"] .admin-dashboard-layout-builder .admin-sidebar .admin-sidebar-nav > button.active,
body.theme-light .admin-dashboard-layout-builder .admin-sidebar .admin-sidebar-nav > button.active {
  background: rgba(var(--theme-shadow-rgb), 0.08) !important;
  color: var(--theme-text) !important;
}

html.theme-light .admin-dashboard-layout:has(.page-builder) .admin-sidebar-nav > button.active svg,
