.admin-dashboard-layout:has(.page-builder) .admin-sidebar-logout span {
  display: none !important;
}

.admin-dashboard-layout:has(.page-builder) .admin-sidebar-logout svg {
  width: 19px;
  height: 19px;
  min-width: 19px;
  display: block;
