/* ============================================================
   AUTH / LOGIN / ALREADY SIGNED IN PAGE
   ============================================================ */

.auth-page,
.login-page,
.already-signed-page {
  flex: 1;
  width: 100%;
  min-height: calc(100vh - 96px - 180px);
  background:
    radial-gradient(circle at top left, rgba(var(--theme-primary-rgb), 0.08), transparent 34%),
    radial-gradient(circle at top right, rgba(var(--theme-shadow-rgb), 0.08), transparent 32%),
    var(--theme-bg-soft);
  color: var(--theme-text);

  display: grid;
  place-items: center;

  padding: 0 5%;
}

.auth-container,
.login-container,
.already-signed-container {
  width: min(620px, 100%);
  margin: 0 auto;
}

.auth-card,
.login-card,
.already-signed-card,
.auth-skeleton-card {
  position: relative;
  overflow: hidden;
  width: 100%;
  background: var(--theme-surface);
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.12);
  border-radius: 24px;
  padding: 34px 30px;
  box-shadow: 0 20px 48px rgba(var(--theme-shadow-rgb), 0.08);
  text-align: center;
}

.auth-card::after,
.login-card::after,
.already-signed-card::after,
.auth-skeleton-card::after {
  content: "";
  position: absolute;
  width: 160px;
  height: 160px;
  top: -82px;
  right: -72px;
  border-radius: 999px;
  background: var(--theme-primary);
  opacity: 0.12;
  pointer-events: none;
}

.auth-card h1,
.login-card h1,
.already-signed-card h1 {
  position: relative;
  z-index: 1;
  margin: 0 auto 12px;
  color: var(--theme-text);
  font-size: clamp(30px, 3.2vw, 42px);
  line-height: 1.08;
  font-weight: 950;
  letter-spacing: -0.045em;
  text-align: center;
}

.auth-card p,
.login-card p,
.already-signed-card p {
  position: relative;
  z-index: 1;
  margin: 0 auto 24px;
  color: var(--theme-text-soft);
  max-width: 520px;
  font-size: 15.5px;
  line-height: 1.65;
  text-align: center;
}

.auth-actions,
.login-actions,
.already-signed-actions {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.auth-actions button,
.login-actions button,
.already-signed-actions button,
.auth-actions a,
.login-actions a,
.already-signed-actions a {
  appearance: none;
  -webkit-appearance: none;
  border-radius: 14px;
  min-height: 46px;
  padding: 11px 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  cursor: pointer;
  font: inherit;
  font-weight: 950;
  text-decoration: none;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease,
    color 0.2s ease,
    border-color 0.2s ease;
}

.auth-actions button:first-child,
.login-actions button:first-child,
.already-signed-actions button:first-child,
.auth-actions a:first-child,
.login-actions a:first-child,
.already-signed-actions a:first-child {
  border: 0;
  background: var(--theme-gradient);
  color: var(--theme-text-inverse);
  box-shadow: 0 12px 28px rgba(var(--theme-primary-rgb), 0.2);
}

.auth-actions button:not(:first-child),
.login-actions button:not(:first-child),
.already-signed-actions button:not(:first-child),
.auth-actions a:not(:first-child),
.login-actions a:not(:first-child),
.already-signed-actions a:not(:first-child) {
  border: 1px solid rgba(var(--theme-primary-rgb), 0.28);
  background: rgba(var(--theme-primary-rgb), 0.06);
  color: var(--color-accent-text);
  box-shadow: none;
}

.auth-actions button:hover,
.login-actions button:hover,
.already-signed-actions button:hover,
.auth-actions a:hover,
.login-actions a:hover,
.already-signed-actions a:hover {
  transform: translateY(-1px);
}

.auth-actions button:first-child:hover,
.login-actions button:first-child:hover,
.already-signed-actions button:first-child:hover,
.auth-actions a:first-child:hover,
.login-actions a:first-child:hover,
.already-signed-actions a:first-child:hover {
  box-shadow: 0 16px 32px rgba(var(--theme-primary-rgb), 0.24);
}

.auth-actions button:not(:first-child):hover,
.login-actions button:not(:first-child):hover,
.already-signed-actions button:not(:first-child):hover,
.auth-actions a:not(:first-child):hover,
.login-actions a:not(:first-child):hover,
.already-signed-actions a:not(:first-child):hover {
  background: rgba(var(--theme-primary-rgb), 0.1);
  border-color: rgba(var(--theme-primary-rgb), 0.38);
}

/* ============================================================
   AUTH SKELETON
   ============================================================ */

.auth-skeleton-line,
.auth-skeleton-button {
  position: relative;
  z-index: 1;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    rgba(var(--theme-shadow-rgb), 0.08),
    rgba(var(--theme-primary-rgb), 0.14),
    rgba(var(--theme-shadow-rgb), 0.08)
  );
  background-size: 220% 100%;
  animation: auth-skeleton-loading 1.1s ease-in-out infinite;
}

.auth-skeleton-title {
  width: min(420px, 85%);
  height: 38px;
  margin: 0 auto 18px;
}

.auth-skeleton-text {
  width: min(500px, 92%);
  height: 16px;
  margin: 0 auto 26px;
}

.auth-skeleton-actions {
  display: flex;
  justify-content: center;
  gap: 12px;
  align-items: center;
}

.auth-skeleton-button {
  height: 46px;
}

.auth-skeleton-button.primary {
  width: 190px;
}

.auth-skeleton-button.secondary {
  width: 88px;
}

/* ============================================================
   DARK MODE
   ============================================================ */

:root[data-theme="dark"] .auth-page,
:root[data-theme="dark"] .login-page,
:root[data-theme="dark"] .already-signed-page,
html.theme-dark .auth-page,
html.theme-dark .login-page,
html.theme-dark .already-signed-page,
body.theme-dark .auth-page,
body.theme-dark .login-page,
body.theme-dark .already-signed-page {
  background:
    radial-gradient(circle at top left, rgba(var(--theme-primary-rgb), 0.16), transparent 34%),
    radial-gradient(circle at top right, rgba(var(--theme-secondary-rgb), 0.12), transparent 36%),
    linear-gradient(135deg, var(--theme-bg) 0%, var(--theme-bg-soft) 56%, var(--theme-surface) 100%);
  color: var(--theme-text);
}

:root[data-theme="dark"] .already-signed-card,
:root[data-theme="dark"] .auth-skeleton-card,
html.theme-dark .already-signed-card,
html.theme-dark .auth-skeleton-card,
body.theme-dark .already-signed-card,
body.theme-dark .auth-skeleton-card {
  background:
    linear-gradient(145deg, rgba(var(--theme-text-inverse-rgb), 0.055), rgba(var(--theme-text-inverse-rgb), 0.025)) padding-box,
    linear-gradient(145deg, rgba(var(--theme-text-inverse-rgb), 0.22), rgba(var(--theme-primary-rgb), 0.2)) border-box;
