}

:root[data-theme="dark"] .already-signed-actions button:not(:first-child),
:root[data-theme="dark"] .already-signed-actions a:not(:first-child),
html.theme-dark .already-signed-actions button:not(:first-child),
html.theme-dark .already-signed-actions a:not(:first-child),
body.theme-dark .already-signed-actions button:not(:first-child),
body.theme-dark .already-signed-actions a:not(:first-child) {
  background: rgba(var(--theme-primary-rgb), 0.12);
  border-color: rgba(var(--theme-primary-rgb), 0.38);
  color: var(--theme-text);
}

:root[data-theme="dark"] .already-signed-actions button:not(:first-child):hover,
:root[data-theme="dark"] .already-signed-actions a:not(:first-child):hover,
html.theme-dark .already-signed-actions button:not(:first-child):hover,
html.theme-dark .already-signed-actions a:not(:first-child):hover,
body.theme-dark .already-signed-actions button:not(:first-child):hover,
body.theme-dark .already-signed-actions a:not(:first-child):hover {
  background: rgba(var(--theme-primary-rgb), 0.18);
  border-color: rgba(var(--theme-primary-rgb), 0.5);
}

:root[data-theme="dark"] .auth-skeleton-line,
:root[data-theme="dark"] .auth-skeleton-button,
html.theme-dark .auth-skeleton-line,
html.theme-dark .auth-skeleton-button,
body.theme-dark .auth-skeleton-line,
