    rgba(var(--theme-text-inverse-rgb), 0.1),
    rgba(var(--theme-primary-rgb), 0.16),
    rgba(var(--theme-text-inverse-rgb), 0.1)
  );
  background-size: 220% 100%;
}

@keyframes auth-skeleton-loading {
  0% {
    background-position: 120% 0;
  }

  100% {
    background-position: -120% 0;
  }
}

/* ============================================================
