  border-radius: 28px;
  background: var(--theme-surface);
  padding: 34px;
  box-shadow:
    0 24px 70px rgba(var(--theme-shadow-rgb), 0.11),
    0 1px 0 rgba(var(--theme-text-inverse-rgb), 0.9) inset;
}

.change-password-card::before {
  display: none;
}

.change-password-card::after {
