}

.reservation-calendar-event strong {
  font-size: 0.76rem;
}

.reservation-calendar-event span,
.reservation-calendar-event small {
  margin-top: 2px;
  color: var(--theme-text-muted);
  font-size: 0.66rem;
}

.reservation-calendar-event--confirmed,
.reservation-calendar-month-event--confirmed {
  background: color-mix(in srgb, var(--theme-success) 17%, var(--theme-surface));
  border-color: var(--color-status-success-text);
}

.reservation-calendar-event--completed,
.reservation-calendar-month-event--completed {
  background: color-mix(in srgb, var(--theme-info) 15%, var(--theme-surface));
  border-color: var(--theme-info);
}

.reservation-calendar-event--cancelled,
.reservation-calendar-month-event--cancelled {
  opacity: 0.65;
  background: var(--theme-surface-elevated);
  border-color: var(--theme-text-muted);
}

.reservation-calendar-event--rejected,
.reservation-calendar-month-event--rejected {
  background: color-mix(in srgb, var(--theme-danger) 14%, var(--theme-surface));
  border-color: var(--color-status-danger-text);
}

.reservation-calendar-month {
  min-width: 860px;
}

.reservation-calendar-month-weekdays,
.reservation-calendar-month-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(120px, 1fr));
}

.reservation-calendar-month-weekdays {
