  background: var(--theme-surface-elevated);
  opacity: 0.55;
}

.reservation-calendar-month-grid > section > button {
  width: 29px;
  height: 29px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-inline-start: auto;
  color: var(--theme-text);
  background: transparent;
  border: 0;
  border-radius: 50%;
  font-weight: 800;
  cursor: pointer;
}

.reservation-calendar-month-grid > section.is-today > button {
  color: var(--theme-text-inverse);
  background: var(--theme-primary);
}

.reservation-calendar-month-event {
  width: 100%;
  display: block;
  overflow: hidden;
  margin-top: 4px;
  padding: 5px 6px;
  color: var(--theme-text);
  background: color-mix(in srgb, var(--theme-primary) 14%, var(--theme-surface));
  border: 0;
  border-inline-start: 3px solid var(--theme-primary);
  border-radius: 5px;
