  font-size: 0.61rem;
}

.reservation-calendar-month-grid section small {
  display: block;
  margin-top: 6px;
  color: var(--theme-text-muted);
  font-size: 0.66rem;
  text-align: center;
}

.reservation-calendar-empty {
  position: absolute;
  top: 135px;
  left: 50%;
  z-index: 8;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 260px;
  padding: 22px;
  color: var(--theme-text-muted);
  background: color-mix(in srgb, var(--theme-surface) 94%, transparent);
  border: 1px solid var(--theme-border);
  border-radius: 14px;
  text-align: center;
  transform: translateX(-50%);
