.reservation-calendar-empty strong {
  margin-top: 10px;
  color: var(--theme-text);
}

.reservation-calendar-empty span {
  margin-top: 5px;
  font-size: 0.78rem;
}

.reservation-calendar-detail {
  position: fixed;
  top: 92px;
  inset-inline-end: 24px;
  z-index: 80;
  width: min(360px, calc(100vw - 32px));
  padding: 24px;
  color: var(--theme-text);
  background: var(--theme-surface);
  border: 1px solid var(--theme-border);
  border-radius: 16px;
  box-shadow: 0 22px 60px rgba(var(--theme-shadow-rgb), 0.2);
