  align-items: center;
  justify-content: center;
  color: var(--theme-text-muted);
  background: var(--theme-surface-elevated);
  border: 1px solid var(--theme-border);
  border-radius: 9px;
  cursor: pointer;
}

.reservation-calendar-status {
  display: inline-flex;
  padding: 5px 9px;
  color: var(--color-accent-text);
  background: rgba(var(--theme-primary-rgb), 0.1);
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 800;
  text-transform: capitalize;
}

.reservation-calendar-status--confirmed {
  color: var(--color-status-success-text);
  background: rgba(var(--theme-success-rgb), 0.1);
}

.reservation-calendar-status--rejected,
.reservation-calendar-status--cancelled {
  color: var(--color-status-danger-text);
  background: rgba(var(--theme-danger-rgb), 0.1);
}

.reservation-calendar-detail h2 {
  margin: 18px 40px 20px 0;
  font-size: 1.45rem;
  overflow-wrap: anywhere;
}

.reservation-calendar-detail-list {
  display: grid;
  gap: 14px;
}

.reservation-calendar-detail-list p {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr);
  align-items: start;
  gap: 10px;
  margin: 0;
  color: var(--theme-text-muted);
  font-size: 0.86rem;
  line-height: 1.45;
}

.reservation-calendar-detail-list a {
  color: var(--color-accent-text);
  overflow-wrap: anywhere;
