@media (max-width: 1100px) {
  .reservation-calendar-page {
    padding: 22px;
  }

  .reservation-calendar-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .reservation-calendar-toolbar-actions {
    width: 100%;
    justify-content: flex-start;
    flex-wrap: wrap;
  }

  .reservation-calendar-layout {
    grid-template-columns: 210px minmax(0, 1fr);
  }
}

@media (max-width: 760px) {
  .reservation-calendar-page {
    padding: 16px;
  }

  .reservation-calendar-layout {
    display: block;
  }

  .reservation-calendar-sidebar {
    border-inline-end: 0;
    border-bottom: 1px solid var(--theme-border);
  }

  .reservation-calendar-mini {
    display: none;
  }

  .reservation-calendar-filters {
    margin-top: 18px;
  }

  .reservation-calendar-filters {
    display: flex;
    flex-wrap: wrap;
    gap: 6px 16px;
  }

  .reservation-calendar-section-title {
    width: 100%;
  }

  .reservation-calendar-filters label {
    grid-template-columns: 18px auto auto;
  }

  .reservation-calendar-unscheduled {
    display: none;
  }

  .reservation-calendar-period-label {
    order: -1;
    width: 100%;
    min-width: 0;
    text-align: start;
  }
}

