/* Calendar header and controls need their own containment rules because the
   dashboard shell exposes broad header/div layout styles. */
.calendar-workspace-page {
  min-width: 0;
  overflow-x: clip;
}

.calendar-workspace-page > .reservation-calendar-toolbar {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr) max-content;
  align-items: end;
  gap: 20px;
}

.calendar-toolbar-copy {
  min-width: 0;
  display: grid !important;
  grid-template-columns: minmax(0, 1fr);
  align-content: start;
  justify-items: start;
  gap: 0;
}

.calendar-toolbar-copy > .reservation-calendar-eyebrow,
.calendar-toolbar-copy > h1,
.calendar-toolbar-copy > p {
  width: 100%;
  display: block;
  min-width: 0;
}

.calendar-toolbar-copy > h1 {
  margin: 0;
  overflow-wrap: normal;
  white-space: nowrap;
}

.calendar-toolbar-copy > p {
  max-width: 720px;
  margin: 9px 0 0;
  line-height: 1.45;
}

.calendar-workspace-page > .reservation-calendar-toolbar > .reservation-calendar-toolbar-actions {
  min-width: max-content;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: nowrap;
  gap: 8px;
}

.calendar-workspace-page .calendar-icon-action,
.calendar-workspace-page .calendar-export,
.calendar-workspace-page .calendar-new-event {
  flex: 0 0 auto;
  line-height: 1;
  white-space: nowrap;
}

.calendar-workspace-page .calendar-new-event {
  min-width: 126px;
}

.calendar-control-bar {
  min-width: 0;
}

.calendar-control-bar > strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 1240px) {
  .calendar-workspace-page > .reservation-calendar-toolbar {
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
  }

  .calendar-workspace-page > .reservation-calendar-toolbar > .reservation-calendar-toolbar-actions {
    min-width: 0;
    justify-content: flex-start;
    flex-wrap: wrap;
  }
}

@media (max-width: 900px) {
  .calendar-workspace-page {
    padding: 18px;
  }

  .calendar-control-bar {
    display: grid;
    grid-template-columns: auto auto auto minmax(0, 1fr);
    align-items: center;
  }

  .calendar-control-bar > strong {
    grid-column: 1 / -1;
    grid-row: 1;
    width: 100%;
    margin: 0 0 4px;
  }

  .calendar-control-spacer {
    display: none;
  }

  .calendar-control-bar > .reservation-calendar-view-switch {
    justify-self: end;
  }

  .calendar-workspace-sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: start;
  }

  .calendar-workspace-sidebar > .reservation-calendar-search,
  .calendar-workspace-sidebar > .calendar-privacy-note {
    grid-column: 1 / -1;
  }
}

@media (max-width: 680px) {
  .calendar-workspace-page {
    padding: 12px;
  }

  .calendar-toolbar-copy > h1 {
    font-size: clamp(2rem, 11vw, 2.7rem);
  }

  .calendar-toolbar-copy > p {
    font-size: 0.86rem;
  }

  .calendar-workspace-page > .reservation-calendar-toolbar > .reservation-calendar-toolbar-actions {
    width: 100%;
    display: grid;
    grid-template-columns: 42px repeat(2, minmax(0, 1fr));
  }

  .calendar-workspace-page .calendar-export {
    min-width: 0;
    display: inline-flex;
    padding-inline: 9px;
  }

  .calendar-workspace-page .calendar-new-event {
    grid-column: 1 / -1;
    width: 100%;
    min-width: 0;
  }

  .calendar-control-bar {
    grid-template-columns: repeat(3, auto) minmax(0, 1fr);
    padding: 8px;
  }

  .calendar-control-bar > .reservation-calendar-view-switch {
    grid-column: 1 / -1;
    width: 100%;
    margin-top: 3px;
  }

  .calendar-control-bar > .reservation-calendar-view-switch button {
