/* Authoritative Calendar theme parity layer. Keep this last. */
.calendar-workspace-page .reservation-calendar-layout {
  grid-template-columns: 280px minmax(0, 1fr);
  align-items: start;
  gap: 14px;
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.calendar-workspace-page .calendar-workspace-sidebar {
  gap: 0;
  padding: 14px;
  border: 1px solid var(--theme-border);
  border-radius: 10px;
  background: var(--theme-surface);
  box-shadow: none;
