.calendar-workspace-page .reservation-calendar-toolbar-actions > .calendar-toolbar-action {
  height: 38px;
  min-height: 38px;
  border-radius: 8px;
  font-size: 0.76rem;
}

.calendar-workspace-page .reservation-calendar-toolbar-actions > .calendar-toolbar-action.is-icon-only {
  width: 38px;
}

.calendar-workspace-page .reservation-calendar-toolbar-actions > .calendar-toolbar-action.is-primary {
  min-width: 116px;
  box-shadow: none;
}

@media (max-width: 1100px) and (min-width: 901px) {
  .calendar-workspace-page .reservation-calendar-layout {
    grid-template-columns: 250px minmax(0, 1fr);
  }
