/* Task editor follows the shared Calendar modal and action patterns. */
.calendar-task-section {
  min-width: 0;
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 11px;
  border: 1px solid var(--theme-border);
  border-radius: 10px;
  background: var(--theme-surface-elevated, var(--theme-bg));
}

.calendar-task-section-heading {
  display: flex;
  align-items: center;
  gap: 8px;
}

.calendar-task-section-heading strong {
  color: var(--theme-text);
  font-size: 0.78rem;
}

.calendar-task-section-heading small {
  color: var(--theme-text-muted);
  font-size: 0.68rem;
  font-weight: 650;
}

.calendar-task-section > p {
  margin: -2px 0 0;
  color: var(--theme-text-muted);
  font-size: 0.7rem;
  line-height: 1.4;
