  margin-bottom: 6px;
  padding: 0;
  color: var(--theme-text);
  font-size: 0.74rem;
  font-weight: 750;
}

.calendar-task-date-time-field > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(104px, 0.42fr);
