.calendar-reservations-search { position: relative; }
.calendar-reservations-search svg { position: absolute; inset-inline-start: 13px; top: 50%; transform: translateY(-50%); color: var(--theme-text-muted); pointer-events: none; }
.calendar-reservations-tools :is(input, select, button) { width: 100%; min-width: 0; min-height: 40px; border: 1px solid var(--color-border-control); border-radius: 8px; background: var(--theme-surface-elevated); color: var(--theme-text); font: inherit; }
