.calendar-reservations-state { min-height: 180px; display: flex; align-items: center; justify-content: center; gap: 8px; border: 1px dashed var(--theme-border); border-radius: 10px; color: var(--theme-text-muted); }
.calendar-reservations-state { flex-direction: column; text-align: center; }
.calendar-reservations-state strong { color: var(--theme-text); }

.calendar-reservations-table-wrap { min-width: 0; overflow-x: auto; border: 1px solid var(--theme-border); border-radius: 10px; }
.calendar-reservations-table { width: 100%; min-width: 760px; border-collapse: collapse; table-layout: fixed; background: var(--theme-surface); }
.calendar-reservations-table th { position: sticky; top: 0; z-index: 2; padding: 11px 12px; border-bottom: 1px solid var(--theme-border); background: var(--theme-surface-elevated); color: var(--theme-text-muted); font-size: 0.66rem; font-weight: var(--font-weight-bold); text-align: start; text-transform: uppercase; letter-spacing: 0.05em; }
.calendar-reservations-table th:nth-child(1) { width: 19%; }
