.calendar-reservations-table td { min-width: 0; padding: clamp(8px, calc(12px * var(--ui-layout-scale, 1)), 12px); border-bottom: 1px solid var(--theme-border); vertical-align: top; color: var(--theme-text); font-size: var(--ui-text-small, 0.76rem); overflow-wrap: anywhere; }
