.calendar-reservations-table td > a { color: var(--color-accent-text); text-decoration: none; }

.calendar-reservation-status { width: fit-content; border-radius: 999px; padding: 5px 8px; background: var(--theme-surface-elevated); text-transform: capitalize; font-size: 0.68rem; font-weight: 900; }
.calendar-reservation-status.is-new { background: var(--theme-primary-soft); color: var(--color-accent-text); }
.calendar-reservation-status.is-confirmed,
