.ecommerce-page-header {
  padding: 4px 0 8px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}

.ecommerce-page-kicker,
.ecommerce-list-header > div > span {
  display: block;
  color: var(--color-accent-text);
  font-size: 0.76rem;
  font-weight: 950;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

.ecommerce-page-header h1 {
  margin: 12px 0;
  color: var(--theme-text);
  font-size: clamp(2.1rem, 4vw, 3.45rem);
  font-weight: 950;
  line-height: 0.95;
  letter-spacing: -0.04em;
}

.ecommerce-page-header p,
.ecommerce-empty-state p {
  margin: 0;
  color: var(--theme-text-muted);
  font-size: 1rem;
  font-weight: 650;
  line-height: 1.7;
}

.ecommerce-page-header p {
  max-width: 760px;
}

.ecommerce-summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.ecommerce-summary-card,
.ecommerce-list-card {
  border: 1px solid color-mix(in srgb, var(--theme-border) 84%, transparent);
  border-radius: 18px;
  background: color-mix(in srgb, var(--theme-surface) 78%, var(--theme-bg-soft));
  box-shadow: 0 16px 38px rgba(var(--theme-shadow-rgb), 0.075);
}

.ecommerce-summary-card {
  min-height: 132px;
  padding: 22px;
  display: flex;
  align-items: flex-start;
  gap: 16px;
}

.ecommerce-summary-icon,
.ecommerce-empty-state > span {
  width: 44px;
  height: 44px;
  border: 1px solid rgba(var(--theme-primary-rgb), 0.2);
  border-radius: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent-text);
  background: rgba(var(--theme-primary-rgb), 0.08);
}

.ecommerce-summary-card strong,
.ecommerce-summary-card div > span {
  display: block;
}

.ecommerce-summary-card strong {
  margin: 12px 0 0;
  color: var(--theme-text);
  font-size: 2rem;
  font-weight: 950;
  line-height: 1;
}

.ecommerce-summary-card div > span {
  color: var(--theme-text-muted);
  font-size: 0.8rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}

.ecommerce-summary-toolbar {
  min-height: 42px;
  margin-bottom: 12px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  justify-content: flex-end;
}

.ecommerce-summary-customizer {
  position: relative;
}

.ecommerce-summary-customizer-toggle {
  min-height: 42px;
  padding: 0 14px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--theme-border);
  border-radius: 11px;
  color: var(--theme-text);
  background: var(--theme-surface);
  font: inherit;
  font-size: 0.84rem;
  font-weight: 800;
  cursor: pointer;
}

.ecommerce-summary-customizer-toggle:hover {
  border-color: rgba(var(--theme-primary-rgb), 0.5);
  background: var(--theme-bg-soft);
}

.ecommerce-summary-customizer-menu {
  position: absolute;
  z-index: 30;
  inset-block-start: calc(100% + 8px);
  inset-inline-end: 0;
  width: min(300px, calc(100vw - 32px));
  padding: 16px;
  border: 1px solid var(--theme-border);
  border-radius: 14px;
  color: var(--theme-text);
  background: var(--theme-surface);
  box-shadow: 0 18px 44px rgba(var(--theme-shadow-rgb), 0.16);
}

.ecommerce-summary-customizer-menu > header {
  padding-bottom: 12px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid var(--theme-border);
}

.ecommerce-summary-customizer-menu > header > div {
  display: grid;
  gap: 2px;
}

.ecommerce-summary-customizer-menu > header strong {
  font-size: 0.86rem;
}

.ecommerce-summary-customizer-menu > header span {
  color: var(--theme-text-muted);
  font-size: 0.72rem;
}

.ecommerce-summary-customizer-menu > header button.ecommerce-summary-customizer-reset {
  min-height: auto;
  padding: 4px 7px;
  border: 0 !important;
  border-radius: 0;
  outline: 0;
  color: var(--color-accent-text);
  background: transparent !important;
  box-shadow: none !important;
  font: inherit;
  font-size: 0.72rem;
  font-weight: 800;
  cursor: pointer;
}

.ecommerce-summary-customizer-menu > header button.ecommerce-summary-customizer-reset:hover:not(:disabled) {
  color: var(--theme-primary-hover);
  background: transparent !important;
  transform: none;
}

.ecommerce-summary-customizer-menu > header button.ecommerce-summary-customizer-reset:focus-visible {
  outline: 2px solid var(--theme-primary);
  outline-offset: 2px;
}

.ecommerce-summary-customizer-menu > header button.ecommerce-summary-customizer-reset:disabled {
  opacity: 0.45;
  cursor: default;
  transform: none;
}

.ecommerce-summary-customizer-list {
  max-height: 280px;
  margin-top: 8px;
  display: grid;
  gap: 2px;
  overflow-y: auto;
}

.ecommerce-summary-customizer-list label {
  min-height: 36px;
  padding: 0 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  border-radius: 8px;
  color: var(--theme-text);
  font-size: 0.84rem;
  font-weight: 650;
  cursor: pointer;
}

.ecommerce-summary-customizer-list label:hover,
.ecommerce-summary-customizer-list label:has(input:focus-visible) {
  background: var(--theme-bg-soft);
}

.ecommerce-summary-customizer-list input {
  width: 16px;
  height: 16px;
  min-height: 16px !important;
  flex: 0 0 16px;
  padding: 0;
  margin: 0;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  background: transparent !important;
  appearance: auto;
  accent-color: var(--theme-primary);
}

.ecommerce-summary-empty {
  grid-column: 1 / -1;
  margin: 0;
  padding: 24px;
  border: 1px dashed var(--theme-border);
  border-radius: 14px;
  color: var(--theme-text-muted);
  background: var(--theme-surface);
  text-align: center;
}

.ecommerce-list-card {
  overflow: hidden;
}

.ecommerce-list-header {
  padding: 24px 26px 20px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.ecommerce-list-header h2 {
  margin: 8px 0 0;
  color: var(--theme-text);
  font-size: 1.35rem;
  font-weight: 950;
}

.ecommerce-list-heading {
  min-width: 0;
}

.ecommerce-list-heading .ecommerce-stock-filter-panel {
  width: min(380px, 100%);
  margin-top: 18px;
}

.ecommerce-list-controls {
  width: min(380px, 100%);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 12px;
}

.ecommerce-list-controls .ecommerce-search {
  width: 100%;
}

.ecommerce-list-columns {
  min-height: 44px;
  padding: 0 26px;
  border-top: 1px solid var(--theme-border);
  border-bottom: 1px solid var(--theme-border);
  display: grid;
  grid-template-columns: minmax(0, 1fr) 160px 180px;
  align-items: center;
  gap: 18px;
  color: var(--theme-text-muted);
  background: rgba(var(--theme-primary-rgb), 0.035);
  font-size: 0.75rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.ecommerce-empty-state {
  min-height: 300px;
  padding: 56px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.ecommerce-empty-state > span {
  width: 58px;
  height: 58px;
  border-radius: 18px;
}

.ecommerce-empty-state h3 {
  margin: 18px 0 8px;
  color: var(--theme-text);
  font-size: 1.1rem;
  font-weight: 950;
}

.ecommerce-empty-state p {
  max-width: 480px;
  font-size: 0.9rem;
}

.ecommerce-primary-button,
.ecommerce-secondary-button {
  min-height: 44px;
  border: 1px solid transparent;
  border-radius: 13px;
  padding: 0 17px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 900;
  cursor: pointer;
}

.ecommerce-primary-button {
  color: var(--theme-text-inverse);
  border: 0 !important;
  background: var(--accent);
  box-shadow: 0 10px 22px rgba(var(--theme-primary-rgb), 0.18);
}

.ecommerce-primary-button:hover:not(:disabled) {
  background: var(--theme-primary-hover);
  transform: translateY(-1px);
}

.ecommerce-secondary-button {
  color: var(--theme-text);
  border-color: var(--color-border-control);
  background: var(--theme-surface);
}

.ecommerce-primary-button:disabled {
  opacity: 0.65;
  cursor: wait;
}

.ecommerce-page-actions { display: flex; align-items: center; gap: 10px; }

.ecommerce-page-skeleton > header,
.ecommerce-page-skeleton > section,
.ecommerce-page-skeleton > article > header { display: flex; align-items: center; justify-content: space-between; gap: 18px; }
.ecommerce-page-skeleton > header > div,
.ecommerce-page-skeleton > article > header > div { display: grid; gap: 9px; }
.ecommerce-page-skeleton > header { min-height: 105px; }
.ecommerce-page-skeleton > section { margin: 24px 0; }
.ecommerce-page-skeleton > section > i { width: 100%; height: 108px; border-radius: 16px; }
.ecommerce-page-skeleton > article { padding: 24px; border: 1px solid var(--theme-border); border-radius: 18px; background: var(--theme-surface); }
.ecommerce-page-skeleton > article > header { margin-bottom: 18px; }
.ecommerce-page-skeleton > article > i { display: block; height: 58px; margin-top: 1px; border-radius: 9px; }
.ecommerce-page-skeleton > header > div > i:nth-child(1) { width: 100px; height: 14px; }
.ecommerce-page-skeleton > header > div > i:nth-child(2) { width: 220px; height: 34px; }
.ecommerce-page-skeleton > header > div > i:nth-child(3) { width: min(420px, 70vw); height: 16px; }
.ecommerce-page-skeleton > header > i { width: 130px; height: 42px; border-radius: 12px; }
.ecommerce-page-skeleton > article > header > div > i:first-child { width: 85px; height: 12px; }
.ecommerce-page-skeleton > article > header > div > i:last-child { width: 145px; height: 25px; }
.ecommerce-page-skeleton > article > header > i { width: 270px; height: 42px; border-radius: 12px; }

.ecommerce-page-skeleton i,
.ecommerce-theme-skeleton i,
.ecommerce-store-page-skeleton i,
.ecommerce-operations-skeleton i,
.ecommerce-route-skeleton-header i,
.ecommerce-route-skeleton-filters i {
  background: linear-gradient(100deg, rgba(var(--theme-primary-rgb), 0.08) 20%, rgba(var(--theme-primary-rgb), 0.18) 42%, rgba(var(--theme-primary-rgb), 0.08) 64%);
  background-size: 220% 100%;
  animation: ecommerce-skeleton-wave 1.35s ease-in-out infinite;
}

@keyframes ecommerce-skeleton-wave { to { background-position-x: -220%; } }

.ecommerce-error {
  border: 1px solid color-mix(in srgb, var(--theme-danger) 36%, var(--theme-border));
  border-radius: 13px;
  padding: 12px 15px;
  color: var(--color-status-danger-text);
  background: color-mix(in srgb, var(--theme-danger) 7%, var(--theme-surface));
  font-size: 0.88rem;
  font-weight: 750;
}

.ecommerce-search {
  width: min(320px, 100%);
  min-height: 42px;
  border: 1px solid var(--theme-text);
  border-radius: 13px;
  padding: 0 13px;
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--theme-text-muted);
  background: var(--theme-surface);
}

.ecommerce-search input {
  width: 100%;
  border: 0 !important;
  border-radius: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  color: var(--theme-text);
  background: transparent !important;
  font: inherit;
  appearance: none;
}

.ecommerce-search input:hover,
.ecommerce-search input:focus,
.ecommerce-search input:focus-visible {
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  background: transparent !important;
}

.ecommerce-search:focus-within {
  border-color: var(--theme-text);
  box-shadow: none;
}

.ecommerce-loading {
  min-height: 260px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: var(--theme-text-muted);
  font-weight: 800;
}

.is-spinning {
  animation: ecommerce-spin 0.8s linear infinite;
}

@keyframes ecommerce-spin {
  to { transform: rotate(360deg); }
}

.ecommerce-record-list {
  display: flex;
  flex-direction: column;
}

.ecommerce-record {
  min-height: 78px;
  padding: 14px 20px;
  border-top: 1px solid var(--theme-border);
  display: grid;
  grid-template-columns: 42px minmax(180px, 1fr) minmax(120px, 0.7fr) 88px auto;
  align-items: center;
  gap: 14px;
}

.ecommerce-record:first-child {
  border-top: 0;
}

.ecommerce-record-icon {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--color-accent-text);
  background: rgba(var(--theme-primary-rgb), 0.08);
}

.ecommerce-record-category-image {
  overflow: hidden;
  padding: 0;
}

.ecommerce-record-category-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ecommerce-record-main strong,
.ecommerce-record-main span {
  display: block;
}

.ecommerce-record-main strong {
  color: var(--theme-text);
  font-size: 0.94rem;
  font-weight: 900;
}

.ecommerce-record-main span,
.ecommerce-record-meta {
  margin-top: 4px;
  color: var(--theme-text-muted);
  font-size: 0.78rem;
  font-weight: 700;
}

.ecommerce-status {
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 6px 9px;
  color: var(--theme-text-muted);
  background: var(--theme-bg-soft);
  font-size: 0.68rem;
  font-weight: 950;
  text-align: center;
  text-transform: uppercase;
}

.ecommerce-status.is-active {
  color: var(--color-status-success-text);
  border-color: rgba(var(--theme-success-rgb), 0.36);
  background: rgba(var(--theme-success-rgb), 0.22);
}

.ecommerce-status.is-draft {
  color: var(--color-status-warning-text);
  border-color: rgba(var(--theme-warning-rgb), 0.42);
  background: rgba(var(--theme-warning-rgb), 0.25);
}

.ecommerce-status.is-inactive {
  color: var(--color-status-danger-text);
  border-color: rgba(var(--theme-danger-rgb), 0.38);
  background: rgba(var(--theme-danger-rgb), 0.2);
}

.ecommerce-status.is-archived {
  color: var(--theme-text);
  border-color: rgba(var(--theme-info-rgb), 0.38);
  background: rgba(var(--theme-info-rgb), 0.22);
}

.ecommerce-record-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ecommerce-record-actions :is(a, button),
.ecommerce-modal > header > button {
  width: 36px;
  height: 36px;
  border: 1px solid var(--color-border-control);
  border-radius: 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--theme-text-muted);
  background: var(--theme-surface);
  cursor: pointer;
}

.ecommerce-modal > header > button {
  border: 0 !important;
  color: var(--theme-text-inverse) !important;
  background: var(--madar-red-deep) !important;
  box-shadow: 0 8px 18px rgba(var(--theme-primary-rgb), 0.18) !important;
}

.ecommerce-modal > header > button:hover,
.ecommerce-modal > header > button:focus-visible {
  border-color: transparent !important;
  color: var(--theme-text-inverse) !important;
  background: var(--madar-red-deep) !important;
  box-shadow: 0 8px 18px rgba(var(--theme-primary-rgb), 0.18) !important;
}

.ecommerce-record-actions :is(a, button) {
  width: 32px;
  height: 32px;
  min-height: 32px;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0;
  outline: 0;
  color: var(--accent);
  background: transparent !important;
  box-shadow: none !important;
  font: inherit;
  text-decoration: none;
}

.ecommerce-record-actions :is(a, button):hover,
.ecommerce-modal > header > button:hover {
  color: var(--theme-primary-hover);
  border-color: rgba(var(--theme-primary-rgb), 0.4);
}

.ecommerce-record-actions :is(a, button):hover {
  border-color: transparent !important;
  background: transparent !important;
  transform: translateY(-1px);
}

.ecommerce-record-actions :is(a, button):focus-visible {
  outline: 0;
  color: var(--theme-primary-hover);
  filter: drop-shadow(0 0 3px rgba(var(--theme-primary-rgb), 0.24));
}

.ecommerce-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1200;
  padding: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(var(--theme-shadow-rgb), 0.52);
  backdrop-filter: blur(7px);
}

.ecommerce-modal {
  width: min(980px, 100%);
  max-height: calc(100vh - 56px);
  overflow: auto;
  border: 1px solid var(--theme-border);
  border-radius: 20px;
  color: var(--theme-text);
  background: var(--theme-surface);
  box-shadow: 0 28px 90px rgba(var(--theme-shadow-rgb), 0.28);
}

.ecommerce-modal > header {
  position: sticky;
  top: 0;
  z-index: 2;
  padding: 20px 24px;
  border-bottom: 1px solid var(--theme-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: color-mix(in srgb, var(--theme-surface) 94%, transparent);
  backdrop-filter: blur(12px);
}

.ecommerce-modal > header span {
  color: var(--color-accent-text);
  font-size: 0.7rem;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.ecommerce-modal > header h2 {
  margin: 5px 0 0;
  font-size: 1.35rem;
  font-weight: 950;
}

.ecommerce-modal form {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.ecommerce-form-section {
  min-width: 0;
  margin: 0;
  border: 1px solid var(--theme-border);
  border-radius: 16px;
  padding: 18px;
}

.ecommerce-form-section--media {
  padding: 26px;
}

.ecommerce-form-section--media .ecommerce-field-grid {
  margin-top: 24px;
}

.ecommerce-form-section legend {
  padding: 0 7px;
  color: var(--theme-text);
  font-size: 0.84rem;
  font-weight: 950;
}

.ecommerce-translation-grid,
.ecommerce-field-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 15px;
}

.ecommerce-field-grid--three { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.ecommerce-field-grid--four { grid-template-columns: repeat(4, minmax(0, 1fr)); }

.ecommerce-translation-card {
  border-radius: 13px;
  padding: 15px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--theme-bg-soft);
}

.ecommerce-translation-card > strong {
  color: var(--color-accent-text);
  font-size: 0.78rem;
  font-weight: 950;
}

.ecommerce-modal label,
.ecommerce-tag-picker > span {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: var(--theme-text-muted);
  font-size: 0.76rem;
  font-weight: 850;
}

.ecommerce-field-help {
  color: var(--theme-text-muted);
  font-size: 0.68rem;
  font-weight: 600;
  line-height: 1.4;
}

.ecommerce-hierarchy-section > .ecommerce-field-help {
  display: block;
  margin: 0 0 12px;
}

.ecommerce-hierarchy-section .ecommerce-field-grid {
  align-items: end;
}

.ecommerce-hierarchy-section .ecommerce-field-grid > label,
.ecommerce-hierarchy-section :is(input, select) {
  min-height: 44px;
}

.ecommerce-field-label {
  display: flex;
  align-items: center;
  gap: 7px;
}

.ecommerce-field-optional {
  color: var(--theme-text-muted);
  font-size: 0.64rem;
  font-weight: 700;
}

.ecommerce-modal input,
.ecommerce-modal select,
.ecommerce-modal textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid var(--color-border-control);
  border-radius: 11px;
  padding: 10px 11px;
  color: var(--theme-text);
  background: var(--theme-surface);
  font-family: inherit;
  font-size: var(--font-size-sm, 0.875rem) !important;
  font-weight: var(--font-weight-regular, 400) !important;
  line-height: 1.5;
  outline: none;
}

.ecommerce-modal textarea {
  min-height: 48px;
  max-height: 144px;
  overflow-y: hidden;
  resize: none;
  transition: height 120ms ease, border-color 140ms ease, box-shadow 140ms ease;
}

.ecommerce-modal input:focus,
.ecommerce-modal select:focus,
.ecommerce-modal textarea:focus,
.ecommerce-modal input:focus-visible,
.ecommerce-modal select:focus-visible,
.ecommerce-modal textarea:focus-visible {
  border-color: var(--theme-text) !important;
  outline: 0 !important;
  box-shadow: none !important;
}

.ecommerce-modal input:hover,
.ecommerce-modal select:hover,
.ecommerce-modal textarea:hover {
  border-color: var(--color-border-control) !important;
  box-shadow: none !important;
}

.ecommerce-modal select,
.ecommerce-modal select option {
  font-family: inherit;
  font-size: var(--font-size-sm, 0.875rem) !important;
  font-weight: var(--font-weight-regular, 400) !important;
  line-height: 1.4;
}

.ecommerce-form-section > label + .ecommerce-field-grid,
.ecommerce-form-section > label + label {
  margin-top: 15px;
}

.ecommerce-product-images {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 18px;
  border: 1px solid var(--theme-border);
  border-radius: 14px;
  background: var(--theme-bg-soft);
}

.ecommerce-product-images-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.ecommerce-product-images-header > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ecommerce-product-images-header strong {
  color: var(--theme-text);
  font-size: 0.88rem;
}

.ecommerce-product-images-header > div > span {
  color: var(--theme-text-muted);
  font-size: 0.72rem;
  font-weight: 600;
}

.ecommerce-product-image-count {
  flex: 0 0 auto;
  padding: 5px 9px;
  border: 1px solid var(--theme-border);
  border-radius: 999px;
  color: var(--theme-text-muted);
  background: var(--theme-surface);
  font-size: 0.7rem;
  font-weight: 800;
}

.ecommerce-product-image-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

.ecommerce-product-image-grid.has-images {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.ecommerce-product-image-grid figure {
  position: relative;
  aspect-ratio: 4 / 3;
  margin: 0;
  overflow: hidden;
  border: 1px solid var(--theme-border);
  border-radius: 12px;
  background: var(--theme-surface);
}

.ecommerce-product-image-grid img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ecommerce-product-image-grid figcaption {
  position: absolute;
  left: 8px;
  bottom: 8px;
  padding: 4px 7px;
  border-radius: 7px;
  color: var(--theme-text);
  background: var(--theme-surface);
  box-shadow: var(--shadow-sm);
  font-size: 0.62rem;
  font-weight: 800;
}

.ecommerce-product-image-grid button {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 30px;
  height: 30px;
  padding: 0;
  display: grid;
  place-items: center;
  border: 1px solid var(--color-border-control);
  border-radius: 9px;
  color: var(--color-status-danger-text);
  background: var(--theme-surface);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: transform 140ms ease, border-color 140ms ease;
}

.ecommerce-product-image-grid button:hover {
  border-color: var(--color-status-danger-text);
  transform: translateY(-1px);
}

.ecommerce-product-image-upload {
  min-height: 172px;
  padding: 20px;
  display: flex !important;
  flex-direction: column !important;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1.5px dashed rgba(var(--theme-primary-rgb), 0.42);
  border-radius: 12px;
  color: var(--theme-text) !important;
  background: rgba(var(--theme-primary-rgb), 0.035);
  text-align: center;
  cursor: pointer;
  transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
}

.ecommerce-product-image-grid.has-images .ecommerce-product-image-upload {
  min-height: 0;
  aspect-ratio: 4 / 3;
  padding: 10px;
}

.ecommerce-product-image-upload:hover,
.ecommerce-product-image-upload.is-dragging {
  border-color: rgba(var(--theme-primary-rgb), 0.82);
  background: rgba(var(--theme-primary-rgb), 0.09);
  transform: translateY(-1px);
}

.ecommerce-product-image-upload.is-busy {
  opacity: 0.68;
  cursor: wait;
  transform: none;
}

.ecommerce-product-image-upload-icon {
  width: 44px;
  height: 44px;
  margin-bottom: 4px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(var(--theme-primary-rgb), 0.2);
  border-radius: 12px;
  color: var(--color-accent-text);
  background: rgba(var(--theme-primary-rgb), 0.1);
}

.ecommerce-product-image-upload strong {
  font-size: 0.76rem;
}

.ecommerce-product-image-upload > span:not(.ecommerce-product-image-upload-icon),
.ecommerce-product-image-upload small {
  color: var(--theme-text-muted);
  font-size: 0.64rem;
  font-weight: 600;
}

.ecommerce-product-image-grid.has-images .ecommerce-product-image-upload > span:not(.ecommerce-product-image-upload-icon),
.ecommerce-product-image-grid.has-images .ecommerce-product-image-upload small {
  display: none;
}

.ecommerce-product-image-grid.has-images .ecommerce-product-image-upload-icon {
  width: 36px;
  height: 36px;
  margin: 0;
}

.ecommerce-product-image-upload input {
  display: none;
}

.ecommerce-category-image-section > .ecommerce-field-help {
  margin: 0 0 14px;
}

.ecommerce-category-image-upload {
  min-height: 190px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 6px;
  padding: 22px;
  border: 1px dashed rgba(var(--theme-primary-rgb), 0.5);
  border-radius: 14px;
  background: rgba(var(--theme-primary-rgb), 0.035);
  color: var(--theme-text);
  text-align: center;
  cursor: pointer;
  transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
}

.ecommerce-category-image-upload:hover,
.ecommerce-category-image-upload.is-dragging {
  border-color: var(--theme-primary);
  background: rgba(var(--theme-primary-rgb), 0.09);
  transform: translateY(-1px);
}

.ecommerce-category-image-upload input {
  display: none;
}

.ecommerce-category-image-upload span,
.ecommerce-category-image-upload small {
  color: var(--theme-text-muted);
}

.ecommerce-category-image-preview {
  position: relative;
  min-height: 0;
  height: clamp(150px, 26vh, 230px);
  margin: 0;
  overflow: hidden;
  border-radius: 14px;
  background: var(--theme-bg-soft);
}

.ecommerce-category-image-preview img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ecommerce-category-image-remove {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 40px;
  height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid var(--theme-border);
  border-radius: 10px;
  background: var(--theme-surface);
  color: var(--theme-danger);
  font: inherit;
  cursor: pointer;
  box-shadow: 0 8px 22px rgba(var(--theme-shadow-rgb), 0.16);
  transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
}

.ecommerce-category-image-remove:hover {
  border-color: var(--theme-danger);
  background: rgba(var(--theme-danger-rgb), 0.1);
  transform: translateY(-1px);
}

.ecommerce-category-image-remove:focus-visible {
  outline: 2px solid var(--theme-danger);
  outline-offset: 2px;
}

.ecommerce-category-image-error {
  margin: 10px 0 0;
  color: var(--theme-danger);
  font-size: 0.78rem;
}

.ecommerce-check-row {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.ecommerce-check {
  flex: 1 1 210px;
  min-height: 44px;
  flex-direction: row !important;
  align-items: center;
  justify-content: flex-start;
  align-self: stretch;
  padding: 10px 12px;
  border: 1px solid var(--theme-border);
  border-radius: 11px;
  background: var(--theme-bg-soft);
  cursor: pointer;
}

.ecommerce-check-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.ecommerce-check-copy strong {
  color: var(--theme-text);
  font-size: 0.74rem;
}

.ecommerce-check-copy small {
  color: var(--theme-text-muted);
  font-size: 0.64rem;
  font-weight: 600;
  line-height: 1.35;
}

.ecommerce-check input,
.ecommerce-tag-picker input {
  flex: 0 0 18px;
  width: 18px;
  min-width: 18px;
  height: 18px;
  margin: 0;
  padding: 0;
  accent-color: var(--color-accent-text);
}

.ecommerce-tag-picker {
  margin-top: 17px;
}

.ecommerce-tag-picker > div {
  margin-top: 9px;
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
}

.ecommerce-tag-picker label {
  border: 1px solid var(--theme-border);
  border-radius: 999px;
  padding: 7px 10px;
  flex-direction: row;
  align-items: center;
  background: var(--theme-surface);
}

.ecommerce-modal form > footer {
  position: sticky;
  bottom: -24px;
  margin: 0 -24px -24px;
  padding: 16px 24px;
  border-top: 1px solid var(--theme-border);
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  background: color-mix(in srgb, var(--theme-surface) 94%, transparent);
  backdrop-filter: blur(12px);
}

[dir="rtl"] .ecommerce-page,
[dir="rtl"] .ecommerce-list-card {
  text-align: right;
}

@media (max-width: 820px) {
  .ecommerce-page-header,
  .ecommerce-list-header {
    flex-direction: column;
    align-items: stretch;
  }

  .ecommerce-primary-button,
  .ecommerce-search {
    width: 100%;
  }

  .ecommerce-summary-grid {
    grid-template-columns: 1fr;
  }

  .ecommerce-list-columns {
    grid-template-columns: minmax(0, 1fr) 100px;
  }

  .ecommerce-list-columns span:last-child {
    display: none;
  }

  .ecommerce-record {
    grid-template-columns: 42px minmax(0, 1fr) auto;
  }

  .ecommerce-record-meta,
  .ecommerce-status {
    display: none;
  }

  .ecommerce-product-image-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }


  .ecommerce-translation-grid,
  .ecommerce-field-grid,
  .ecommerce-field-grid--three,
  .ecommerce-field-grid--four {
    grid-template-columns: 1fr;
  }

  .ecommerce-modal-backdrop {
    padding: 0;
  }

  .ecommerce-modal {
    max-height: 100vh;
    border-radius: 0;
  }

  .ecommerce-category-image-preview {
    height: clamp(130px, 22vh, 180px);
  }
}

.ecommerce-store-admin {
  --store-admin-surface: var(--color-surface);
  --store-admin-primary: var(--color-primary);
  --store-admin-browser-bar: var(--color-surface-soft);
  --store-admin-error-bg: color-mix(in srgb, var(--color-danger) 8%, var(--color-surface));
  width: 100%;
  height: 100dvh;
  min-height: 0;
  padding: 32px 24px 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  color: var(--color-text);
}

.ecommerce-store-admin-header {
  width: 100%;
  max-width: none;
  margin: 0 auto 22px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
}

.ecommerce-store-admin-kicker {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--color-accent-text);
  font-size: 0.76rem;
  font-weight: 800;
