/* ============================================================
   Builder Toast
   ============================================================ */

.page-builder .builder-toast {
  position: fixed;
  top: 148px;
  right: 24px;
  z-index: 9999;

  width: min(360px, calc(100vw - 48px));
  min-height: 68px;

  display: flex;
  align-items: flex-start;
  gap: 12px;

  border-radius: 16px;
  padding: 14px 16px;

  background: var(--theme-surface);
  color: var(--madar-text);
  border: 1px solid var(--madar-border);
  border-left: 4px solid var(--madar-red);
  box-shadow: 0 18px 46px rgba(var(--theme-shadow-rgb), 0.18);

  line-height: 1.35;
  pointer-events: none;
  animation: builder-toast-enter 180ms ease-out both;
}

.page-builder .builder-toast-icon {
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: var(--madar-gradient);
  color: var(--theme-text-inverse);
  font-size: 14px;
  font-weight: 950;
  box-shadow: 0 8px 18px rgba(var(--theme-primary-rgb), 0.2);
}

.page-builder .builder-toast-message {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.page-builder .builder-toast-message strong {
  color: var(--madar-text);
  font-size: 13px;
  font-weight: 950;
}

.page-builder .builder-toast-message > span {
  color: var(--madar-muted);
  font-size: 13px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

@keyframes builder-toast-enter {
  from {
    opacity: 0;
    transform: translateX(24px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.page-builder .builder-live-site-link {
  position: fixed;
  top: 212px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9999;

  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-height: 38px;
  padding: 10px 16px;
  border-radius: 999px;

  background: var(--madar-gradient);
  color: var(--theme-text-inverse);
  box-shadow: 0 14px 34px rgba(var(--theme-shadow-rgb), 0.18);
  font-size: 13px;
  font-weight: 950;
  text-decoration: none;
  text-align: center;
}

.page-builder .builder-live-site-link p {
  margin: 0;
  font-size: 12px;
  line-height: 1.2;
}

.page-builder .builder-live-site-link a {
  color: var(--theme-text-inverse);
  text-decoration: none;
}

.page-builder .builder-live-site-link a:hover {
  text-decoration: underline;
}

.page-builder .builder-toast::before {
  content: "✓";
  width: 26px;
  height: 26px;
  flex: 0 0 26px;

  display: grid;
  place-items: center;

  border-radius: 999px;
  background: var(--madar-gradient);
  color: var(--theme-text-inverse);
  font-size: 14px;
  font-weight: 950;
  box-shadow: 0 8px 18px rgba(var(--theme-primary-rgb), 0.2);
}

.page-builder .builder-toast::before {
  display: none;
}

.page-builder .user-row:not(.users-table-row) {
  grid-template-columns: minmax(0, 1fr) 220px 160px auto;
}

.page-builder .user-row-main {
  min-width: 0;
}

.page-builder .user-row-main strong,
.page-builder .user-row-main span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.page-builder .user-delete-button {
