.preview-mode .site-column > .builder-element:not(.builder-element-button),
.tenant-runtime-page .site-column > .builder-element:not(.builder-element-button) {
  width: 100%;
}

.preview-mode .site-column > .builder-element-button,
.tenant-runtime-page .site-column > .builder-element-button {
  width: auto;
  max-width: 100%;
}

.builder-element-heading,
.builder-element-text {
