  user-select: text;
  counter-reset: builder-numbered-line;
}

.builder-element > [data-builder-text-block] {
  margin: 0;
  min-height: 1em;
  color: inherit;
  line-height: inherit;
}

.builder-element > h1[data-builder-text-block] {
  font-size: var(--builder-authored-font-size, calc(46px * var(--builder-text-fit-scale, 1)));
  line-height: 1.08;
  color: var(--theme-text);
}

.builder-element > h2[data-builder-text-block] {
  font-size: var(--builder-authored-font-size, calc(36px * var(--builder-text-fit-scale, 1)));
  line-height: 1.15;
  color: var(--theme-text);
}

.builder-element > h3[data-builder-text-block] {
  font-size: var(--builder-authored-font-size, calc(28px * var(--builder-text-fit-scale, 1)));
  line-height: 1.2;
  color: var(--theme-text);
}

.builder-element > p[data-builder-text-block] {
  font-size: var(--builder-authored-font-size, calc(17px * var(--builder-text-fit-scale, 1)));
  line-height: 1.5;
}

.builder-element > p[data-builder-text-block="bullets"],
.builder-element > p[data-builder-text-block="numbers"] {
  position: relative;
  padding-inline-start: 1.5em;
}

.builder-element > p[data-builder-text-block="bullets"]::before,
.builder-element > p[data-builder-text-block="numbers"]::before {
  position: absolute;
  inset-inline-start: 0.2em;
  min-width: 1em;
  text-align: end;
}

.builder-element > p[data-builder-text-block="bullets"]::before {
  content: "•";
}

.builder-element > p[data-builder-text-block="numbers"] {
  counter-increment: builder-numbered-line;
}

.builder-element > p[data-builder-text-block="numbers"]::before {
  content: counter(builder-numbered-line) ".";
}

.builder-element > p[data-builder-text-block]:has(> br:only-child) {
  min-height: calc(17px * var(--builder-text-fit-scale, 1));
  line-height: 1;
}

.builder-element-button {
  appearance: none;
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 18px;
  border: 0 !important;
  border-radius: 8px;
  background: var(--madar-red) !important;
  background-color: var(--madar-red) !important;
  background-image: none !important;
  color: var(--theme-text-inverse) !important;
  -webkit-text-fill-color: var(--theme-text-inverse) !important;
  opacity: 1 !important;
  box-shadow: none;
  font-weight: 850;
  line-height: 1.2;
  cursor: pointer;
  transition:
    background-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.builder-element-button:hover {
  background: var(--madar-red-dark) !important;
  box-shadow: none;
  transform: translateY(-1px);
}

.builder-element-button:active {
  box-shadow: none;
  transform: translateY(0);
}

.builder-element-button:focus-visible {
  outline: 0;
  box-shadow:
    0 0 0 3px rgba(var(--theme-primary-rgb), 0.28),
    0 10px 22px rgba(var(--theme-primary-rgb), 0.22);
}

.builder-element-image {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
  object-position: center;
  border-radius: 0 !important;
}

.builder-element-imageButton {
  width: 100%;
  min-height: 48px;
  display: block;
  overflow: hidden;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.builder-element-imageButton > img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
  transform: scale(var(--image-scale, 1));
  transform-origin: center;
}

.builder-element-imageButton > span {
  width: 100%;
  height: 100%;
  min-height: 48px;
  display: grid;
  place-items: center;
  border: 1px dashed var(--color-border-control);
  color: var(--theme-text-muted);
  background: var(--theme-surface-muted);
  font: inherit;
}

.builder-element-imageButton.is-editorial-card {
  container-type: inline-size;
  display: grid;
  grid-template-columns: var(--image-card-media-width, 200px) minmax(0, 1fr);
  height: 100%;
  min-height: 0;
  max-height: 100%;
  overflow: hidden;
  border: 1px solid var(--color-border-control);
  background: var(--theme-surface);
  color: var(--theme-text);
  text-align: left;
  box-shadow: 0 12px 34px rgba(var(--theme-shadow-rgb), 0.1);
}

.builder-element-imageButton.is-editorial-card > span {
  width: auto;
  height: auto;
  min-height: 0;
  display: flex;
  border: 0;
  background: transparent;
  color: inherit;
}

.image-button-card-media {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  max-height: 100%;
  overflow: hidden;
}

.image-button-card-media > img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
  transform: scale(var(--image-scale, 1));
  transform-origin: center;
  transition: transform 220ms ease;
}

.image-button-card-placeholder {
  width: 100%;
  display: grid;
  place-items: center;
  border-inline-end: 1px dashed var(--color-border-control);
  background: var(--theme-surface-muted);
  color: var(--theme-text-muted);
  font-size: 13px;
}

.image-button-card-copy {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: clamp(6px, 1.8cqw, 9px);
  padding: clamp(12px, 3.5cqw, 18px);
}

.image-button-card-icon {
  width: clamp(32px, 8.5cqw, 38px);
  height: clamp(32px, 8.5cqw, 38px);
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  align-self: center;
  border-radius: 999px;
  background: var(--theme-icon-background, var(--theme-primary));
  color: var(--theme-icon-foreground, var(--theme-on-primary, var(--theme-text-inverse)));
  font-size: 18px;
}

.image-button-card-icon svg {
  color: inherit;
  stroke: currentColor;
}

.image-button-card-title {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  flex: 0 0 auto;
  width: 100%;
  max-width: 100%;
  padding-block: 1px;
  font-family: var(--theme-heading-font);
  font-size: clamp(18px, 5.3cqw, 24px);
  font-weight: 600;
  line-height: 1.08;
  text-align: center;
  text-wrap: balance;
}

.image-button-card-description {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
  flex: 0 1 auto;
  max-width: 100%;
  color: var(--theme-text-muted);
  font-size: clamp(11px, 2.85cqw, 13px);
  line-height: 1.4;
}

.image-button-card-action {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  align-self: center;
  gap: 9px;
  margin-top: 2px;
  color: var(--theme-primary);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.builder-element-imageButton.is-editorial-card:hover .image-button-card-media > img {
  transform: scale(calc(var(--image-scale, 1) * 1.035));
}

.builder-canvas.viewport-mobile .builder-element-imageButton.is-editorial-card {
  grid-template-columns: min(46%, var(--image-card-media-width, 200px)) minmax(0, 1fr);
}

.builder-canvas.viewport-mobile .image-button-card-copy {
  gap: 6px;
  padding: 12px;
}

.builder-canvas.viewport-mobile .image-button-card-icon {
  width: 34px;
  height: 34px;
  font-size: 15px;
}

.builder-canvas.viewport-mobile .image-button-card-title {
  font-size: 18px;
}

.builder-canvas.viewport-mobile .image-button-card-description {
  font-size: 11px;
  line-height: 1.4;
}

.builder-element-video {
  width: 100%;
  height: auto;
  min-height: 180px;
  position: relative;
  display: grid;
  overflow: hidden;
  background: var(--theme-text);
  border-radius: 0 !important;
  contain: paint;
}

.modern-video-media {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  display: block;
  object-fit: cover;
  object-position: center;
  background: var(--theme-text);
}

.modern-video-ui {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  align-items: flex-end;
  pointer-events: none;
  background: linear-gradient(180deg, transparent 52%, rgba(0, 0, 0, 0.7) 100%);
}

.modern-video-center-play {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  padding: 0 0 0 3px;
  border: 1px solid rgba(255, 255, 255, 0.42);
  border-radius: 50%;
  background: rgba(14, 14, 16, 0.72);
  color: #fff;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.32);
  backdrop-filter: blur(12px);
  transform: translate(-50%, -50%);
  cursor: pointer;
  pointer-events: auto;
}

.modern-video-center-play:hover {
  background: var(--madar-red);
  border-color: transparent;
  transform: translate(-50%, -50%) scale(1.06);
}

.modern-video-controls {
  width: 100%;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 18px 16px 13px;
  color: #fff;
  pointer-events: auto;
}

.modern-video-controls button {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  cursor: pointer;
}

.modern-video-controls button:hover,
.modern-video-controls button:focus-visible {
  background: rgba(255, 255, 255, 0.24);
  outline: none;
}

.modern-video-time {
  flex: 0 0 auto;
  color: rgba(255, 255, 255, 0.9);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  font-weight: 750;
}

.modern-video-progress {
  width: 100%;
  min-width: 50px;
  height: 4px;
  padding: 0;
  appearance: none;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(to right, var(--madar-red) var(--video-progress), rgba(255, 255, 255, 0.34) var(--video-progress));
  cursor: pointer;
}

.modern-video-progress::-webkit-slider-thumb {
  width: 13px;
  height: 13px;
  appearance: none;
  border: 2px solid #fff;
  border-radius: 50%;
  background: var(--madar-red);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.32);
}

.modern-video-progress::-moz-range-thumb {
  width: 10px;
  height: 10px;
  border: 2px solid #fff;
  border-radius: 50%;
  background: var(--madar-red);
}

.builder-element-card,
.builder-element-metric,
.builder-element-loginBlock,
