/* ============================================================
   Madar App Builder v4 — Forms / Data / Runtime
   ============================================================ */

.runtime-form {
  display: grid;
  gap: 16px;
  scroll-margin-top: 72px;
  border-radius: var(--form-theme-radius);
  color: var(--form-theme-text);
}

.runtime-form-header h3 {
  margin: 0 0 5px;
  color: var(--form-theme-text);
  font-size: 24px;
}

.runtime-form-header p,
.runtime-form-section-header p {
  margin: 0;
  color: var(--form-theme-muted);
}

.runtime-form-section {
  display: grid;
  gap: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--form-theme-border);
}

.runtime-form-section:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.runtime-form-section-header h4 {
  margin: 0 0 4px;
  color: var(--form-theme-text);
  font-size: 15px;
  font-weight: 950;
}

.runtime-form-page-count {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  border: 0;
  border-radius: 0;
  padding: 4px 6px;
  background: transparent;
  color: var(--form-theme-muted);
  font-size: 12px;
  font-weight: 900;
}

.runtime-form-pagination {
  display: grid;
  grid-template-columns: minmax(112px, 140px) minmax(96px, 1fr) minmax(240px, 300px);
  align-items: center;
  gap: 10px;
  padding-top: 12px;
  border-top: 1px solid var(--form-theme-border);
}

.runtime-form-pagination button {
  width: 100%;
  min-width: 0;
  min-height: 44px;
  border: 1px solid var(--form-theme-border);
  border-radius: var(--form-theme-field-radius);
  padding: 10px 14px;
  background: var(--form-theme-input);
  color: var(--form-theme-text);
  font-weight: 900;
  cursor: pointer;
}

.runtime-form-pagination button:hover:not(:disabled) {
  border-color: var(--form-theme-accent);
  background: color-mix(in srgb, var(--form-theme-accent) 8%, var(--form-theme-input));
  color: var(--form-theme-text);
}

.runtime-form-pagination button.runtime-submit {
  border-color: transparent;
  background: var(--form-theme-accent);
  color: var(--form-theme-button-text);
}

.runtime-form-pagination button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.runtime-form-pagination > :first-child {
  justify-self: stretch;
}

.runtime-form-pagination > .runtime-form-page-count {
  justify-self: center;
}

.runtime-form-pagination > :last-child {
  justify-self: stretch;
}

.runtime-form-actions {
  display: flex;
  flex-wrap: wrap;
  width: 100%;
  gap: 8px;
}

.runtime-form-actions > button {
  flex: 1 1 112px;
  width: auto;
}

.runtime-form-pagination button.runtime-resume-later {
  background: transparent;
  color: var(--form-theme-accent);
}

.runtime-form-toast {
  position: fixed;
  top: 24px;
  right: 24px;
  z-index: 10000;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) 28px;
  align-items: center;
  gap: 10px;
  width: min(390px, calc(100vw - 32px));
  padding: 13px 14px;
  border: 1px solid color-mix(in srgb, var(--form-theme-accent) 32%, transparent);
  border-left: 4px solid var(--form-theme-accent);
  border-radius: 12px;
  background: var(--form-theme-surface);
  color: var(--form-theme-text);
  box-shadow: 0 14px 38px rgba(var(--theme-shadow-rgb), 0.2);
  animation: runtime-form-toast-enter 180ms ease-out both;
}

.runtime-form-toast-icon {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--form-theme-accent) 14%, transparent);
  color: var(--form-theme-accent);
  font-weight: 950;
}

.runtime-form-toast-copy {
  display: grid;
  min-width: 0;
  gap: 2px;
}

.runtime-form-toast-copy strong,
.runtime-form-toast-copy span {
  overflow-wrap: anywhere;
}

.runtime-form-toast-copy strong { font-size: 13px; }
.runtime-form-toast-copy span {
  color: var(--form-theme-muted);
  font-size: 12px;
  font-weight: 700;
}

.runtime-form-toast > button {
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--form-theme-muted);
  cursor: pointer;
  font-size: 20px;
}

@keyframes runtime-form-toast-enter {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

.runtime-question label,
.runtime-question-field {
  display: grid;
  gap: 7px;
