.runtime-question input:not([type="checkbox"]):not([type="radio"]):not([type="file"]),
.runtime-question textarea,
.runtime-question select {
  width: 100%;
  min-height: 54px;
  border: 1px solid var(--form-theme-border);
  border-radius: var(--form-theme-field-radius);
  padding: 14px 16px;
  background: var(--form-theme-input);
  color: var(--form-theme-text);
  box-shadow: 0 1px 0 rgba(var(--theme-shadow-rgb), 0.03), inset 0 0 0 1px transparent;
  font-size: 15px;
  font-weight: 750;
  line-height: 1.35;
  transition: border-color 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
}

.runtime-question textarea {
  min-height: 118px;
  resize: vertical;
}

.runtime-question input::placeholder,
.runtime-question textarea::placeholder {
  color: var(--form-theme-muted);
  opacity: 0.72;
  font-weight: 650;
}

.runtime-question select {
  appearance: none;
  background-image:
    linear-gradient(45deg, transparent 50%, var(--form-theme-muted) 50%),
    linear-gradient(135deg, var(--form-theme-muted) 50%, transparent 50%);
  background-position:
    calc(100% - 20px) 50%,
    calc(100% - 14px) 50%;
  background-size: 6px 6px, 6px 6px;
  background-repeat: no-repeat;
  padding-right: 40px;
}

.runtime-question input[type="file"] {
  width: 100%;
  min-height: 58px;
  border: 1px dashed var(--form-theme-border);
  border-radius: var(--form-theme-field-radius);
  padding: 10px;
  background: var(--form-theme-input);
  color: var(--form-theme-muted);
  font-size: 14px;
  font-weight: 850;
  cursor: pointer;
  transition: border-color 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
}

.runtime-question input[type="file"]::file-selector-button {
  min-height: 38px;
  margin-inline-end: 12px;
  border: 0;
  border-radius: var(--form-theme-field-radius);
  padding: 0 14px;
  background: var(--form-theme-accent);
  color: var(--form-theme-button-text);
  font-weight: 950;
  cursor: pointer;
}

.runtime-question input[type="file"]:hover {
  border-color: var(--form-theme-accent);
  background: color-mix(in srgb, var(--form-theme-accent) 8%, var(--form-theme-input));
}

.runtime-question input:not([type="checkbox"]):not([type="radio"]):not([type="file"]):focus,
.runtime-question textarea:focus,
.runtime-question select:focus,
.runtime-question input[type="file"]:focus {
  border-color: var(--form-theme-accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--form-theme-accent) 14%, transparent);
  outline: none;
}

.runtime-question input:read-only,
.runtime-question textarea:read-only {
  background: var(--form-theme-surface);
}

.runtime-choice-list {
  display: grid;
  gap: 10px;
  justify-items: stretch;
  width: 100%;
}

.runtime-choice-inline {
  display: flex;
  flex-wrap: wrap;
}

.runtime-choice {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  align-items: start;
  justify-content: stretch;
  gap: 12px;
  width: 100%;
  max-width: 100%;
  min-height: 42px;
  padding: 10px 12px;
  border: 1px solid var(--form-theme-border);
  border-radius: var(--form-theme-field-radius);
  background: var(--form-theme-input);
  color: var(--form-theme-text);
  font-size: 14px;
  font-weight: 800;
  text-align: start;
  cursor: pointer;
}

.runtime-choice input {
  flex: 0 0 auto;
  width: 16px;
  height: 16px;
  margin: 2px 0 0;
  accent-color: var(--form-theme-accent);
}

.runtime-choice span {
  min-width: 0;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.runtime-form[dir="rtl"] {
  direction: rtl;
  text-align: right;
}

.runtime-form[dir="ltr"] {
  direction: ltr;
  text-align: left;
}

.runtime-form[dir="rtl"] .runtime-choice {
  grid-template-columns: 18px minmax(0, 1fr);
}

.runtime-form[dir="rtl"] select {
  background-position:
    20px 50%,
    14px 50%;
  padding-right: 16px;
  padding-left: 40px;
}

.runtime-choice:has(input:disabled) {
  opacity: 0.65;
  cursor: not-allowed;
}

.runtime-form-message,
.runtime-form-note {
  margin: 0;
  border-radius: 12px;
  padding: 10px 12px;
  font-size: 14px;
  font-weight: 850;
  line-height: 1.45;
}

.runtime-form-success {
  border: 1px solid rgba(var(--theme-success-rgb), 0.22);
  background: rgba(var(--theme-success-rgb), 0.08);
  color: var(--color-status-success-text);
}

.runtime-form-error {
  border: 1px solid rgba(var(--theme-danger-rgb), 0.22);
  background: rgba(var(--theme-danger-rgb), 0.08);
  color: var(--color-status-danger-text);
}

.runtime-form-note {
  border: 1px solid rgba(83, 98, 122, 0.18);
  background: rgba(83, 98, 122, 0.08);
  color: var(--madar-muted);
}

.runtime-language-switch,
.form-language-switch {
  display: inline-flex;
  width: fit-content;
  gap: 2px;
  padding: 2px;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.14);
  border-radius: 8px;
  background: var(--theme-surface);
}

.runtime-language-switch button,
.form-language-switch button {
  min-height: 30px;
  border: 0;
  border-radius: 6px;
  padding: 5px 10px;
  background: transparent;
  color: rgba(var(--theme-shadow-rgb), 0.72);
  font-size: 12px;
  font-weight: 850;
  cursor: pointer;
}

.runtime-language-switch button.active,
.form-language-switch button.active {
  background: rgba(var(--theme-shadow-rgb), 0.08);
  color: var(--madar-text);
  box-shadow: inset 0 0 0 1px rgba(var(--theme-shadow-rgb), 0.08);
}

.form-translation-panel,
.translation-settings-card {
  display: grid;
  gap: 8px;
}

.form-translation-panel > span,
.translation-settings-card small {
  color: var(--madar-muted);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.35;
}

.translation-entry-field {
  display: grid;
  gap: 5px;
  margin-top: 8px;
}

.translation-entry-field span {
  color: rgba(83, 98, 122, 0.86);
  font-size: 11px;
  font-weight: 850;
}

.translation-entry-field textarea {
  width: 100%;
  min-height: 42px;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.12);
  border-radius: 8px;
  padding: 9px 10px;
  background: var(--theme-surface);
  color: var(--madar-text);
  font-size: 13px;
  font-weight: 750;
  line-height: 1.35;
  resize: vertical;
}

.translation-entry-field textarea:focus {
  border-color: rgba(var(--theme-primary-rgb), 0.32);
  box-shadow: 0 0 0 3px rgba(var(--theme-primary-rgb), 0.07);
  outline: none;
}

.question-translation-title {
  margin: -4px 0 4px 44px;
}

.option-editor-stack {
  display: grid;
  gap: 6px;
}

.option-translation-field {
  margin: 0 0 2px 34px;
}

.forms-loading-shell {
  min-height: 100vh;
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  background: var(--theme-bg);
  color: var(--madar-text);
}

.forms-loading-app-rail {
  position: sticky;
  top: 0;
  height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr auto;
  justify-items: center;
  gap: 24px;
  padding: 34px 12px 28px;
  border-right: 1px solid rgba(var(--theme-shadow-rgb), 0.08);
  background: var(--theme-surface);
}

.forms-loading-shell[dir="rtl"] .forms-loading-app-rail {
  border-right: 0;
  border-left: 1px solid rgba(var(--theme-shadow-rgb), 0.08);
}

.forms-loading-rail-stack {
  display: grid;
  align-content: start;
  gap: 24px;
  padding-top: 28px;
}

.forms-loading-page {
  min-width: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
}

.forms-loading-header {
  display: grid;
  gap: 10px;
  min-height: 130px;
  align-content: center;
  padding: 28px clamp(22px, 4vw, 52px) 22px;
  border-bottom: 1px solid rgba(var(--theme-shadow-rgb), 0.08);
  background: var(--theme-surface);
}

.forms-loading-workspace {
  width: min(100%, 1540px);
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(180px, 220px) minmax(0, 1fr);
  gap: 16px;
  align-items: start;
  padding: 28px clamp(18px, 3vw, 42px);
}

.forms-loading-controls,
.forms-loading-document {
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.1);
  border-radius: 8px;
  background: var(--theme-surface);
  box-shadow: 0 12px 28px rgba(var(--theme-shadow-rgb), 0.06);
}

.forms-loading-controls {
  position: sticky;
  top: 24px;
  display: grid;
  gap: 14px;
  padding: 12px;
}

.forms-loading-control-group {
  display: grid;
  gap: 7px;
}

.forms-loading-actions {
  display: grid;
  gap: 8px;
  padding-top: 12px;
  border-top: 1px solid rgba(var(--theme-shadow-rgb), 0.08);
}

.forms-loading-document {
  display: grid;
  gap: 14px;
  min-height: 640px;
  padding: 14px;
  border-top: 8px solid var(--madar-red);
}

.forms-loading-document-top {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 110px;
  gap: 12px;
  align-items: center;
  padding: 4px 0 12px;
  border-bottom: 1px solid rgba(var(--theme-shadow-rgb), 0.08);
}

.forms-loading-toolbar {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 8px 0;
}

.forms-loading-question {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) minmax(130px, 180px);
  gap: 12px;
  align-items: start;
  padding: 14px;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.1);
  border-left: 4px solid rgba(var(--theme-primary-rgb), 0.55);
  border-radius: 8px;
  background: var(--theme-surface);
}

.forms-loading-shell[dir="rtl"] .forms-loading-question {
  border-left-width: 1px;
  border-right: 4px solid rgba(var(--theme-primary-rgb), 0.55);
}

.forms-loading-question-body {
  display: grid;
  gap: 10px;
}

.forms-loading-shimmer {
  overflow: hidden;
  position: relative;
  background: linear-gradient(90deg, var(--theme-surface-3) 0%, var(--theme-surface-2) 45%, var(--theme-surface-3) 100%);
  background-size: 220% 100%;
  animation: formsLoadingShimmer 1.2s ease-in-out infinite;
}

.forms-loading-line,
.forms-loading-control,
.forms-loading-button,
.forms-loading-pill,
.forms-loading-textarea,
.forms-loading-tool,
.forms-loading-dot,
.forms-loading-type,
.forms-loading-avatar,
.forms-loading-rail-icon {
  display: block;
  border-radius: 8px;
}

.forms-loading-avatar {
  width: 46px;
  height: 46px;
  border-radius: 14px;
}

.forms-loading-avatar.small {
  width: 42px;
  height: 42px;
}

.forms-loading-rail-icon {
  width: 22px;
  height: 22px;
  border-radius: 7px;
}

.forms-loading-line.title {
  width: 230px;
  height: 22px;
}

.forms-loading-line.subtitle {
  width: min(420px, 70%);
  height: 13px;
}

.forms-loading-line.label {
  width: 74px;
  height: 10px;
}

.forms-loading-control {
  height: 40px;
}

.forms-loading-button {
  height: 38px;
}

.forms-loading-line.page-title {
  width: min(360px, 62%);
  height: 28px;
}

.forms-loading-pill {
  height: 30px;
  border-radius: 999px;
}

.forms-loading-textarea {
  width: 100%;
  height: 72px;
}

.forms-loading-tool {
  width: 32px;
  height: 30px;
  border-radius: 7px;
}

.forms-loading-dot {
  width: 28px;
  height: 28px;
  border-radius: 999px;
}

.forms-loading-line.question-title {
  width: min(460px, 74%);
  height: 24px;
}

.forms-loading-control.answer {
  width: 100%;
  height: 44px;
}

.forms-loading-line.hint {
  width: min(320px, 58%);
  height: 10px;
}

.forms-loading-type {
  width: 100%;
  height: 42px;
}

@keyframes formsLoadingShimmer {
  from {
    background-position: 120% 0;
  }

  to {
    background-position: -120% 0;
  }
}

@media (max-width: 920px) {
  .forms-loading-shell {
    grid-template-columns: 56px minmax(0, 1fr);
  }

  .forms-loading-workspace,
  .forms-loading-question {
    grid-template-columns: 1fr;
  }

  .forms-loading-controls {
    position: static;
  }

  .forms-loading-type {
    width: min(220px, 100%);
  }
}

[data-theme="dark"] .forms-loading-shell,
body.theme-dark .forms-loading-shell,
.theme-dark .forms-loading-shell {
  background: var(--madar-bg);
  color: var(--madar-text);
}

[data-theme="dark"] .forms-loading-app-rail,
[data-theme="dark"] .forms-loading-header,
[data-theme="dark"] .forms-loading-controls,
[data-theme="dark"] .forms-loading-document,
[data-theme="dark"] .forms-loading-question,
body.theme-dark .forms-loading-app-rail,
body.theme-dark .forms-loading-header,
body.theme-dark .forms-loading-controls,
body.theme-dark .forms-loading-document,
body.theme-dark .forms-loading-question,
.theme-dark .forms-loading-app-rail,
.theme-dark .forms-loading-header,
.theme-dark .forms-loading-controls,
.theme-dark .forms-loading-document,
.theme-dark .forms-loading-question {
  border-color: var(--madar-border);
  background: var(--madar-surface);
  box-shadow: none;
}

[data-theme="dark"] .forms-loading-shimmer,
body.theme-dark .forms-loading-shimmer,
.theme-dark .forms-loading-shimmer {
  background: linear-gradient(
    90deg,
    rgba(var(--theme-text-inverse-rgb), 0.06) 0%,
    rgba(var(--theme-text-inverse-rgb), 0.14) 45%,
    rgba(var(--theme-text-inverse-rgb), 0.06) 100%
  );
  background-size: 220% 100%;
}

/* ============================================================
   PAGE BUILDER ROUTE SKELETONS
   Dedicated loading states for builder workspaces.
   ============================================================ */

.builder-skeleton-workspace {
  min-height: 100%;
  padding: 0 28px 34px;
  background: var(--madar-bg);
  color: var(--madar-text);
}

.builder-skeleton-header {
  min-height: 92px;
  display: flex;
  align-items: center;
  padding: 0 8px;
  border-bottom: 1px solid var(--madar-border);
}

.builder-skeleton-header > div {
  display: grid;
  gap: 10px;
}

.builder-skeleton-title,
.builder-skeleton-subtitle,
.builder-skeleton-tabs span,
.builder-skeleton-line,
.builder-skeleton-wide-line,
.builder-skeleton-pill,
.builder-skeleton-side-panel,
.builder-skeleton-inspector,
.builder-skeleton-canvas,
.builder-skeleton-document,
.builder-skeleton-question,
.builder-skeleton-calendar,
.builder-skeleton-calendar span,
.builder-skeleton-site-preview,
.builder-skeleton-site-header,
.builder-skeleton-site-body,
.builder-skeleton-site-footer,
.builder-skeleton-stats span,
.builder-skeleton-user-row,
.builder-skeleton-user-row span,
.builder-skeleton-swatches,
.builder-skeleton-swatches span,
.builder-skeleton-theme-preview,
.builder-skeleton-theme-preview span,
.builder-skeleton-status-grid span,
.builder-skeleton-share-grid span,
.builder-skeleton-table,
.builder-skeleton-table span,
.builder-skeleton-hero,
.builder-skeleton-section-grid span {
  background: linear-gradient(
    90deg,
    rgba(var(--theme-shadow-rgb), 0.06),
    rgba(var(--theme-primary-rgb), 0.12),
    rgba(var(--theme-shadow-rgb), 0.06)
  );
  background-size: 220% 100%;
  animation: skeleton-loading 1.1s ease-in-out infinite;
}

.builder-skeleton-title {
  width: min(280px, 54vw);
  height: 24px;
  border-radius: 999px;
}

.builder-skeleton-subtitle {
  width: min(520px, 72vw);
  height: 13px;
  border-radius: 999px;
}

.builder-skeleton-tabs {
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(18px, 3vw, 34px);
  border-bottom: 1px solid var(--madar-border);
}

.builder-skeleton-tabs span {
  width: 88px;
  height: 18px;
  border-radius: 999px;
  color: transparent;
  font-size: 0;
  overflow: hidden;
  user-select: none;
}

.builder-skeleton-tabs span:nth-child(3),
.builder-skeleton-tabs span:nth-child(4) {
  width: 120px;
}

.builder-skeleton-tabs span.is-active {
  background: linear-gradient(
    90deg,
    rgba(var(--theme-primary-rgb), 0.22),
    rgba(var(--theme-primary-rgb), 0.34),
    rgba(var(--theme-primary-rgb), 0.22)
  );
  background-size: 220% 100%;
  animation: none;
}

.builder-skeleton-design,
.builder-skeleton-forms,
.builder-skeleton-reservations,
.builder-skeleton-chrome,
.builder-skeleton-users,
.builder-skeleton-theme,
.builder-skeleton-publish,
.builder-skeleton-data {
  width: min(1500px, 100%);
  margin: 28px auto 0;
}

.builder-skeleton-design {
  display: grid;
  grid-template-columns: minmax(220px, 0.7fr) minmax(0, 1.7fr) minmax(220px, 0.75fr);
  gap: 18px;
  align-items: stretch;
}

.builder-skeleton-side-panel,
.builder-skeleton-inspector,
.builder-skeleton-canvas,
.builder-skeleton-document,
.builder-skeleton-calendar,
.builder-skeleton-site-preview,
.builder-skeleton-users,
.builder-skeleton-swatches,
.builder-skeleton-theme-preview,
.builder-skeleton-table {
  min-width: 0;
  border: 1px solid var(--madar-border);
  border-radius: 14px;
  background-color: var(--madar-surface);
  box-shadow: 0 12px 28px rgba(var(--theme-shadow-rgb), 0.045);
}

.builder-skeleton-side-panel,
.builder-skeleton-inspector {
  min-height: 520px;
  display: grid;
  align-content: start;
  gap: 14px;
  padding: 18px;
}

.builder-skeleton-line,
.builder-skeleton-wide-line,
.builder-skeleton-pill {
  display: block;
  height: 14px;
  border-radius: 999px;
}

.builder-skeleton-line:nth-child(odd) {
  width: 78%;
}

.builder-skeleton-line:nth-child(even) {
  width: 100%;
}

.builder-skeleton-pill {
  width: 100%;
  height: 42px;
  border-radius: 11px;
}

.builder-skeleton-canvas {
  min-height: 620px;
  display: grid;
  align-content: start;
  gap: 18px;
  padding: 24px;
}

.builder-skeleton-hero {
  display: block;
  min-height: 220px;
  border-radius: 12px;
}

.builder-skeleton-section-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.builder-skeleton-section-grid span {
  min-height: 150px;
  border-radius: 12px;
}

.builder-skeleton-forms,
.builder-skeleton-reservations,
.builder-skeleton-chrome,
.builder-skeleton-data {
  display: grid;
  grid-template-columns: minmax(240px, 0.55fr) minmax(0, 1.45fr);
  gap: 18px;
  align-items: start;
}

.builder-skeleton-document {
  min-height: 610px;
  display: grid;
  align-content: start;
  gap: 16px;
  padding: 22px;
}

.builder-skeleton-wide-line {
  width: min(440px, 80%);
  height: 22px;
}

.builder-skeleton-question {
  min-height: 122px;
  display: grid;
  gap: 14px;
  padding: 18px;
  border: 1px solid var(--madar-border);
  border-radius: 12px;
  background-color: var(--madar-surface);
}

.builder-skeleton-question span {
  display: block;
  height: 16px;
  border-radius: 999px;
  background: rgba(var(--theme-shadow-rgb), 0.08);
}

.builder-skeleton-question span:last-child {
  height: 40px;
  border-radius: 10px;
}

.builder-skeleton-reservations,
.builder-skeleton-chrome,
.builder-skeleton-data {
  grid-template-columns: minmax(0, 1.35fr) minmax(260px, 0.65fr);
}

.builder-skeleton-calendar {
  min-height: 520px;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 10px;
  padding: 18px;
}

.builder-skeleton-calendar span {
  min-height: 64px;
  border-radius: 10px;
}

.builder-skeleton-site-preview {
  min-height: 560px;
  display: grid;
  grid-template-rows: 72px 1fr 110px;
  gap: 18px;
  padding: 20px;
}

.builder-skeleton-site-header,
.builder-skeleton-site-body,
.builder-skeleton-site-footer {
  display: block;
  border-radius: 12px;
}

.builder-skeleton-users {
  display: grid;
  gap: 12px;
  padding: 18px;
}

.builder-skeleton-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.builder-skeleton-stats span {
  min-height: 96px;
  border-radius: 12px;
}

.builder-skeleton-user-row {
  min-height: 74px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) 140px;
  gap: 14px;
  align-items: center;
  padding: 14px;
  border-radius: 12px;
}

.builder-skeleton-user-row span {
  height: 16px;
  border-radius: 999px;
}

.builder-skeleton-user-row span:first-child {
  width: 42px;
  height: 42px;
  border-radius: 999px;
}

.builder-skeleton-theme {
  display: grid;
  grid-template-columns: minmax(260px, 0.75fr) minmax(0, 1.25fr);
  gap: 18px;
}

.builder-skeleton-swatches {
  min-height: 460px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  padding: 18px;
}

.builder-skeleton-swatches span {
  min-height: 88px;
  border-radius: 12px;
}

.builder-skeleton-theme-preview {
  min-height: 460px;
  display: grid;
  align-content: start;
  gap: 18px;
  padding: 22px;
}

.builder-skeleton-theme-preview span {
  min-height: 92px;
  border-radius: 12px;
}

.builder-skeleton-theme-preview span:first-child {
  min-height: 170px;
}

.builder-skeleton-publish {
  display: grid;
  gap: 18px;
}

.builder-skeleton-status-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.builder-skeleton-status-grid span,
.builder-skeleton-share-grid span {
  min-height: 112px;
  border: 1px solid var(--madar-border);
  border-radius: 14px;
}

.builder-skeleton-share-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.builder-skeleton-share-grid span {
  min-height: 260px;
}

.builder-skeleton-table {
  min-height: 540px;
  display: grid;
  align-content: start;
  gap: 10px;
  padding: 18px;
}

.builder-skeleton-table span {
  height: 54px;
  border-radius: 10px;
}

@media (max-width: 1180px) {
  .builder-skeleton-design,
  .builder-skeleton-forms,
  .builder-skeleton-reservations,
  .builder-skeleton-chrome,
  .builder-skeleton-theme,
  .builder-skeleton-data {
    grid-template-columns: 1fr;
  }

  .builder-skeleton-side-panel,
  .builder-skeleton-inspector {
    min-height: 220px;
  }

  .builder-skeleton-status-grid,
  .builder-skeleton-share-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .builder-skeleton-workspace {
    padding: 0 16px 24px;
  }

  .builder-skeleton-tabs {
    justify-content: flex-start;
    overflow: hidden;
    gap: 14px;
  }

