  gap: 8px;
  align-items: center;
}

.forms-header-actions button,
.question-actions button,
.forms-rail-heading button,
.question-type-bar button,
.forms-side-card button,
.add-question-wide {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 36px;
  border: 1px solid var(--forms-border);
  border-radius: 8px;
