  background: transparent;
}

.forms-live-preview-page .runtime-form {
  width: 100%;
  min-width: 0;
  padding: 18px;
  border: 0;
  border-radius: 0;
  background: var(--form-theme-surface);
}

.forms-live-preview-page .runtime-form,
.forms-live-preview-page .runtime-form * {
