}

.forms-live-preview-page {
  overflow-x: hidden;
}

.forms-live-preview-page .form-page-counter-title {
  width: fit-content;
  justify-self: center;
  margin-bottom: 4px;
  padding: 5px 12px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--form-theme-accent) 8%, transparent);
  color: var(--form-theme-accent);
  font-size: 18px;
  letter-spacing: -0.02em;
}

.forms-live-preview-page .runtime-form-section-header .form-page-title {
