  gap: 16px;
  align-items: start;
  direction: ltr;
}

.forms-simple-document,
.simple-side-panel,
.simple-preview-panel,
.forms-simple-header label {
  direction: inherit;
}

.forms-simple-workbench[dir="rtl"] .forms-simple-document,
.forms-simple-workbench[dir="rtl"] .simple-side-panel,
.forms-simple-workbench[dir="rtl"] .simple-preview-panel,
.forms-simple-workbench[dir="rtl"] .forms-simple-header label {
  direction: rtl;
  text-align: right;
}

.forms-simple-workbench[dir="ltr"] .forms-simple-document,
.forms-simple-workbench[dir="ltr"] .simple-side-panel,
.forms-simple-workbench[dir="ltr"] .simple-preview-panel,
.forms-simple-workbench[dir="ltr"] .forms-simple-header label {
  direction: ltr;
  text-align: left;
}

.forms-simple-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.form-description-field {
  display: grid !important;
  gap: 6px !important;
  color: var(--madar-muted);
  font-size: 12px;
  font-weight: 900;
}

.forms-simple-meta span {
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(var(--theme-shadow-rgb), 0.07);
  color: var(--madar-muted);
  font-size: 12px;
  font-weight: 900;
}

.simple-add-question {
