  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

.simple-add-question label,
.simple-side-panel label {
  display: grid;
  gap: 6px;
  color: var(--madar-muted);
  font-size: 12px;
  font-weight: 900;
}

.forms-panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.forms-panel-heading > div {
