  justify-content: center;
  border-radius: 10px;
  background: rgba(var(--theme-shadow-rgb), 0.08);
  color: var(--madar-text);
  font-size: 13px;
  font-weight: 950;
}

.simple-add-question .panel-help {
  margin: -4px 0 0;
}

.forms-sidebar-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  padding: 10px;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.08);
  border-radius: 12px;
  background: rgba(var(--theme-shadow-rgb), 0.025);
}

.forms-sidebar-stats div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.forms-sidebar-stats span {
  color: var(--madar-muted);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.forms-sidebar-stats strong {
  min-width: 0;
  color: var(--madar-text);
  font-size: 14px;
  font-weight: 950;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.simple-add-question select,
.simple-add-question input {
  min-height: 44px;
  border-color: var(--color-border-control);
  border-radius: 12px;
  background-color: var(--madar-surface);
  color: var(--madar-text);
  font-weight: 900;
}

.forms-primary-action {
  width: 100%;
  min-height: 42px;
  border-color: transparent !important;
  border-radius: 12px !important;
  background: var(--theme-primary) !important;
  color: var(--theme-text-inverse) !important;
  box-shadow: 0 10px 22px rgba(var(--theme-primary-rgb), 0.2);
}

.forms-primary-action:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: rgba(var(--theme-primary-rgb), 0.28) !important;
  background: rgba(var(--theme-primary-rgb), 0.1) !important;
  color: var(--color-accent-text) !important;
  box-shadow: none;
}

.forms-secondary-actions,
.form-library-file-actions,
.forms-builder-actions {
  display: grid;
  gap: 8px;
}

.form-page-counter-title {
  width: 100%;
  margin: 0;
  padding: 4px 0 8px;
  color: var(--form-theme-text);
  font-size: clamp(20px, 2.2vw, 28px);
  font-weight: 950;
  line-height: 1.2;
  text-align: center;
}

.runtime-form-section-header .form-page-title,
.builder-form-preview-section .form-page-title {
  margin: 0 0 6px;
  color: var(--form-theme-text);
  font-size: 24px;
  font-weight: 950;
  line-height: 1.25;
}

.runtime-form-section-header .form-page-description,
.builder-form-preview-section .form-page-description {
  margin: 0;
  color: var(--form-theme-muted);
  font-size: 17px;
  font-weight: 500;
  line-height: 1.5;
}

.form-required-marker {
  color: var(--color-status-danger-text);
  font-weight: 950;
}

.form-library-file-actions {
  grid-template-columns: 1fr;
}

.form-library-file-actions .form-command-button {
  width: 100%;
  min-width: 0;
}

.form-import-guide {
  padding: 10px 12px;
  border: 1px solid var(--madar-border);
  border-radius: 12px;
  background: var(--madar-surface-soft);
}

.form-import-guide summary {
  cursor: pointer;
  color: var(--madar-text);
  font-size: 13px;
  font-weight: 900;
}

.form-import-guide p {
  color: var(--madar-muted);
  font-size: 12px;
  line-height: 1.45;
}

.form-import-guide pre {
  max-height: 260px;
  margin: 10px 0 0;
  padding: 10px;
  overflow: auto;
  border-radius: 10px;
  background: var(--madar-surface);
  color: var(--madar-text);
  font: 11px/1.5 Consolas, monospace;
  white-space: pre-wrap;
}

.forms-builder-actions {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.forms-builder-actions .form-command-button {
  min-height: 42px;
  border-radius: 12px;
}

.forms-theme-action-group {
  margin-top: 2px;
  padding-top: 0;
  border-top: 1px solid var(--madar-border);
}

.forms-theme-action-group > summary {
  min-height: 36px;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 7px;
  align-items: center;
  cursor: pointer;
  list-style: none;
  color: var(--color-accent-text);
  font-size: 12px;
  font-weight: 950;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.forms-theme-action-group > summary::-webkit-details-marker {
  display: none;
}

.forms-theme-action-group > summary::before {
  content: "▸";
  color: var(--madar-muted);
  font-size: 11px;
  transition: transform 0.15s ease;
}

.forms-theme-action-group[open] > summary::before {
  transform: rotate(90deg);
}

.forms-theme-action-body {
  display: grid;
  gap: 12px;
  padding-top: 8px;
}

.forms-theme-grid,
.forms-theme-shape-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.forms-theme-shape-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.forms-theme-token,
.forms-theme-shape-grid label {
  min-width: 0;
  display: grid;
  gap: 6px;
  color: var(--madar-text);
  font-size: 11px;
  font-weight: 900;
  line-height: 1.25;
}

.forms-theme-token > span:first-child,
.forms-theme-shape-grid label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.forms-theme-color-input {
  position: relative;
  min-height: 50px;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  align-items: center;
  align-content: center;
  gap: 8px;
  padding: 7px 9px 7px 7px;
  border: 1px solid var(--color-border-control);
  border-radius: 10px;
  background: var(--madar-surface);
}

.forms-theme-swatch {
  width: 26px;
  height: 26px;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.16);
  border-radius: 8px;
  background: var(--forms-theme-token);
  box-shadow: inset 0 0 0 1px rgba(var(--theme-text-inverse-rgb), 0.42);
}

.forms-theme-color-input strong {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  color: var(--madar-muted);
  font-size: 11px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.forms-theme-color-input input[type="color"] {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
  opacity: 0;
}

.forms-theme-shape-grid input {
  width: 100%;
  min-height: 42px;
  border-radius: 12px;
  background: var(--madar-surface);
}

.forms-theme-action-group > .form-command-button {
  margin-top: 2px;
}

.simple-add-question .form-command-button-primary,
.simple-action-group .form-command-button-primary {
  border-color: transparent !important;
  background: var(--theme-primary) !important;
  color: var(--theme-text-inverse) !important;
  box-shadow: 0 10px 22px rgba(var(--theme-primary-rgb), 0.2);
}

.simple-add-question .form-command-button-primary:hover:not(:disabled),
.simple-action-group .form-command-button-primary:hover:not(:disabled) {
  border-color: rgba(var(--theme-primary-rgb), 0.28) !important;
  background: rgba(var(--theme-primary-rgb), 0.1) !important;
  color: var(--color-accent-text) !important;
  box-shadow: none;
}

.simple-form-actions,
.simple-action-groups {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
  margin-top: 4px;
  padding-top: 14px;
  border-top: 1px solid var(--madar-border);
}

.simple-action-groups {
  gap: 12px;
}

.simple-action-group {
  display: grid;
  gap: 8px;
}

.simple-action-group-site {
  margin-top: 2px;
  border: 1px solid rgba(var(--theme-primary-rgb), 0.16);
  border-radius: 8px;
  padding: 10px;
  background: rgba(var(--theme-primary-rgb), 0.045);
}

.simple-action-group-title {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--madar-muted);
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0;
  text-transform: uppercase;
}

.simple-action-group-title::after {
  content: "";
  flex: 1 1 auto;
  height: 1px;
  background: rgba(var(--theme-shadow-rgb), 0.1);
}

.simple-action-group-site .simple-action-group-title {
  color: var(--color-accent-text);
}

[data-theme="dark"] .simple-action-group-site,
body.theme-dark .simple-action-group-site,
.theme-dark .simple-action-group-site {
