  background: rgba(var(--theme-primary-rgb), 0.1);
}

[data-theme="dark"] .simple-action-group-title::after,
body.theme-dark .simple-action-group-title::after,
.theme-dark .simple-action-group-title::after {
  background: var(--madar-border);
}

.simple-form-actions .form-command-button,
.simple-action-group .form-command-button {
  width: 100%;
  min-height: 42px;
  border-radius: 12px;
}

.simple-add-question > .form-command-button {
  width: 100%;
  min-height: 42px;
  border-radius: 12px;
}

.simple-side-panel,
.simple-preview-panel {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--forms-border);
  border-radius: 8px;
  background: var(--theme-surface);
  box-shadow: 0 10px 24px rgba(var(--theme-shadow-rgb), 0.06);
}

.simple-panel-grid {
