  grid-template-columns: minmax(180px, 1fr) minmax(220px, 1fr) auto;
  gap: 10px;
  align-items: end;
}

.simple-preview-panel .runtime-form {
  padding: 0;
  border: 0;
  box-shadow: none;
}

.forms-simple-document .forms-section-stack {
