}

.forms-simple-document .forms-add-page-button {
  width: 100%;
  min-height: 54px;
  border: 2px dashed rgba(var(--theme-primary-rgb), 0.32) !important;
  border-radius: 12px;
  background: rgba(var(--theme-primary-rgb), 0.05) !important;
  color: var(--color-accent-text) !important;
  font-weight: 800;
}

.forms-simple-document .forms-insert-page-button {
  width: 100%;
  min-height: 44px;
  border: 1px dashed rgba(var(--theme-primary-rgb), 0.3) !important;
  background: rgba(var(--theme-primary-rgb), 0.04) !important;
  color: var(--color-accent-text) !important;
}

.forms-simple-document .forms-insert-page-button:hover:not(:disabled) {
