}

.publish-qr-preview {
  display: grid;
  justify-items: center;
  align-content: start;
  gap: 9px;
  margin-top: 0;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.1);
  border-radius: 12px;
  padding: 10px;
  background: rgba(var(--theme-shadow-rgb), 0.025);
  color: var(--madar-muted);
  font-size: 12px;
  font-weight: 900;
}

.publish-qr-preview img {
  width: 124px;
