  border: 1px solid rgba(var(--theme-shadow-rgb), 0.12);
  border-radius: 9px;
  padding: 7px;
  background: var(--theme-text-inverse);
}

.publish-qr-empty {
  width: 118px;
  height: 118px;
  display: grid;
  place-items: center;
  border: 1px dashed rgba(var(--theme-shadow-rgb), 0.18);
  border-radius: 10px;
  background:
    linear-gradient(135deg, rgba(var(--theme-shadow-rgb), 0.04), transparent),
    var(--theme-text-inverse);
