.reservation-empty-actions,
.reservation-editor-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
}

.reservation-empty-actions button,
.reservation-editor-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 42px;
  border-radius: var(--form-theme-field-radius, 12px);
  padding: 0 15px;
  border: 1px solid var(--form-theme-border, var(--reservation-accent-border));
  background: var(--form-theme-input, var(--theme-surface));
  color: var(--form-theme-text, var(--madar-text));
  font-weight: 900;
}

.reservation-empty-actions button:hover,
.reservation-editor-actions button:hover {
  background: color-mix(in srgb, var(--form-theme-accent, var(--reservation-accent)) 8%, var(--form-theme-input, var(--theme-surface)));
  border-color: var(--form-theme-accent, var(--reservation-accent));
}

.reservation-empty-actions .primary-action {
  border-color: var(--form-theme-accent, var(--reservation-accent));
  background: var(--form-theme-accent, var(--reservation-accent));
  color: var(--form-theme-button-text, var(--theme-text-inverse));
  box-shadow: none;
}

.reservation-empty-actions .primary-action:hover {
  background: var(--form-theme-accent, var(--reservation-accent-dark));
  border-color: var(--form-theme-accent, var(--reservation-accent-dark));
  color: var(--form-theme-button-text, var(--theme-text-inverse));
}

.reservation-editor-layout {
  width: min(100%, 1720px);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 300px minmax(0, 1fr);
  gap: 18px;
  align-items: start;
  min-width: 0;
}

.reservation-block-list {
  position: sticky;
  top: 0;
  display: grid;
  gap: 14px;
  max-height: calc(100vh - 220px);
  overflow: auto;
  scrollbar-width: thin;
}

.reservation-panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.reservation-panel-heading > div {
  display: grid;
  gap: 3px;
}

.reservation-count {
  min-width: 0;
  height: auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--form-theme-muted, var(--madar-muted));
  font-size: 12px;
  font-weight: 850;
}

.reservation-library-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.object-list.reservation-block-list .reservation-library-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 38px;
  border: 1px solid var(--form-theme-border, rgba(var(--theme-shadow-rgb), 0.1));
  border-radius: var(--form-theme-field-radius, 10px);
  padding: 0 10px;
  background: var(--form-theme-input, var(--theme-surface));
  color: var(--form-theme-text, var(--madar-text));
  font-size: 12px;
  font-weight: 850;
  text-align: center;
  transform: none;
}

.object-list.reservation-block-list .reservation-library-actions button:hover {
  border-color: var(--form-theme-accent, var(--reservation-accent));
  background: color-mix(in srgb, var(--form-theme-accent, var(--reservation-accent)) 6%, var(--form-theme-input, var(--theme-surface)));
  color: var(--form-theme-text, var(--madar-text));
  transform: none;
}

.reservation-library-actions svg {
  color: var(--form-theme-accent, var(--reservation-accent));
  flex: 0 0 auto;
}

.reservation-summary {
  display: grid;
  gap: 4px;
  padding: 10px 0 12px;
  border-block: 1px solid var(--form-theme-border, rgba(var(--theme-shadow-rgb), 0.08));
  background: transparent;
}

.reservation-summary span {
  color: var(--form-theme-muted, var(--madar-muted));
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
}

.reservation-summary strong {
  overflow: hidden;
  color: var(--form-theme-text, var(--madar-text));
  font-size: 14px;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.object-list.reservation-block-list button {
  position: relative;
  display: grid;
  gap: 5px;
  width: 100%;
  border: 1px solid var(--form-theme-border, rgba(var(--theme-shadow-rgb), 0.1));
  border-radius: var(--form-theme-field-radius, 10px);
  padding: 12px 12px 12px 14px;
  background: var(--form-theme-input, var(--theme-surface));
  color: var(--form-theme-text, var(--madar-text));
  text-align: left;
  box-shadow: none;
  transform: none;
}

.object-list.reservation-block-list button.is-active {
  border-color: var(--form-theme-border, rgba(var(--theme-shadow-rgb), 0.16));
  background: color-mix(in srgb, var(--form-theme-accent, var(--reservation-accent)) 4%, var(--form-theme-surface, var(--theme-surface)));
  color: var(--form-theme-text, var(--madar-text));
  box-shadow: none;
  transform: none;
}

.object-list.reservation-block-list button.is-active::before {
  content: "";
  position: absolute;
  inset: 10px auto 10px 0;
  width: 3px;
  border-radius: 0 999px 999px 0;
  background: var(--form-theme-accent, var(--reservation-accent));
}

.object-list.reservation-block-list button:hover {
  border-color: var(--form-theme-accent, var(--reservation-accent));
  background: color-mix(in srgb, var(--form-theme-accent, var(--reservation-accent)) 5%, var(--form-theme-input, var(--theme-surface)));
  color: var(--form-theme-text, var(--madar-text));
  transform: none;
}

.object-list.reservation-block-list button strong {
  overflow: hidden;
  font-size: 14px;
  font-weight: 850;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.object-list.reservation-block-list button span {
  overflow: hidden;
  color: var(--form-theme-muted, var(--madar-muted));
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.reservation-empty-list {
  display: grid;
  place-items: center;
  gap: 8px;
  min-height: 140px;
  border: 1px dashed var(--madar-border-strong);
  border-radius: 16px;
  color: var(--madar-muted);
  text-align: center;
}

.reservation-empty-list p,
.reservation-editor-empty p {
  margin: 0;
}

.reservation-editor-card {
  display: grid;
  gap: 14px;
  max-height: none;
  overflow: visible;
  align-content: start;
}

.reservation-editor-card.is-empty {
  align-content: center;
  min-height: 220px;
  overflow: visible;
}

.reservation-editor-card textarea {
  min-height: 84px;
}

.reservation-editor-card .editor-card-header h3 {
  margin: 2px 0 0;
}
.reservation-build-name {
  width: min(360px, 100%);
  margin-top: 14px;
  display: grid;
  gap: 6px;
}

.reservation-build-name > span {
  color: var(--form-theme-muted, var(--madar-muted));
  font-size: 11px;
  font-weight: 850;
}

.reservation-build-name input {
  width: 100%;
  min-height: 40px;
}

.reservation-editor-card .editor-card-header .reservation-delete-block {
  border-color: rgba(var(--theme-danger-rgb), 0.2);
  color: var(--color-status-danger-text);
}

.reservation-editor-card .editor-card-header .reservation-delete-block:hover {
  background: rgba(var(--theme-danger-rgb), 0.08);
  border-color: rgba(var(--theme-danger-rgb), 0.32);
  color: var(--color-status-danger-text);
}

.reservation-settings-section {
  display: grid;
  gap: 12px;
  padding: 0 0 16px;
  border: 0;
  border-bottom: 1px solid rgba(var(--theme-shadow-rgb), 0.1);
  border-radius: 0;
  background: transparent;
}

.reservation-settings-section:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.reservation-settings-section h4 {
  margin: 2px 0 0;
  color: var(--madar-text);
  font-size: 16px;
}

.reservation-copy-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.reservation-wide-field {
  grid-column: 1 / -1;
}

.reservation-mode-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
}

.reservation-mode-card p {
  margin: 4px 0 0;
  color: var(--madar-muted);
  font-size: 13px;
  line-height: 1.45;
}

.reservation-mode-switch {
  display: inline-grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--madar-border);
  border-radius: 14px;
  background: var(--theme-surface);
}

.reservation-mode-switch button {
  min-height: 38px;
  border-radius: 10px;
  padding: 0 12px;
  background: transparent;
  color: var(--madar-muted);
  font-weight: 900;
  white-space: nowrap;
}

.reservation-mode-switch button.active {
  background: var(--reservation-accent);
  color: var(--theme-text-inverse);
  box-shadow: var(--madar-red-shadow);
}

.reservation-list-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.reservation-list-heading button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 36px;
  border-radius: 11px;
  padding: 0 11px;
  background: var(--reservation-accent-soft);
  color: var(--reservation-accent);
  font-weight: 900;
}

.reservation-bullet-editor {
  display: grid;
  gap: 8px;
}

.reservation-bullet-row {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) 36px;
  gap: 9px;
  align-items: center;
  padding: 8px;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.1);
  border-radius: 10px;
  background: var(--theme-surface);
}

.reservation-bullet-row input {
  width: 100%;
  min-width: 0;
  min-height: 38px;
  border: 0 !important;
  background: transparent !important;
  padding: 0 4px !important;
}

.reservation-bullet-row input:focus {
  box-shadow: none !important;
}

.reservation-bullet-row > svg {
  color: var(--reservation-accent);
  justify-self: center;
}

.reservation-bullet-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--reservation-accent);
  justify-self: center;
  box-shadow: 0 0 0 5px var(--reservation-accent-soft);
}

.reservation-bullet-row button {
  display: inline-grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 11px;
  padding: 0;
  color: var(--color-status-danger-text);
  background: rgba(var(--theme-danger-rgb), 0.08);
}

.reservation-bullet-row button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.reservation-time-editor {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 230px), 1fr));
}

.reservation-time-editor .reservation-bullet-row {
  grid-template-columns: 18px minmax(120px, 1fr) 36px;
}

.reservation-time-editor input[type="time"] {
  overflow: hidden;
}

.reservation-date-heading {
  display: flex;
  gap: 12px;
  align-items: center;
}

.reservation-date-heading-icon,
.reservation-date-card-icon {
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  color: var(--reservation-accent);
  background: var(--reservation-accent-soft);
}

.reservation-date-heading-icon {
  width: 44px;
  height: 44px;
  border-radius: 14px;
}

.reservation-date-heading p {
  margin: 4px 0 0;
  color: var(--madar-muted);
  font-size: 13px;
}

.reservation-calendar-picker {
  position: relative;
  width: min(100%, 360px);
  z-index: 4;
}

.reservation-calendar-trigger {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) 20px;
  gap: 10px;
  align-items: center;
  width: 100%;
  min-height: 58px;
  padding: 9px 12px;
  border: 1px solid var(--reservation-accent-border);
  border-radius: 14px;
  background: var(--theme-surface);
  color: var(--madar-text);
  text-align: left;
}

.reservation-calendar-trigger:hover,
.reservation-calendar-trigger[aria-expanded="true"] {
  border-color: var(--reservation-accent);
  box-shadow: 0 0 0 3px var(--reservation-accent-soft);
}

.reservation-calendar-trigger-icon {
  display: inline-grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  color: var(--reservation-accent);
  background: var(--reservation-accent-soft);
}

.reservation-calendar-trigger > span:nth-child(2) {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.reservation-calendar-trigger small {
  color: var(--madar-muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.reservation-calendar-trigger strong {
  font-size: 13px;
}

.reservation-calendar-trigger[aria-expanded="true"] > svg {
  transform: rotate(180deg);
}

.reservation-calendar-popover {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  z-index: 30;
  width: min(340px, calc(100vw - 48px));
  padding: 14px;
  border: 1px solid var(--reservation-accent-border);
  border-radius: 18px;
  background: var(--theme-surface);
  color: var(--madar-text);
  box-shadow: 0 20px 50px rgba(var(--theme-shadow-rgb), 0.24);
}

.reservation-calendar-toolbar,
.reservation-calendar-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}

.reservation-calendar-toolbar {
  margin-bottom: 12px;
}

.reservation-calendar-toolbar > strong {
  font-size: 14px;
}

.reservation-calendar-toolbar > div {
  display: flex;
  gap: 5px;
}

.reservation-calendar-toolbar button {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border-radius: 10px;
  background: var(--madar-surface-soft);
}

.reservation-calendar-weekdays,
.reservation-calendar-days {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
}

.reservation-calendar-weekdays {
  margin-bottom: 5px;
}

.reservation-calendar-weekdays span {
  color: var(--madar-muted);
  font-size: 10px;
  font-weight: 800;
  text-align: center;
  text-transform: uppercase;
}

.reservation-calendar-days button,
.reservation-calendar-days .is-empty {
  aspect-ratio: 1;
}

.reservation-calendar-days button {
  min-width: 0;
  min-height: 34px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--madar-text);
  font-size: 12px;
  font-weight: 800;
}

.reservation-calendar-days button:hover:not(:disabled) {
  border-color: var(--reservation-accent-border);
  background: var(--reservation-accent-soft);
}

.reservation-calendar-days button.is-today {
  border-color: var(--reservation-accent);
  color: var(--reservation-accent);
}

.reservation-calendar-days button.is-selected {
  border-color: var(--reservation-accent);
  background: var(--reservation-accent);
  color: var(--theme-on-primary, white);
  opacity: 1;
}

.reservation-calendar-footer {
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--madar-border);
}

.reservation-calendar-footer button {
  min-height: 32px;
  padding: 0 10px;
  border-radius: 9px;
  color: var(--reservation-accent);
  background: transparent;
  font-size: 11px;
  font-weight: 800;
}

@media (max-width: 520px) {
  .reservation-calendar-picker {
    width: 100%;
  }

  .reservation-calendar-popover {
    right: 0;
    left: auto;
  }
}
.reservation-date-picker-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
}

.reservation-date-card {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) 34px;
  gap: 10px;
  align-items: center;
  min-height: 66px;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.1);
  border-radius: 15px;
  padding: 9px 10px;
  background: var(--theme-surface);
  color: var(--madar-text);
  box-shadow: 0 8px 20px rgba(var(--theme-shadow-rgb), 0.05);
}

.reservation-date-card-icon {
  width: 38px;
  height: 38px;
  border-radius: 12px;
}

.reservation-date-card > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.reservation-date-card small {
  color: var(--madar-muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.reservation-date-card strong {
  overflow: hidden;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.reservation-date-card button {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border-radius: 10px;
  color: var(--color-status-danger-text);
  background: rgba(var(--theme-danger-rgb), 0.08);
}

.reservation-date-empty {
  grid-column: 1 / -1;
  margin: 0;
  padding: 16px;
  border: 1px dashed var(--madar-border);
  border-radius: 13px;
  color: var(--madar-muted);
  text-align: center;
}
.reservation-editor-empty {
  display: grid;
  grid-template-columns: 52px minmax(220px, 1fr) minmax(360px, 0.95fr);
  gap: 18px;
  align-items: center;
  width: min(100%, 960px);
  min-height: 150px;
  padding: 18px;
  border: 1px solid var(--form-theme-border, rgba(var(--theme-shadow-rgb), 0.08));
  border-radius: var(--form-theme-radius, 14px);
  background: var(--form-theme-surface, var(--theme-surface));
  color: var(--form-theme-muted, var(--madar-muted));
}

.reservation-editor-empty h3 {
  margin: 0;
  color: var(--form-theme-text, var(--madar-text));
}

.reservation-empty-icon {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border: 1px solid var(--form-theme-border, rgba(var(--theme-shadow-rgb), 0.1));
  border-radius: var(--form-theme-field-radius, 12px);
  background: var(--form-theme-input, var(--theme-surface));
  color: var(--form-theme-accent, var(--reservation-accent));
}

.reservation-empty-copy {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.reservation-empty-actions {
  justify-content: stretch;
}

.reservation-empty-actions button {
  min-height: 64px;
  justify-content: flex-start;
  border-radius: var(--form-theme-field-radius, 12px);
  padding: 10px 12px;
  text-align: left;
}

.reservation-empty-actions button span {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.reservation-empty-actions button strong,
.reservation-empty-actions button small {
  display: block;
}

.reservation-empty-actions button small {
  color: inherit;
  font-size: 12px;
  font-weight: 650;
  line-height: 1.25;
  opacity: 0.72;
}

.reservation-empty-actions .primary-action small {
  opacity: 0.82;
}

@media (max-width: 1320px) {
  .reservation-editor-layout {
    grid-template-columns: 280px minmax(0, 1fr);
    min-width: 0;
  }

  .reservation-editor-empty {
    grid-template-columns: 52px minmax(0, 1fr);
  }

  .reservation-empty-actions {
    grid-column: 1 / -1;
  }
}

@media (max-width: 860px) {
  .reservations-workspace {
    max-height: none;
    overflow: visible;
  }

  .reservation-editor-layout {
    grid-template-columns: 1fr;
    min-width: 0;
  }

  .reservation-block-list {
    position: static;
    max-height: none;
  }

  .reservation-editor-card {
    max-height: none;
