/* Reservations route hierarchy and shared card rhythm. */
.page-builder .reservations-header :is(h1, p),
.page-builder .reservation-panel-heading h2,
.page-builder .reservation-editor-card h2 {
  margin: 0;
}

.page-builder .reservations-header h1 {
  color: var(--pb-text, var(--theme-text));
  font-size: clamp(24px, 2vw, 30px);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.page-builder .reservation-panel-heading h2,
.page-builder .reservation-editor-card h2 {
  color: var(--pb-text, var(--theme-text));
  font-size: 16px;
  font-weight: 800;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

.page-builder .reservation-editor-layout {
  gap: 18px;
  align-items: stretch;
}

.page-builder :is(.reservation-block-list, .reservation-editor-card) {
  min-height: 220px;
  padding: 20px;
  border: 1px solid var(--pb-border, var(--theme-border));
  border-radius: var(--pb-radius, 14px);
  background: var(--pb-surface, var(--theme-surface));
  box-sizing: border-box;
}

.page-builder .reservation-editor-card {
  min-width: 0;
  container: reservation-editor / inline-size;
}
.page-builder .reservation-block-list {
  align-content: start;
