  border-radius: 12px;
  background: var(--pb-surface, var(--madar-surface));
}

.page-builder .reservation-workspace-summary strong {
  overflow: hidden;
  color: var(--pb-text, var(--madar-text));
  font-size: 15px;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.page-builder .reservation-workspace-summary span {
  color: var(--pb-muted, var(--madar-muted));
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.page-builder .reservation-editor-card:not(.is-empty) {
  grid-template-columns: minmax(280px, 0.85fr) minmax(340px, 1.15fr);
  align-content: start;
}

.page-builder .reservation-editor-card > .editor-card-header,
.page-builder .reservation-copy-section,
.page-builder .reservation-mode-section {
  grid-column: 1 / -1;
}

.page-builder .reservation-services-section {
  grid-column: 1;
  grid-row: span 2;
  align-self: start;
}

.page-builder .reservation-schedule-section {
  grid-column: 2;
}

.page-builder .reservation-editor-card.is-flexible .reservation-services-section {
  grid-column: 1 / -1;
  grid-row: auto;
}

.page-builder .reservation-settings-section {
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--pb-border, var(--madar-border));
  border-radius: 14px;
  background: var(--pb-surface-soft, var(--madar-surface-soft));
}

.page-builder .reservation-settings-section:last-child {
  padding-bottom: 16px;
  border-bottom: 1px solid var(--pb-border, var(--madar-border));
}

.page-builder .reservation-settings-section :is(h3, h4) {
  margin: 2px 0 0;
  color: var(--pb-text, var(--madar-text));
  font-size: 16px;
  font-weight: 850;
}

@media (max-width: 1320px) {
  .page-builder .reservation-editor-card:not(.is-empty) {
    grid-template-columns: 1fr;
