  gap: 8px;
}

.page-builder .reservation-setup-steps button {
  min-width: 0;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 9px;
  align-items: center;
  min-height: 56px;
  padding: 8px 10px;
  border: 1px solid var(--color-border-control);
  border-radius: 12px;
  background: var(--madar-surface-soft);
  color: var(--madar-muted);
  text-align: left;
}

.page-builder .reservation-setup-steps button > span {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 999px;
  background: var(--madar-surface);
  font-size: 12px;
  font-weight: 900;
}

.page-builder .reservation-setup-steps button > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.page-builder .reservation-setup-steps :is(strong, small) {
