  text-overflow: ellipsis;
  white-space: nowrap;
}

.page-builder .reservation-setup-steps button.is-active {
  border-color: var(--reservation-accent);
  background: var(--reservation-accent-soft);
  color: var(--madar-text);
}

.page-builder .reservation-setup-steps button.is-active > span {
  background: var(--reservation-accent);
  color: var(--theme-text-inverse);
}

.page-builder .reservation-step-actions {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding-top: 4px;
}

.page-builder .reservation-step-actions > span {
  color: var(--madar-muted);
  font-size: 12px;
  text-align: center;
}

.page-builder .reservation-step-actions button {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid var(--color-border-control);
  border-radius: 11px;
  background: var(--madar-surface);
  color: var(--madar-text);
  font-weight: 850;
}

.page-builder .reservation-step-actions button.primary-action {
  border-color: var(--reservation-accent);
  background: var(--reservation-accent);
  color: var(--theme-text-inverse);
}

.page-builder .reservation-step-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

@media (max-width: 860px) {
  .page-builder .reservation-setup-steps,
  .page-builder .reservation-step-actions {
    grid-template-columns: 1fr;
  }

  .page-builder .reservation-step-actions > span {
    order: -1;
  }
}

/* Booking element builder — mirrors the page builder interaction language. */
.page-builder .reservation-block-builder-section {
