.page-builder [dir="rtl"] .results-form-list-scroll button,
.page-builder [dir="rtl"] .responses-card-list button,
.page-builder [dir="rtl"] .analytics-list button,
.page-builder [dir="rtl"] .results-data-table th,
.page-builder [dir="rtl"] .results-data-table td {
  text-align: right;
}

.page-builder [dir="rtl"] .responses-card-list button:hover,
.page-builder [dir="rtl"] .responses-card-list button.active,
.page-builder [dir="rtl"] .results-form-list-scroll button.active,
.page-builder [dir="rtl"] .results-form-list-scroll button:hover {
  box-shadow: inset -3px 0 0 var(--madar-red);
}

.page-builder .analysis-method-tabs strong,
.page-builder .analysis-method-tabs span {
  display: block;
}

.page-builder .analysis-method-tabs span {
  color: inherit;
  opacity: 0.72;
  font-size: 12px;
  line-height: 1.35;
  font-weight: 800;
}

.page-builder .analysis-result-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.page-builder .analysis-result-grid article {
  min-width: 0;
  border: 1px solid var(--madar-border);
  border-radius: 8px;
  padding: 12px;
  background: var(--madar-surface-soft);
}

.page-builder .analysis-result-grid span {
  display: block;
  color: var(--madar-muted);
  font-size: 12px;
  font-weight: 950;
}

.page-builder .analysis-result-grid strong {
  display: block;
  margin-top: 7px;
  color: var(--madar-text);
  font-size: 16px;
  font-weight: 950;
  line-height: 1.35;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.page-builder .analytics-empty.compact {
  padding: 18px 12px;
}

.page-builder .analysis-json-output.friendly {
  background: var(--madar-surface-soft);
  color: var(--madar-text);
}

@media (max-width: 1100px) {
  .page-builder .results-summary-grid,
  .page-builder .analytics-summary-grid,
  .page-builder .form-info-grid,
  .page-builder .analysis-runner-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .page-builder .results-layout,
  .page-builder .analytics-layout,
  .page-builder .responses-data-browser,
  .page-builder .analysis-dashboard-grid,
  .page-builder .analysis-workflow-grid,
  .page-builder .analysis-workbench-layout,
  .page-builder .analysis-source-body,
  .page-builder .analysis-data-layout {
    grid-template-columns: 1fr;
  }

  .page-builder .analysis-control-rail {
    position: static;
    max-height: none;
  }

  .page-builder .analysis-cleaning-grid,
  .page-builder .analysis-form-grid,
  .page-builder .analysis-method-tabs {
    grid-template-columns: 1fr;
  }

  .page-builder .results-form-list {
    position: static;
  }

  .page-builder .responses-list-panel {
    max-height: none;
  }

  .page-builder .responses-answer-grid,
  .page-builder .responses-detail-meta {
    grid-template-columns: 1fr;
  }
}
/* Data Analysis Workspace styles are chunked in ./data-analysis for easier debugging. */
/* ============================================================
   Data Analysis Workspace
   Clean guided data/report flow
   ============================================================ */

.page-builder {
  --daw-btn-height: 38px;
  --daw-btn-radius: 12px;
  --daw-btn-padding: 0 14px;
  --daw-btn-font-size: 12px;
  --daw-btn-font-weight: 900;

  --daw-primary-bg: var(--theme-primary);
  --daw-primary-bg-hover: var(--theme-primary-hover);
  --daw-primary-text: var(--theme-surface);
  --daw-primary-shadow: 0 14px 28px rgba(var(--theme-primary-rgb), 0.18);

  --daw-secondary-bg: var(--theme-surface-2);
  --daw-secondary-bg-hover: var(--theme-primary-soft);
  --daw-secondary-border: var(--theme-border);
  --daw-secondary-text: var(--theme-text);

  --daw-tab-bg: var(--theme-surface-2);
  --daw-tab-border: var(--theme-border);
  --daw-tab-active-bg: var(--theme-primary-soft);
  --daw-tab-active-border: rgba(var(--theme-primary-rgb), 0.28);
  --daw-tab-active-text: var(--theme-primary);

  --daw-card-bg: var(--theme-surface);
  --daw-card-border: var(--theme-border);
  --daw-soft-bg: var(--theme-surface-2);
  --daw-text: var(--theme-text);
  --daw-muted: var(--theme-text-soft);
  --daw-red: var(--madar-red, var(--theme-primary));
  --daw-red-dark: var(--madar-red-dark, var(--theme-primary-hover));
}
/* ============================================================
   Page base
   ============================================================ */

.page-builder .daw-page {
  width: 100%;
  margin: 0;
  color: var(--daw-text);
  flex: 1 1 auto !important;
  min-height: 0 !important;
  overflow-y: auto !important;
}

.page-builder .daw-page *,
.page-builder .daw-page *::before,
.page-builder .daw-page *::after {
  box-sizing: border-box;
}

.page-builder .daw-page button,
.page-builder .daw-page summary,
.page-builder .daw-page input,
.page-builder .daw-page select,
.page-builder .daw-page textarea {
  font-family: inherit;
}

.page-builder .daw-page button,
.page-builder .daw-page summary {
  -webkit-tap-highlight-color: transparent;
}

.page-builder .daw-page button:disabled,
.page-builder .daw-page summary:disabled,
.page-builder .daw-stepper button:disabled {
  opacity: 0.52;
  cursor: not-allowed;
  transform: none !important;
  box-shadow: none !important;
}
/* ============================================================
   Header
   ============================================================ */

.page-builder .daw-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  margin-bottom: 22px;
}

.page-builder .daw-kicker,
.page-builder .daw-section-heading > span,
.page-builder .daw-report-header span {
  display: inline-flex;
  width: fit-content;
  margin-bottom: 8px;
  color: var(--action-primary, var(--theme-primary));
  font-size: 13px;
  font-weight: 950;
  line-height: 1.2;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.page-builder .daw-page[dir="rtl"] .daw-kicker,
.page-builder .daw-page[dir="rtl"] .daw-section-heading > span,
.page-builder .daw-page[dir="rtl"] .daw-report-header span {
  letter-spacing: 0;
  text-transform: none;
}

.page-builder .daw-header h1 {
  margin: 0;
  color: var(--daw-text);
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 950;
  line-height: 1.04;
  letter-spacing: -0.05em;
}

.page-builder .daw-header p {
  max-width: 760px;
  margin: 12px 0 0;
  color: var(--daw-muted);
  font-size: 15px;
  line-height: 1.65;
}
/* ============================================================
   Button system
   ============================================================ */

.page-builder .daw-primary,
.page-builder .daw-page button.daw-primary,
.page-builder .daw-button-row .daw-primary,
.page-builder .daw-section-actions .daw-primary,
.page-builder .daw-report-submit-row .daw-primary,
.page-builder .daw-flow-actions .daw-primary,
.page-builder .daw-header .daw-primary,
.page-builder .daw-assistant-card .daw-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--daw-btn-height);
  height: var(--daw-btn-height);
  padding: var(--daw-btn-padding);
  border: 1px solid transparent;
  border-radius: var(--daw-btn-radius);
  background: var(--daw-primary-bg);
  color: var(--daw-primary-text);
  font-size: var(--daw-btn-font-size);
  font-weight: var(--daw-btn-font-weight);
  line-height: 1;
  text-decoration: none;
  box-shadow: var(--daw-primary-shadow);
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease,
    opacity 0.2s ease;
}

.page-builder .daw-primary:hover,
.page-builder .daw-page button.daw-primary:hover,
.page-builder .daw-header .daw-primary:hover,
.page-builder .daw-assistant-card .daw-primary:hover {
  background: var(--daw-primary-bg-hover);
  color: var(--theme-text-inverse);
  transform: translateY(-1px);
  box-shadow: 0 18px 34px rgba(var(--theme-primary-rgb), 0.24);
}

.page-builder .daw-button-row button:not(.daw-primary),
.page-builder .daw-section-actions button:not(.daw-primary),
.page-builder .daw-report-submit-row button:not(.daw-primary),
.page-builder .daw-flow-actions button:not(.daw-primary),
.page-builder .daw-secondary,
.page-builder .daw-pagination button,
.page-builder .daw-column-menu summary,
.page-builder .daw-column-menu-panel button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--daw-btn-height);
  height: var(--daw-btn-height);
  padding: var(--daw-btn-padding);
  border: 1px solid var(--daw-secondary-border);
  border-radius: var(--daw-btn-radius);
  background: var(--daw-secondary-bg);
  color: var(--daw-secondary-text);
  font-size: var(--daw-btn-font-size);
  font-weight: var(--daw-btn-font-weight);
  line-height: 1;
  box-shadow: none;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease;
}

.page-builder .daw-button-row button:not(.daw-primary):hover,
.page-builder .daw-section-actions button:not(.daw-primary):hover,
.page-builder .daw-report-submit-row button:not(.daw-primary):hover,
.page-builder .daw-flow-actions button:not(.daw-primary):hover,
.page-builder .daw-secondary:hover,
.page-builder .daw-pagination button:hover,
.page-builder .daw-column-menu summary:hover,
.page-builder .daw-column-menu-panel button:hover {
  background: var(--daw-secondary-bg-hover);
  border-color: rgba(var(--theme-primary-rgb), 0.18);
  color: var(--daw-red);
  transform: translateY(-1px);
}
/* ============================================================
   Stepper
   ============================================================ */

.page-builder .daw-stepper {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 16px;
}

.page-builder .daw-stepper button {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 48px;
  padding: 9px 12px;
  border: 1px solid rgba(var(--theme-shadow-rgb), 0.1);
  border-radius: 12px;
  background: rgba(var(--theme-text-inverse-rgb), 0.78);
  color: var(--daw-text);
  box-shadow: 0 10px 24px rgba(var(--theme-shadow-rgb), 0.05);
  cursor: pointer;
  text-align: start;
  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.page-builder .daw-stepper button:hover:not(:disabled) {
  border-color: rgba(var(--theme-primary-rgb), 0.16);
  background: rgba(var(--theme-primary-rgb), 0.05);
  transform: translateY(-1px);
}

.page-builder .daw-stepper button.active {
  border-color: rgba(var(--theme-primary-rgb), 0.24);
  background: rgba(var(--theme-primary-rgb), 0.08);
  color: var(--daw-red);
  box-shadow: 0 14px 28px rgba(var(--theme-primary-rgb), 0.08);
}

.page-builder .daw-stepper button.locked {
  opacity: 0.62;
  border-style: dashed;
  cursor: not-allowed;
}

.page-builder .daw-stepper button.locked:hover:not(:disabled) {
  border-color: rgba(var(--theme-shadow-rgb), 0.1);
  background: rgba(var(--theme-text-inverse-rgb), 0.78);
  transform: none;
  box-shadow: 0 10px 24px rgba(var(--theme-shadow-rgb), 0.05);
}

.page-builder .daw-stepper button span {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 10px;
  background: rgba(var(--theme-shadow-rgb), 0.08);
  color: var(--daw-text);
  font-size: 13px;
  font-weight: 950;
  flex: 0 0 auto;
  transition:
    background 0.2s ease,
    color 0.2s ease;
}

.page-builder .daw-stepper button.active span {
  background: var(--daw-primary-bg);
  color: var(--theme-text-inverse);
}

.page-builder .daw-stepper button strong {
  display: block;
  overflow: hidden;
  color: inherit;
  font-size: 13px;
  font-weight: 950;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* ============================================================
   Layout
   ============================================================ */

.page-builder .daw-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}

.page-builder .daw-scroll-nav,
.page-builder .daw-page-jumpbar,
.page-builder .daw-page-sidebar,
.page-builder .daw-fixed-sidebar,
.page-builder .daw-scroll-rail,
.page-builder .daw-vertical-slider {
  display: none !important;
}

.page-builder .daw-flow {
  display: grid;
  gap: 16px;
  min-width: 0;
  scroll-margin-top: 110px;
}

.page-builder .daw-step-content {
  display: grid;
  min-width: 0;
  gap: 18px;
}

.page-builder .daw-step-report .daw-step-content {
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
}

.page-builder .daw-report-builder-foundation {
  min-height: 1px;
}

.page-builder .daw-canvas-column {
  min-width: 0;
  position: sticky;
  top: 104px;
  scroll-margin-top: 110px;
}

.page-builder #daw-top,
.page-builder #daw-workspace-main,
.page-builder #daw-assistant,
.page-builder #daw-flow-actions,
.page-builder #daw-report-preview {
  scroll-margin-top: 110px;
}

/* ============================================================
   Normal vertical slider bar
   ============================================================ */

.daw-normal-slider {
  display: none !important;
}

.daw-normal-slider-track {
  position: relative !important;
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  cursor: pointer !important;
  touch-action: none !important;
  outline: none !important;
}

.daw-normal-slider-track:focus-visible {
  box-shadow: inset 0 0 0 2px rgba(var(--theme-text-inverse-rgb), 0.28) !important;
}

.daw-normal-slider-thumb {
  position: absolute !important;
  left: 50% !important;
  display: block !important;
  width: 10px !important;
  min-height: 28px !important;
  border-radius: 999px !important;
  background: var(--text-muted) !important;
  transform: translateX(-50%) !important;
  pointer-events: none !important;
}

.daw-normal-slider-track:hover .daw-normal-slider-thumb,
.daw-normal-slider-track:focus-visible .daw-normal-slider-thumb {
  background: var(--text-secondary) !important;
}

.daw-page[dir="rtl"] .daw-normal-slider {
  right: auto !important;
  left: 0 !important;
  border-left: 0 !important;
  border-right: 1px solid rgba(var(--theme-text-inverse-rgb), 0.12) !important;
}
/* ============================================================
   Cards
   ============================================================ */

.page-builder .daw-card {
  min-width: 0;
  border: 1px solid var(--daw-card-border);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(var(--theme-text-inverse-rgb), 0.96), rgba(var(--theme-text-inverse-rgb), 0.88)),
    var(--daw-card-bg);
  box-shadow: 0 24px 70px rgba(var(--theme-shadow-rgb), 0.09);
}

.page-builder .daw-section-card,
.page-builder .daw-assistant-card,
.page-builder .daw-report-canvas {
  padding: 20px;
}

.page-builder .daw-section-heading {
  margin-bottom: 18px;
}

.page-builder .daw-section-heading h3,
.page-builder .daw-report-header h3 {
  margin: 0;
  color: var(--daw-text);
  font-size: 22px;
  font-weight: 950;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

.page-builder .daw-section-heading p,
.page-builder .daw-report-header p,
.page-builder .daw-source-body p {
  margin: 8px 0 0;
  color: var(--daw-muted);
  font-size: 13px;
  line-height: 1.55;
}
/* ============================================================
   Source tabs and source body
   ============================================================ */

.page-builder .daw-source-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 18px;
}

.page-builder .daw-source-tabs button,
.page-builder .daw-review-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 34px;
  padding: 0 14px;
  border: 1px solid var(--daw-tab-border);
  border-radius: 10px;
  background: var(--daw-tab-bg);
  color: var(--daw-text);
  font-size: 12px;
  font-weight: 900;
  line-height: 1.1;
  text-align: center;
  cursor: pointer;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    color 0.2s ease,
    transform 0.2s ease;
}

.page-builder .daw-source-tabs button {
  min-width: 168px;
  width: auto;
}

.page-builder .daw-source-tabs button:hover,
.page-builder .daw-review-actions button:hover {
  background: rgba(var(--theme-primary-rgb), 0.08);
  border-color: rgba(var(--theme-primary-rgb), 0.18);
  color: var(--daw-red);
  transform: translateY(-1px);
}

.page-builder .daw-source-tabs button.active,
.page-builder .daw-review-actions button.active {
  background: var(--daw-tab-active-bg);
  border-color: var(--daw-tab-active-border);
  color: var(--daw-tab-active-text);
  box-shadow: inset 0 0 0 1px rgba(var(--theme-primary-rgb), 0.05);
}

.page-builder .daw-source-body {
  display: grid;
  gap: 16px;
}

.page-builder .daw-source-body h4 {
  margin: 0;
  color: var(--daw-text);
  font-size: 17px;
  font-weight: 950;
}
/* ============================================================
   Fields
   ============================================================ */

.page-builder .daw-field {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.page-builder .daw-field.wide {
  grid-column: 1 / -1;
}

.page-builder .daw-field > span,
.page-builder .daw-toggle > span {
  color: var(--daw-text);
  font-size: 13px;
  font-weight: 950;
}

.page-builder .daw-field input,
.page-builder .daw-field select,
.page-builder .daw-field textarea {
  width: 100%;
  min-height: 44px;
  border: 1px solid var(--daw-card-border);
  border-radius: 14px;
  padding: 0 13px;
  background: var(--theme-surface);
  color: var(--daw-text);
  font: inherit;
  font-size: 13px;
  font-weight: 850;
  outline: none;
}

.page-builder .daw-field input[type="checkbox"] {
  width: 18px;
  min-width: 18px;
  height: 18px;
  min-height: 18px;
  border-radius: 5px;
  padding: 0;
  accent-color: var(--daw-red);
}

.page-builder .daw-field textarea {
  min-height: 112px;
  padding: 12px 13px;
  line-height: 1.5;
  resize: vertical;
}

.page-builder .daw-field input:focus,
.page-builder .daw-field select:focus,
.page-builder .daw-field textarea:focus,
.page-builder .daw-data-grid-toolbar input:focus {
  border-color: rgba(var(--theme-primary-rgb), 0.45);
  box-shadow: 0 0 0 4px rgba(var(--theme-primary-rgb), 0.1);
}

.page-builder .daw-field small {
  color: var(--daw-muted);
  font-size: 12px;
  font-weight: 750;
}
/* ============================================================
   Actions
   ============================================================ */

.page-builder .daw-button-row,
.page-builder .daw-section-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.page-builder .daw-flow-actions {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 6px;
  border: 1px solid var(--daw-card-border);
  border-radius: 18px;
  padding: 10px;
  background: rgba(var(--theme-text-inverse-rgb), 0.72);
}

.page-builder .daw-flow-actions button {
  min-width: 96px;
  gap: 8px;
}

.page-builder .daw-flow-actions.only-next {
  justify-content: flex-end;
}

.page-builder .daw-page[dir="rtl"] .daw-flow-actions.only-next {
  justify-content: flex-start;
}

.page-builder .daw-report-submit-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 18px;
  border: 1px solid rgba(var(--theme-primary-rgb), 0.18);
  border-radius: 18px;
  padding: 16px;
  background:
    linear-gradient(135deg, rgba(var(--theme-primary-rgb), 0.08), rgba(var(--theme-shadow-rgb), 0.04)),
    var(--theme-surface);
}

.page-builder .daw-report-submit-row div {
  min-width: 0;
}

.page-builder .daw-report-submit-row strong {
  display: block;
  color: var(--daw-text);
  font-size: 15px;
  font-weight: 950;
}

.page-builder .daw-report-submit-row span {
  display: block;
  margin-top: 5px;
  color: var(--daw-muted);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.45;
}

.page-builder .daw-report-submit-row .daw-primary {
  flex: 0 0 auto;
}

.page-builder .daw-page[dir="rtl"] .daw-report-submit-row {
  flex-direction: row;
  text-align: right;
}
/* ============================================================
   File dropzone
   ============================================================ */

.page-builder .daw-file-dropzone {
  display: grid;
  gap: 7px;
  min-height: 118px;
  border: 1px dashed rgba(var(--theme-shadow-rgb), 0.3);
  border-radius: 18px;
  padding: 22px;
  background:
    linear-gradient(180deg, rgba(var(--theme-text-inverse-rgb), 0.94), rgba(247, 248, 251, 0.92)),
    rgba(var(--theme-shadow-rgb), 0.03);
  cursor: pointer;
