  line-height: 1.55;
}

.page-builder .page-delete-modal-copy strong {
  color: var(--madar-text);
}

.page-builder .page-delete-modal-actions {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.page-builder .page-delete-modal-actions button {
  min-height: 48px;
  border-radius: 14px;
  padding: 0 16px;
  font-weight: 950;
}

.page-builder .page-delete-modal-secondary {
