}

.tenant-runtime-card.tenant-runtime-status-loading,
.tenant-runtime-card.tenant-runtime-status-unavailable {
  width: min(560px, calc(100vw - 32px));
  display: grid;
  justify-items: center;
  gap: 14px;
  text-align: center;
}

.tenant-site-runtime > .tenant-runtime-main.tenant-runtime-loading-screen {
  position: relative;
  min-height: 100dvh;
  padding: 24px;
  overflow: hidden;
  background: var(--theme-bg) !important;
  isolation: isolate;
}

.tenant-site-runtime > .tenant-runtime-main.tenant-runtime-loading-screen::before {
  content: "";
  position: absolute;
  width: min(64vw, 760px);
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(var(--theme-primary-rgb), 0.09), transparent 68%);
  filter: blur(8px);
  pointer-events: none;
  z-index: -1;
}

.tenant-brand-loader {
  display: grid;
  justify-items: center;
  gap: clamp(16px, 2.4vmin, 28px);
  color: var(--theme-text);
  text-align: center;
}

.tenant-brand-loader-mark {
  position: relative;
  width: clamp(240px, 70vmin, 720px);
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  animation: tenant-brand-arrive 560ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.tenant-brand-loader-mark::before {
  content: "";
  position: absolute;
  inset: -12px;
  border: 1px solid rgba(var(--theme-primary-rgb), 0.24);
  border-radius: 50%;
  animation: tenant-brand-halo 1.8s ease-out infinite;
}

.tenant-brand-loader-mark > span {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  border: 1px solid var(--theme-border);
  border-radius: 28%;
  background: var(--theme-surface);
  color: var(--theme-primary);
  font-size: clamp(72px, 22vmin, 220px);
  font-weight: 950;
  box-shadow: 0 18px 50px rgba(var(--theme-shadow-rgb), 0.1);
}

.tenant-brand-loader-mark img {
  position: absolute;
  inset: 8px;
  width: calc(100% - 16px);
  height: calc(100% - 16px);
  object-fit: contain;
  background: var(--theme-bg);
  transform-origin: center;
  will-change: transform;
  animation: tenant-brand-logo-spin 1.6s linear infinite;
}

.tenant-brand-loader-name {
  margin: 0;
  color: var(--theme-text);
  font-size: clamp(18px, 2.4vmin, 28px);
  font-weight: 850;
  letter-spacing: 0.08em;
  line-height: 1.3;
  text-transform: uppercase;
  animation: tenant-brand-copy-in 420ms 120ms ease-out both;
}

.tenant-brand-loader-progress {
  position: relative;
  width: clamp(120px, 18vmin, 220px);
  height: 3px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(var(--theme-primary-rgb), 0.14);
}

.tenant-brand-loader-progress::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: var(--theme-primary);
  animation: tenant-brand-progress 1.15s ease-in-out infinite;
  transform-origin: left;
}

@keyframes tenant-brand-arrive {
  from { opacity: 0; transform: scale(0.84) translateY(10px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

@keyframes tenant-brand-copy-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes tenant-brand-halo {
  0% { opacity: 0.7; transform: scale(0.88); }
  70%, 100% { opacity: 0; transform: scale(1.16); }
}

@keyframes tenant-brand-progress {
  0% { transform: translateX(-100%) scaleX(0.45); }
  50% { transform: translateX(0) scaleX(0.75); }
  100% { transform: translateX(100%) scaleX(0.45); }
}

