.tenant-brand-loader-mark:has(img) {
  width: min(620px, 78vw);
  aspect-ratio: 4 / 3;
}

.tenant-brand-loader-mark:has(img)::before {
  inset: -8px;
  border-radius: 36px;
  animation: tenant-brand-halo 2.2s ease-out infinite;
}

.tenant-brand-loader-mark:has(img) > span {
  border-radius: 30px;
}

.tenant-brand-loader-mark img {
  inset: 0;
  width: 100%;
  height: 100%;
  border: 1px solid var(--theme-border);
  border-radius: 30px;
  object-fit: cover;
  object-position: center;
  background: var(--theme-surface);
  animation: tenant-brand-arrive 560ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.tenant-publication-warning-backdrop {
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(var(--theme-shadow-rgb), 0.56);
  backdrop-filter: blur(4px);
}

.tenant-publication-warning {
  width: min(520px, 100%);
  display: grid;
  gap: 14px;
  padding: 28px;
  border: 1px solid var(--theme-border);
  border-radius: 20px;
  background: var(--theme-surface);
  color: var(--theme-text);
  box-shadow: 0 24px 80px rgba(var(--theme-shadow-rgb), 0.3);
}

.tenant-publication-warning h2,
.tenant-publication-warning p {
  margin: 0;
}

.tenant-publication-warning p {
  color: var(--theme-muted);
  line-height: 1.65;
}

.tenant-publication-warning-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: flex-end;
}
/* ============================================================
   Madar App Builder v4 — Responsive
   Must be imported last
   ============================================================ */

@media (max-width: 1380px) {
  .page-builder .workspace-context-bar {
    grid-template-columns: 1fr;
  }

  .page-builder .workspace-context-controls {
    justify-content: flex-start;
    flex-wrap: wrap;
  }

  .page-builder .forms-layout {
    grid-template-columns: 240px minmax(0, 1fr);
  }

  .page-builder .google-form-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .page-builder .google-form-actions {
    grid-column: auto;
    position: static;
  }

  .page-builder .form-side-settings {
    grid-column: 2;
    position: static;
  }

  .page-builder .theme-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .page-builder .theme-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .page-builder .theme-section-actions {
    justify-content: flex-start;
  }
}

@media (max-width: 1240px) {
  .page-builder .users-grid,
  .page-builder .publish-grid {
    grid-template-columns: 1fr;
  }

}

.builder-canvas.viewport-tablet .site-row.columns-3,
.builder-canvas.viewport-tablet .site-row.columns-4 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.builder-canvas.viewport-mobile .site-row.columns-2,
.builder-canvas.viewport-mobile .site-row.columns-3,
.builder-canvas.viewport-mobile .site-row.columns-4 {
  grid-template-columns: 1fr;
}

@media (max-width: 980px) {
  .page-builder .forms-layout {
    grid-template-columns: 1fr;
  }

  .page-builder .google-form-layout,
  .page-builder .google-question-topline,
  .page-builder .google-section-header {
    grid-template-columns: 1fr;
  }

  .page-builder .google-form-actions {
    grid-column: auto;
  }

  .page-builder .object-list,
  .page-builder .form-side-settings {
    position: static;
  }

  .page-builder .field-row,
  .page-builder .user-row,
  .page-builder .question-card {
    grid-template-columns: 1fr;
  }

  .page-builder .form-connect-card {
    grid-template-columns: 1fr;
  }

  .page-builder .form-connect-actions {
    flex-wrap: wrap;
  }

  .page-builder .theme-grid,
  .page-builder .section-library-grid,
  .page-builder .starter-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 899px) {
  .page-builder .builder-desktop-shell {
    display: none;
  }

  .page-builder .builder-mobile-blocker {
    position: fixed;
    inset: 0;
    z-index: 1000;
    min-height: 100dvh;
    display: grid;
    place-items: center;
    padding: 24px 18px;
    background: rgba(12, 13, 18, 0.72);
    color: var(--madar-text);
    text-align: center;
    backdrop-filter: blur(10px);
  }

  .page-builder .builder-mobile-blocker div {
    width: min(100%, 520px);
    background: var(--madar-surface);
    border: 1px solid var(--madar-border);
    border-radius: 18px;
    padding: 32px;
    box-shadow: var(--madar-shadow-md);
  }

  .page-builder .builder-mobile-blocker h2 {
    margin: 0 0 10px;
    color: var(--madar-text);
    font-size: 24px;
