  border-radius: 8px;
  padding: 18px;
  background: var(--theme-surface);
}

.page-builder .daw-plot-editor-card.active {
  border-color: var(--theme-border);
  box-shadow: none;
}

.page-builder .daw-plot-editor-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.page-builder .daw-plot-editor-card-header span {
