  align-items: center;
  gap: 10px;
  min-height: 44px;
}

.page-builder .daw-color-mode-toggle {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  min-height: 44px;
  border: 1px solid var(--theme-border);
  border-radius: 8px;
  padding: 0 13px;
  background: var(--theme-surface);
  color: var(--daw-text);
  font-size: 12px;
  font-weight: 900;
}

.page-builder .daw-gradient-toggle {
  width: 100%;
}

.page-builder .daw-color-mode-toggle input[type="checkbox"],
.page-builder .daw-color-control input[type="checkbox"] {
