.page-builder .daw-series-color-row {
  min-width: 0;
  min-height: 36px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  border-radius: 10px;
  padding: 5px 8px;
  background: transparent;
}

.page-builder .daw-series-color-row input[type="color"] {
  width: 30px;
  min-width: 30px;
  height: 28px;
  border: 1px solid var(--daw-card-border);
  border-radius: 8px;
  padding: 2px;
  cursor: pointer;
}

.page-builder .daw-series-color-row span {
  min-width: 0;
  overflow: hidden;
  color: var(--daw-text);
  font-size: 12px;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.page-builder .daw-series-colors + small {
  display: block;
  margin-top: 2px;
}

.page-builder .daw-modal-actions {
  justify-content: flex-end;
  margin-top: 0;
}

/* Dark mode */
.theme-dark .page-builder .daw-visualization-card,
[data-theme="dark"] .page-builder .daw-visualization-card,
.theme-dark .page-builder .daw-visualization-frame,
[data-theme="dark"] .page-builder .daw-visualization-frame {
