/* Responsive */
@media (max-width: 820px) {
  .page-builder .daw-visualization-frame,
  .page-builder .daw-visualization-frame iframe {
    min-height: 320px;
  }

  .page-builder .daw-visualization-builder-header,
  .page-builder .daw-visualization-actions,
