/* Final Page Builder chrome layer.
   Keep this import last. It normalizes editor UI without styling the tenant canvas. */

.page-builder {
  --pb-bg: var(--builder-bg);
  --pb-surface: var(--builder-surface-1);
  --pb-surface-raised: var(--builder-surface-2);
  --pb-surface-muted: var(--builder-surface-3);
  --pb-border: var(--builder-border);
  --pb-border-strong: var(--builder-border-strong);
  --pb-hover: var(--builder-hover);
  --pb-selected: var(--builder-selected);
  --pb-text: var(--builder-text);
  --pb-muted: var(--builder-text-muted);
  --pb-accent: var(--theme-primary);
  --pb-accent-soft: var(--theme-primary-soft);
  --pb-danger: var(--theme-danger);
  --pb-radius-sm: 10px;
  --pb-radius: 14px;
  --pb-radius-lg: 18px;
  --pb-shadow: var(--builder-chrome-shadow);
  background: var(--pb-bg) !important;
  color: var(--pb-text) !important;
}

:root:not([data-theme="dark"]) .page-builder {
  --pb-radius-sm: var(--app-radius-control);
  --pb-radius: var(--app-radius-card);
  --pb-radius-lg: var(--app-radius-panel);
}

.page-builder .builder-topbar,
.page-builder .builder-subbar,
.page-builder .workspace-header {
  background: var(--pb-surface) !important;
  border-color: var(--pb-border) !important;
