.page-builder .dashboard-panel,
.page-builder .users-panel,
.page-builder .users-roles-panel,
.page-builder .user-row,
.page-builder .user-settings-panel,
.page-builder .role-editor-card,
.page-builder .permission-group,
.page-builder .users-card,
.page-builder .publish-panel,
