}

.page-builder .site-chrome-color-control output {
  color: var(--pb-text);
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 13px;
  font-weight: 650;
}

.page-builder .site-chrome-color-control button {
  min-height: 32px;
  padding: 0 10px;
  border: 1px solid var(--color-border-control);
  border-radius: 8px;
  background: var(--pb-surface-raised);
  color: var(--pb-text);
  cursor: pointer;
  font-size: 12px;
  font-weight: 700;
}

.page-builder .site-chrome-color-control button:disabled {
  cursor: default;
  opacity: 0.45;
}

.page-builder .site-chrome-footer-structure {
  min-width: 0;
