.builder-project-chooser-list > button:hover {
  transform: translateY(-2px);
  border-color: rgba(var(--theme-primary-rgb), 0.35);
  box-shadow: 0 18px 36px rgba(var(--theme-shadow-rgb), 0.09);
}

.builder-project-chooser-list > button:focus-visible {
  outline: 3px solid rgba(var(--theme-primary-rgb), 0.22);
  outline-offset: 2px;
}

.builder-project-chooser-list strong {
  font-size: 15px;
  font-weight: 750;
}

.builder-project-chooser-list span {
  color: var(--theme-text-muted);
  font-size: 12px;
  line-height: 1.45;
}

@keyframes builder-project-progress {
  0% { transform: translateX(-110%); }
  55% { transform: translateX(125%); }
  100% { transform: translateX(270%); }
}

@keyframes builder-project-shimmer {
  100% { transform: translateX(100%); }
}

@keyframes builder-project-pulse {
  0%, 100% { opacity: 0.55; }
  50% { opacity: 1; }
}

@media (max-width: 720px) {
  .builder-project-loading-screen {
    min-height: calc(100dvh - 24px);
    padding: 24px 16px;
  }

  .builder-project-chooser {
    min-height: auto;
    padding: 30px 18px 48px;
  }

  .builder-project-chooser-header {
    margin-bottom: 26px;
  }

  .builder-project-loading-heading,
  .builder-project-loading-list {
    padding-right: 18px;
    padding-left: 18px;
  }

  .builder-project-loading-row {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  .builder-project-loading-status {
    display: none;
  }

  .builder-project-loading-note {
    padding-right: 18px;
    padding-left: 18px;
  }

  .builder-project-opening-preview {
    grid-template-columns: 78px minmax(0, 1fr);
    min-height: 260px;
    padding: 14px;
  }

  .builder-project-opening-inspector {
    display: none;
  }

  .builder-project-chooser-list {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 460px) {
  .builder-project-loading-screen {
    padding-inline: 12px;
  }

  .builder-project-loading-heading {
    align-items: flex-start;
    padding: 20px 18px 18px;
  }

  .builder-project-opening-preview {
    grid-template-columns: minmax(0, 1fr);
  }

  .builder-project-opening-sidebar {
    display: none;
  }

  .builder-project-opening-canvas {
    min-height: 230px;
    padding: 24px 20px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .builder-project-loading-progress > span,
  .builder-project-loading-icon::after,
  .builder-project-loading-copy > span::after,
  .builder-project-loading-status::after,
  .builder-project-loading-note > span,
  .builder-project-opening-sidebar > span::after,
  .builder-project-opening-inspector > span::after,
  .builder-project-opening-canvas > span::after,
  .builder-project-opening-canvas > div > span::after {
    animation: none;
  }

  .builder-project-loading-progress > span {
    width: 68%;
    transform: none;
  }
}
