  font-weight: var(--font-weight-medium);
  line-height: 1.3;
  cursor: pointer;
}

.admin-dashboard-page .settings-page .notification-preference-row:first-child {
  border-top: 0;
}

.notification-preference-toggle {
  position: relative;
  display: inline-flex;
  flex: 0 0 auto;
}

.admin-dashboard-page .settings-page .notification-preference-toggle input {
  position: absolute;
  width: 1px;
  min-height: 1px;
  height: 1px;
  padding: 0;
  opacity: 0;
}

.notification-preference-toggle > span {
  position: relative;
  width: 42px;
  height: 24px;
  background: var(--theme-surface-3) !important;
  border: 1px solid var(--theme-border-strong);
  border-radius: 999px;
  transition: background 0.18s ease, border-color 0.18s ease;
}

.notification-preference-toggle > span::after {
  content: "";
  position: absolute;
  top: 3px;
  inset-inline-start: 3px;
  width: 16px;
  height: 16px;
  background: var(--theme-surface) !important;
  border-radius: 50%;
  box-shadow: 0 1px 4px rgba(var(--theme-shadow-rgb), 0.2);
  transition: transform 0.18s ease;
}

.notification-preference-toggle input:checked + span {
  background: var(--theme-primary) !important;
  border-color: var(--color-accent-text);
}

.notification-preference-toggle input:checked + span::after {
  transform: translateX(18px);
}

.settings-page[dir="rtl"] .notification-preference-toggle input:checked + span::after {
  transform: translateX(-18px);
}

.notification-preference-toggle input:focus-visible + span {
  outline: 3px solid rgba(var(--theme-primary-rgb), 0.18);
  outline-offset: 2px;
}

.notification-preference-toggle input:disabled + span {
  cursor: wait;
  opacity: 0.62;
}

