/* Theme changes use one short root snapshot transition. This avoids adding
   transitions to every component and keeps the update visually coordinated. */
::view-transition-old(root),
::view-transition-new(root) {
  animation-duration: 140ms;
  animation-timing-function: ease-out;
}

::view-transition-old(root) {
  animation-name: madar-theme-fade-out;
}

::view-transition-new(root) {
  animation-name: madar-theme-fade-in;
}

@keyframes madar-theme-fade-out {
  to { opacity: 0; }
}

@keyframes madar-theme-fade-in {
  from { opacity: 0; }
}

/* Fallback for browsers without View Transitions. Limit the transition to
   application structure and controls instead of matching every DOM node. */
html.theme-transitioning :where(
