}

.ecommerce-style-footer .ecommerce-footer-quick-links {
  justify-items: center;
  text-align: center;
}

.ecommerce-style-footer .ecommerce-footer-quick-links h4 {
  width: 100%;
  text-align: center;
}

.ecommerce-style-footer :is(.ecommerce-footer-column, .ecommerce-footer-contact) h4 {
  margin: 0 0 14px;
  color: var(--workspace-footer-text) !important;
  font-size: clamp(15px, 1.55cqi, 19px);
  font-weight: 900;
  letter-spacing: 0;
  line-height: 1.2;
  text-transform: none;
}

.ecommerce-style-footer .ecommerce-footer-links-grid {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
  justify-items: center;
  gap: 12px 20px;
}

.ecommerce-style-footer .ecommerce-footer-links-grid button {
  max-width: 100%;
  margin: 0;
  padding: 4px 0;
  border: 0;
  background: transparent;
  color: var(--workspace-footer-muted) !important;
  font-size: clamp(13px, 1.3cqi, 16px);
  font-weight: 550;
  line-height: 1.45;
  text-align: center;
  overflow-wrap: anywhere;
}

.ecommerce-style-footer .ecommerce-footer-links-grid button:hover {
  color: var(--workspace-footer-text) !important;
}

.ecommerce-style-footer .ecommerce-contact-row {
  max-width: 100%;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 4px 0;
  color: var(--workspace-footer-muted) !important;
  font-size: clamp(13px, 1.3cqi, 16px);
  line-height: 1.45;
  text-decoration: none;
  overflow-wrap: anywhere;
}

.ecommerce-style-footer .ecommerce-contact-row svg {
  color: var(--workspace-footer-text);
}

.builder-canvas .ecommerce-style-footer .ecommerce-contact-row span {
  color: var(--workspace-footer-text) !important;
  -webkit-text-fill-color: var(--workspace-footer-text) !important;
  opacity: 1 !important;
}

.ecommerce-style-footer .ecommerce-contact-row:hover {
  color: var(--workspace-footer-text) !important;
}

.ecommerce-style-footer .ecommerce-payment-row {
  margin-top: 8px;
}

.ecommerce-style-footer .ecommerce-payment-row :is(a, span) {
  min-width: 0;
  padding: 7px 10px;
  border: 1px solid color-mix(in srgb, var(--theme-text-inverse) 18%, transparent);
  border-radius: 7px;
  background: color-mix(in srgb, var(--theme-text-inverse) 4%, transparent);
  color: var(--workspace-footer-muted) !important;
  font-size: 12px;
  text-decoration: none;
}

.ecommerce-style-footer .ecommerce-footer-bottom {
  width: min(100%, 1200px);
  max-width: none;
  margin: clamp(40px, 6cqi, 72px) auto 0;
  padding-top: clamp(20px, 2.4cqi, 30px);
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 20px;
  border-top: 1px solid color-mix(in srgb, var(--theme-text-inverse) 28%, transparent);
  color: var(--workspace-footer-muted) !important;
  font-size: clamp(11px, 1.15cqi, 14px);
  text-align: center;
}

.ecommerce-style-footer .ecommerce-footer-bottom p {
  margin: 0;
  grid-column: 2;
  justify-self: center;
}

.ecommerce-style-footer .powered-by-madar {
  grid-column: 3;
  justify-self: end;
  margin: 0;
  padding: 10px 15px;
  border: 0;
  border-radius: 999px;
  background: var(--theme-accent);
  color: var(--theme-text-inverse);
  font-size: 12px;
  font-weight: 850;
  white-space: nowrap;
  box-shadow: 0 10px 24px rgba(var(--theme-primary-rgb), 0.24);
}

@container site-footer (max-width: 760px) {
  .ecommerce-style-footer .ecommerce-footer-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 38px 28px;
  }

  .ecommerce-style-footer .ecommerce-footer-grid[data-section-count="3"] .ecommerce-footer-brand {
    grid-column: 1 / -1;
  }

  .ecommerce-style-footer .ecommerce-footer-links-grid {
    grid-template-columns: minmax(0, 1fr);
  }


  .ecommerce-style-footer .ecommerce-footer-grid[data-section-count="1"] {
    grid-template-columns: minmax(0, 1fr);
  }
}

@container site-footer (max-width: 520px) {
  .ecommerce-style-footer {
    padding: 32px 24px 24px;
  }

  .ecommerce-style-footer .ecommerce-footer-grid,
  .ecommerce-style-footer .ecommerce-footer-bottom {
    grid-template-columns: minmax(0, 1fr);
  }

  .ecommerce-style-footer .ecommerce-footer-grid {
    gap: 36px;
  }

  .ecommerce-style-footer .ecommerce-footer-brand {
    grid-column: auto;
  }

  .ecommerce-style-footer :is(
    .ecommerce-footer-brand,
    .ecommerce-footer-column,
    .ecommerce-footer-contact
  ) {
    width: 100%;
    justify-items: center;
    text-align: center;
  }

  .ecommerce-style-footer .ecommerce-footer-logo-row {
    justify-content: center;
  }

  .ecommerce-style-footer .ecommerce-social-row,
  .ecommerce-style-footer .ecommerce-payment-row {
    justify-content: center;
  }

  .ecommerce-style-footer .ecommerce-footer-links-grid {
    width: min(100%, 290px);
    gap: 14px 24px;
  }

  .ecommerce-style-footer .ecommerce-contact-row {
    width: min(100%, 220px);
    grid-template-columns: 22px minmax(0, 1fr);
    justify-self: center;
    text-align: start;
  }

  .ecommerce-style-footer .ecommerce-footer-bottom {
    width: 100%;
    margin-top: 32px;
    padding-top: 22px;
    gap: 16px;
    justify-items: center;
    text-align: center;
  }

  .ecommerce-style-footer .ecommerce-footer-bottom p,
  .ecommerce-style-footer .powered-by-madar {
    grid-column: 1;
  }

  .ecommerce-style-footer .powered-by-madar {
    justify-self: center;
  }

  .ecommerce-style-footer .ecommerce-footer-links-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* ============================================================
   TEMP: Builder demo route styles
   We will move this later into PageBuilder files.
   ============================================================ */

.builder-demo-main {
  min-height: calc(100vh - 110px);
  padding: 0 24px 32px;
}

.builder-demo-main .page-builder {
  border: 1px solid var(--theme-border);
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 18px 45px rgba(var(--theme-shadow-rgb), 0.08);
}

@media (max-width: 900px) {
  .builder-demo-main {
    padding: 0 16px 24px;
  }
}

/* ============================================================
   TEMP: Tenant Site Runtime — Header / Login / Footer
   We will move this later into:
   styles/admin/PageBuilder/tenant-runtime.css
   ============================================================ */

.tenant-site-runtime {
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr auto;
  background: var(--theme-bg);
  color: var(--theme-text);
}

.tenant-site-header {
  background: var(--theme-surface);
  border-bottom: 1px solid var(--theme-border);
  position: sticky;
  top: 0;
  z-index: 20;
}

.tenant-site-header-inner {
  min-height: 78px;
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
}

.tenant-site-brand {
  justify-self: start;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border: 0;
  background: transparent;
  color: var(--theme-text);
  font-size: 18px;
  font-weight: 950;
  cursor: pointer;
}

.tenant-site-brand img {
  width: 42px;
  height: 42px;
  object-fit: contain;
  border-radius: 10px;
}

.tenant-logo-fallback {
  width: 42px;
  height: 42px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: var(--theme-gradient);
  color: var(--theme-text-inverse);
  font-weight: 950;
}

.tenant-site-nav {
  justify-self: center;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  flex-wrap: wrap;
}

.tenant-site-nav :is(button, a) {
  border: 0;
  border-radius: 999px;
  padding: 9px 14px;
  background: transparent;
  color: var(--theme-text-soft);
  font-weight: 900;
  cursor: pointer;
  text-decoration: none;
}

.tenant-site-nav :is(button, a):hover,
.tenant-site-nav :is(button, a).active {
  background: var(--theme-surface-2);
  color: var(--theme-text);
}

.tenant-site-cta {
  justify-self: end;
  border: 0;
  border-radius: 999px;
  padding: 12px 18px;
  cursor: pointer;
  color: var(--theme-text-inverse);
  background: var(--theme-gradient);
  box-shadow: 0 12px 26px rgba(var(--theme-primary-rgb), 0.18);
  font-weight: 950;
  text-decoration: none;
}

.tenant-login-runtime {
  min-height: calc(100vh - 78px);
  display: grid;
  align-items: center;
  background:
    radial-gradient(circle at top left, rgba(var(--theme-primary-rgb), 0.07), transparent 34%),
    linear-gradient(180deg, var(--theme-surface) 0%, var(--theme-bg) 100%);
}

.tenant-login-runtime .login-page {
  min-height: auto;
  padding: 70px 24px;
  background: transparent;
}

.tenant-runtime-main {
  min-height: 560px;
  display: grid;
  place-items: center;
  padding: 64px 24px;
  background:
    radial-gradient(circle at top left, rgba(var(--theme-primary-rgb), 0.07), transparent 34%),
    linear-gradient(180deg, var(--theme-surface) 0%, var(--theme-bg) 100%);
}

.tenant-runtime-card {
  width: min(720px, 100%);
  border: 1px solid var(--theme-border);
  border-radius: 28px;
  background: var(--theme-surface);
  padding: 34px;
  box-shadow: 0 18px 45px rgba(var(--theme-shadow-rgb), 0.08);
  text-align: center;
}

.tenant-eyebrow {
  display: inline-flex;
  margin: 0 0 12px;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(var(--theme-primary-rgb), 0.1);
  color: var(--theme-primary);
  font-size: 12px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.tenant-runtime-card h1 {
  margin: 0;
  color: var(--theme-text);
  font-size: clamp(34px, 5vw, 54px);
  line-height: 1.04;
  font-weight: 950;
  letter-spacing: -0.05em;
}

.tenant-runtime-card p {
  margin: 14px auto 0;
  max-width: 560px;
  color: var(--theme-text-soft);
  font-size: 17px;
  line-height: 1.65;
}

.tenant-runtime-actions {
  margin-top: 24px;
  display: flex;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
}

.tenant-runtime-actions button {
  border: 0;
  border-radius: 14px;
  padding: 13px 18px;
  cursor: pointer;
  color: var(--theme-text-inverse);
  background: var(--theme-gradient);
  box-shadow: 0 12px 26px rgba(var(--theme-primary-rgb), 0.18);
  font-weight: 950;
}

.tenant-site-footer {
  background: var(--theme-surface);
  border-top: 1px solid var(--theme-border);
  color: var(--theme-text);
  padding: 36px 5% 22px;
}

.tenant-footer-grid {
  max-width: 980px;
  width: 100%;
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(240px, 1fr) minmax(260px, 1fr) minmax(190px, 0.85fr);
  gap: clamp(24px, 4vw, 48px);
  align-items: start;
}

.tenant-footer-brand {
  display: grid;
  gap: 16px;
  align-content: start;
  justify-items: center;
  text-align: center;
}

.tenant-footer-logo-row {
  display: grid;
  justify-items: center;
  gap: 8px;
}

.tenant-footer-logo-row h3 {
  margin: 0;
  color: var(--theme-text);
  font-size: 28px;
  line-height: 1.05;
  font-weight: 950;
}

.tenant-footer-brand p {
  margin: 0;
  color: var(--theme-text-soft);
  line-height: 1.6;
  max-width: 380px;
}

.tenant-footer-logo {
  width: 76px;
  height: 76px;
  object-fit: contain;
}

.tenant-footer-logo-fallback {
  border-radius: 20px;
  display: grid;
  place-items: center;
  background: var(--theme-gradient);
  color: var(--theme-text-inverse);
  font-size: 28px;
  font-weight: 950;
}

.tenant-social-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
}

.tenant-social-row button,
.tenant-social-row a,
.tenant-social-row > span {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  border: 1px solid var(--theme-border);
  color: var(--theme-text);
  background: var(--theme-surface);
  font-size: 11px;
  font-weight: 900;
  cursor: pointer;
  text-decoration: none;
}

.tenant-payment-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.tenant-payment-row a,
.tenant-payment-row span {
  border: 1px solid var(--theme-border);
  border-radius: 8px;
  padding: 7px 10px;
  background: var(--theme-surface);
  color: var(--theme-text);
  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
}

.tenant-footer-column h4,
.tenant-footer-contact h4 {
  margin: 0 0 12px;
  color: var(--theme-text);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 14px;
}

.tenant-footer-links-grid {
  display: grid;
  gap: 8px;
}

.tenant-footer-links-grid :is(button, a) {
  justify-self: start;
  border: 0;
  background: transparent;
  color: var(--theme-text-soft);
  cursor: pointer;
  padding: 0;
  font-weight: 800;
  text-align: left;
  text-decoration: none;
}

.tenant-footer-links-grid :is(button, a):hover {
  color: var(--theme-primary);
}

.tenant-footer-contact {
  display: grid;
  gap: 10px;
  align-content: start;
}

.tenant-footer-contact p {
  margin: 0;
  color: var(--theme-text-soft);
  line-height: 1.6;
}

.tenant-language-pill {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--theme-border);
  border-radius: 999px;
  padding: 7px 10px;
  background: var(--theme-surface-2);
}

.tenant-language-pill strong {
  color: var(--theme-text);
}

.tenant-footer-bottom {
  max-width: 980px;
  margin: 26px auto 0;
  border-top: 1px solid var(--theme-border);
  padding-top: 16px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  color: var(--theme-text-soft);
}

.tenant-footer-bottom p {
  margin: 0;
}

.tenant-footer-bottom :is(button, a) {
  border: 0;
  background: transparent;
  color: var(--theme-text-soft);
  font-weight: 900;
  cursor: pointer;
  text-decoration: none;
}

.tenant-footer-bottom :is(button, a):hover {
  color: var(--theme-primary);
}

@media (max-width: 900px) {
  .tenant-site-header-inner {
    grid-template-columns: 1fr;
    justify-items: center;
    padding: 14px 0;
  }

  .tenant-site-brand,
  .tenant-site-cta {
    justify-self: center;
  }

  .tenant-footer-grid {
    grid-template-columns: 1fr;
    text-align: center;
    justify-items: center;
  }

  .tenant-footer-contact {
    justify-items: center;
  }

  .tenant-footer-links-grid button {
    justify-self: center;
  }

  .tenant-footer-bottom {
    justify-content: center;
    text-align: center;
  }
}
